//! `wm` — композитор окон VOID (Веха 117, [[0007-graphics-native-compositor]]).
//!
//! ```text
//!   клиент ─рисует в свою память─→ obj_put ─content-id─→ ATTACH+COMMIT ─→ композитор
//!   мышь/клавиши ─→ композитор ─→ событие ОКНУ под курсором (отложенный ответ)
//!   композитор ─→ damage-прямоугольники ─→ фреймбуфер
//! ```
//!
//! ## Что здесь принципиального
//!
//! - **Окно — это буфер-ОБЪЕКТ плюс право звать нас**, а не участок чужой памяти
//!   ([[0018-gpu-ladder]]). Клиент называет content-id; мы читаем объект ОДИН РАЗ и держим у
//!   себя копию. Пока содержимое не менялось, повторный `commit` не стоит ничего: content-id
//!   тот же — перечитывать нечего.
//! - **Двигает окна композитор.** Перемещение не трогает клиента вообще: его пиксели уже у нас.
//!   Это и есть правило ADR 0016 «анимируем трансформации, а не содержимое» — здесь оно не
//!   пожелание, а следствие устройства.
//! - **Рисуем по damage, и ровно раз за оборот цикла.** Кадр никогда не перерисовывается целиком:
//!   закрашиваются только изменившиеся прямоугольники (старое и новое место окна, содержимое,
//!   курсор). События их лишь ОТМЕЧАЮТ ([`Wm::damage`]), рисует один [`Wm::flush`] в конце
//!   оборота — иначе пачка из тридцати событий мыши означала бы тридцать перерисовок, и рука
//!   обгоняла бы экран (Веха 120.2).
//! - **Рамки рисуем МЫ** (server-side decorations). Так у всех окон один вид без единой строчки
//!   в приложениях — ровно то, ради чего затевался общий тулкит (ADR 0016).
//! - **Обои и бар — КЛИЕНТЫ, а не наши поля** (Веха 139, [[layers]]). Поверхность слоя
//!   ([`win::OP_LAYER`]) — то же окно (`Win` с `layer: Some(…)`), только место ей назначает
//!   якорь, а не раскладка, стопка берётся из слоя, и оформления у неё нет. Иначе композитор
//!   обязан был бы уметь читать store и разбирать PNG — в программе, где лежат буферы ВСЕХ окон.
//!
//! ## Чего здесь пока нет
//!
//! Список писался Вехой 121 и с тех пор вычерпан весь: анимации пришли Вехой 125, плитка запуска
//! — 147, буфер обмена — 150, перетаскивание — 150.1. Оставлять его пустым незачем, а вычёркивать
//! по одному было бы враньём о том, чего стоила каждая строка; чего нет СЕЙЧАС, перечисляет
//! [[known-gaps]].

#![no_std]
#![no_main]

extern crate alloc;

use alloc::string::String;
use alloc::vec;
use alloc::vec::Vec;

use void_user as sys;
use void_user::win;

// Веха 148.3 — НИЖНИЙ ярус тулкита: холст, прямоугольник, тема и кривая движения. Верхние два
// (`Ui` с виджетами и `app` с циклом) композитору не нужны и не используются: он не клиент
// самому себе. Раньше это значило «своё всё» — свой холст плитки, своя палитра, своя кривая, — и
// три цвета из пяти успели разойтись молча.
#[allow(dead_code)]
#[path = "../ui/mod.rs"]
mod ui;

use ui::{Rect, Rgba, Theme};

// ─── КООРДИНАТНЫЕ ПРОСТРАНСТВА (Веха 149.2) ──────────────────────────────────
//
// У композитора их два, и различаются они на прокрутку ленты:
//
//   ЛЕНТА  — бесконечная полоса, по которой ездит экран. В ней живёт раскладка: колонки, места
//            окон, ширина. Координата окна в ленте не меняется от того, куда человек уехал.
//   ЭКРАН  — то, что видит человек. В нём приходит мышь, в нём считается damage, в него пишутся
//            пиксели. `экран = лента − scroll_x`.
//
// Пока оба были голыми `i32`, каждое новое место решало заново, в каком из них оно находится, —
// и трижды решило неверно, причём каждый раз это выглядело поломкой совсем другого свойства:
//
//   1. damage-прямоугольник клиента считался в ленте — «новое окно рождается ЧЁРНЫМ»
//      (запись сохранена в коде рядом с `OP_COMMIT`);
//   2. `damage_chrome` помечал рамку в ленте — наблюдаемой поломки собрать не удалось (Веха 149);
//   3. точка указателя называлась клиенту в ленте — «кнопки нажимаются там, где окно было
//      раньше» (Веха 149.1).
//
// Третий раз — это уже не невнимательность, а свойство записи. Поэтому пространство стало частью
// ТИПА: `At<Strip>` и `At<Screen>` — разные типы, вычесть один из другого молча нельзя, а перевод
// [`At::to_screen`] требует назвать прокрутку вслух. Стоит это ноль байтов: `PhantomData`
// исчезает при сборке, а методы те же самые.

use core::marker::PhantomData;

/// Лента: полоса раскладки, по которой ездит экран.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct Strip;
/// Экран: пиксели, мышь, damage.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct Screen;

/// Прямоугольник, знающий, в каком пространстве он назван.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct At<S> {
    r: Rect,
    _s: PhantomData<S>,
}

/// Точка — то же самое. Курсор живёт в экране, место окна — в ленте, и сложить их нельзя.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct Pt<S> {
    x: i32,
    y: i32,
    _s: PhantomData<S>,
}

impl<S> At<S> {
    fn new(x: i32, y: i32, w: i32, h: i32) -> At<S> {
        At { r: Rect::new(x, y, w, h), _s: PhantomData }
    }

    fn of(r: Rect) -> At<S> {
        At { r, _s: PhantomData }
    }

    /// Голый прямоугольник. Осознанный выход из типа: нужен там, где дальше идут пиксели, а у
    /// пикселей пространства уже нет — они всегда экранные.
    fn rect(self) -> Rect {
        self.r
    }

    fn offset(self, dx: i32, dy: i32) -> At<S> {
        At::of(self.r.offset(dx, dy))
    }

    fn inset(self, n: i32) -> At<S> {
        At::of(self.r.inset(n))
    }

    fn union(self, o: At<S>) -> At<S> {
        At::of(self.r.union(o.r))
    }

    fn intersect(self, o: At<S>) -> At<S> {
        At::of(self.r.intersect(o.r))
    }

    fn subtract(self, hole: At<S>) -> [At<S>; 4] {
        self.r.subtract(hole.r).map(At::of)
    }

    fn contains(self, p: Pt<S>) -> bool {
        self.r.contains(p.x, p.y)
    }

    fn is_empty(self) -> bool {
        self.r.is_empty()
    }
}

impl<S> Pt<S> {
    fn new(x: i32, y: i32) -> Pt<S> {
        Pt { x, y, _s: PhantomData }
    }

    /// Прямоугольник от этой точки — курсор и прочее, что «шириной с картинку».
    fn rect(self, w: i32, h: i32) -> At<S> {
        At::new(self.x, self.y, w, h)
    }
}

impl At<Strip> {
    /// Лента → экран. Прокрутку приходится назвать вслух — в этом весь смысл.
    fn to_screen(self, scroll: i32) -> At<Screen> {
        At::of(self.r.offset(-scroll, 0))
    }
}

impl At<Screen> {
    /// Экран → лента. Нужно ровно в одном месте: лента ОБЪЯВЛЕНА начинающейся там же, где экран
    /// (прокрутка меряется оттуда), и раскладка отсчитывает окна от рабочей области.
    fn to_strip(self, scroll: i32) -> At<Strip> {
        At::of(self.r.offset(scroll, 0))
    }
}

/// Цвет темы в тройку, которой рисует композитор (альфа у него своя, попиксельная).
fn tri(c: Rgba) -> (u8, u8, u8) {
    (c.r, c.g, c.b)
}

/// Кадр 1280×800 RGBA (4 МиБ) + копии содержимого окон.
#[global_allocator]
static ALLOC: sys::heap::Heap<{ 64 * 1024 * 1024 }> = sys::heap::Heap::new();

/// Окно фреймбуфера в нашем адресном пространстве (как у `term`).
const FB_VA: usize = 0x5000_0000;

/// Отметка сборки — коммит и дата, подставляет `build.rs`. Печатается на старте.
///
/// Раньше здесь стояла константа с номером вехи — и она соврала при первой же возможности:
/// следующая веха её не подняла, а владелец дважды перезаписал флешку, выясняя, почему система
/// «старая». Она была новая. Число, которое надо не забыть поднять руками, однажды не поднимут.
const BUILD: &str = env!("VOID_BUILD");

// ── вид (ADR 0016: один палитра-источник, приложения цветов не знают) ────────
//
// Веха 148.3 — источник этот наконец ОДИН: цвета приезжают из `ui::Theme`, то есть из конфига
// поколения. До неё здесь стояли свои константы под тем же заголовком про «один источник», и
// заголовок был неправдой: `ui("accent", "#ff0000")` перекрашивал панель, а рамку фокуса, фон
// стола и плитку запуска не трогал вовсе.

// ── анимации (Веха 125) ──────────────────────────────────────────────────────
//
// Требование владельца: «чтобы чувствовалось, будто ты сам двигаешь эту камеру» — резкое
// ускорение вначале и плавное торможение. Это ease-out: движение начинается на полной скорости
// и гасится к цели. Обратная кривая (плавный старт) читается как «система подумала и поехала»,
// а нужно «поехало сразу, а доводит уже само».

/// Сколько длится ПЕРЕЕЗД окна — основа всех сроков (Веха 142: настраивается,
/// `desktop anim <мс>` из конфига поколения). Остальные три считаются от него теми же долями,
/// какими стояли до настройки: открытие чуть короче переезда, закрытие ещё короче, обзор равен
/// переезду. Долями, а не четырьмя числами в конфиге, потому что соотношения между ними — это
/// решение о виде системы, а не вкус: рассогласовать их значит получить рябь, а не свою настройку.
const ANIM_MS: u64 = 360;
/// Доли от [`Wm::anim`] в процентах.
const D_OPEN: u64 = 84;
const D_CLOSE: u64 = 71;
const D_OV: u64 = 100;
/// Потолок: анимация длиннее секунды — это уже не «плавно», а «система задумалась».
const ANIM_MAX: u64 = 1000;

/// Бюджет ОДНОГО кадра, пока что-то движется: 16 мс — это 60 кадров в секунду, темп экрана.
///
/// Именно бюджет, а не пауза. Пауза здесь и стояла (8 мс «с запасом»), и прибавлялась она к
/// времени самого кадра, а не включала его. Замер периода между кадрами: пауза 8 мс → 20.0 мс
/// (50 кадров в секунду), пауза 16 мс → 25.5 мс (39!), бюджет 16 мс → 19.9 мс (50). То есть
/// «поставить паузу побольше, чтобы не жечь процессор» просто роняет темп: чем тяжелее кадр, тем
/// сильнее промах. Спим ОСТАТОК бюджета — и период перестаёт зависеть от стоимости кадра.
///
/// Шестидесяти кадров сегодня всё равно не выходит, и упирается это НЕ в паузу (замер того же
/// прогона: отрисовка кадра 8.8 мс, просили поспать 6.6, проспали 10.6 — ядро пересыпает на 4 мс).
/// Оба потолка записаны в [[known-gaps]]; здесь важно, что при удешевлении кадра темп сам дойдёт
/// до 60 и там остановится, а не разгонится вхолостую.
const FRAME_NS: u64 = 16_000_000;

/// Веха 142 — перетаскивание окна мышью с зажатым Super.
///
/// Хранится накопленный сдвиг, а не «схваченная точка»: в тайлинге окно не кладут в координату,
/// его переставляют местами. Как только накопится шаг ([`Wm::drag_steps`]), выполняется обычное
/// действие раскладки, а накопитель уменьшается на этот шаг — остаток продолжает копиться, и
/// медленное движение не теряет ход.
struct Drag {
    /// ПКМ — меняем ширину колонки; иначе переставляем окно.
    resize: bool,
    ax: i32,
    ay: i32,
}

/// Веха 151 — идёт СБОР СЕАНСА: разослали «сохранись», ждём ответов.
///
/// Сбор существует потому, что ответы приходят не сразу: клиент спит в `OP_EVENT`, его надо
/// разбудить, дать ему записать своё и дождаться слова. Всё это время композитор продолжает жить
/// — рисовать, отвечать другим, — иначе «сохранение» выглядело бы как зависший экран.
struct Saving {
    /// Скольких спросили. Ответили все — дальше ждать нечего.
    asked: usize,
    /// Сколько уже ответило. Сами ответы лежат в окнах ([`Win::run`]).
    got: usize,
    /// До какого времени ждём молчащих (монотонные нс).
    until: u64,
    /// Гасить ли машину, когда допишем. Сохранение бывает и просто так — по просьбе человека.
    power: bool,
}

/// Сколько ждём ответов на «сохранись» (Веха 151). Полсекунды — это не про скорость программ, а
/// про терпение человека, который нажал «выключить»: молчащая программа не имеет права держать
/// машину включённой, и цена её молчания — только её собственное невосстановление.
const SAVE_WAIT_NS: u64 = 500_000_000;

/// Веха 151.1 — как часто СВЕРЯТЬ сеанс с тем, что на экране. Не «как часто писать»: пишем только
/// при РАЗНИЦЕ, а на неподвижном столе её нет, и диск не трогается вовсе.
///
/// Пять секунд — потому что мерой здесь человек, а не машина: за пять секунд он успевает
/// передвинуть окно или перейти на другой стол, но не успевает сделать этого столько раз, чтобы
/// накопились лишние коммиты. Веха 33 отучила систему от привычки писать на каждый чих, и
/// заводить эту привычку заново ради раскладки было бы обидно.
const SESSION_TICK_NS: u64 = 5_000_000_000;

/// Веха 150.1 — ГРУЗ, который сейчас тащат мышью ([`win::OP_DRAG`]).
///
/// Здесь, как и у буфера обмена, только ИМЯ содержимого: байты лежат в store, композитор их не
/// возит. Корень `drag/current` на них держит он же — по той же причине, что и у буфера: без
/// корня объект недостижим, и сборка мусора store забрала бы груз прямо из-под руки.
struct Payload {
    kind: u8,
    id: [u8; 32],
    /// Что написано под курсором, пока тащат. Подпись назвал источник; содержимым она быть не
    /// обязана — тащат мегабайт, а подписан он именем.
    label: String,
    /// Кто начал. Нужен ровно для одного: в СВОЁ же окно не роняем. Отпустить кнопку там же, где
    /// нажал, — это отменённое перетаскивание, а не передача самому себе.
    from: u32,
}

/// Веха 168 — одно уведомление. Имя отправителя здесь уже проверенное: его назвало ядро.
struct Note {
    id: u32,
    level: u8,
    from: String,
    title: String,
    text: String,
}

/// Сколько уведомлений храним. Список копится сам собой, а читает человек последние.
const NOTES_MAX: usize = 32;
/// Сколько живёт всплывашка. Три секунды — столько, чтобы прочесть две строки и не больше:
/// уведомление, висящее дольше, начинает мешать тому, ради чего человек сидит за экраном.
const TOAST_NS: u64 = 3_000_000_000;
/// Поля всплывашки и её скругление — то же, что у окон, только вдвое мельче: карточка меньше
/// окна, и радиус окна на ней выглядел бы каплей.
const TOAST_PAD: i32 = 10;
const TOAST_RAD: i32 = RADIUS / 2;

/// Веха 169.1 — потолок памяти под СНИМКИ окон, восстановленных из сеанса. Восьмая часть кучи
/// композитора: снимок это кадр окна целиком, и десяток окон в пол-экрана съедает её всю.
const SNAP_BUDGET: usize = 8 * 1024 * 1024;

/// Сколько кадров помнит счётчик. Четыре секунды при шестидесяти в секунду: столько длится
/// то, на что смотрят («открой меню», «перетащи окно»), и столько же нужно, чтобы увидеть РЫВОК.
/// Среднее за минуту его прячет, а именно рывок и ищут.
const FRAMES_KEPT: usize = 256;

/// Веха 168.3 — **счёт кадров ЭКРАНА** (см. [`win::OP_FRAMES`]).
///
/// Считает не намерения клиентов, а записи во фреймбуфер: пиксель попадает на экран ровно в
/// [`Wm::flush`], и другого места нет. Стоит это два чтения часов на кадр — в кадре их и так
/// десятки, а без них «подлагивает» остаётся ощущением, которое нечем ни подтвердить, ни
/// опровергнуть.
struct Frames {
    /// Кольцо: промежуток, сборка, вывод (мкс), пиксели, коммиты, «шло движение» — свежие по кругу.
    ring: [(u32, u32, u32, u32, u32, u32); FRAMES_KEPT],
    /// Куда писать следующий.
    head: usize,
    /// Сколько записано за всё время (по нему видно, что кольцо ещё не полное).
    total: u64,
    /// Когда кончился прошлый кадр.
    last: u64,
    /// Сколько клиентских кадров приехало ВСЕГО и сколько с прошлого кадра экрана.
    commits: u64,
    since: u32,
}

impl Frames {
    fn new() -> Frames {
        Frames {
            ring: [(0, 0, 0, 0, 0, 0); FRAMES_KEPT],
            head: 0,
            total: 0,
            last: 0,
            commits: 0,
            since: 0,
        }
    }

    /// Записать кадр. `t0` — начало, `mid` — конец сборки, `t1` — конец вывода, `busy` — вёл ли
    /// композитор собственное движение (переезд окна, лента, всплывашка).
    fn put(&mut self, t0: u64, mid: u64, t1: u64, px: u32, busy: bool) {
        let gap = if self.last == 0 { 0 } else { t1.saturating_sub(self.last) };
        self.ring[self.head] = (
            (gap / 1000) as u32,
            (mid.saturating_sub(t0) / 1000) as u32,
            (t1.saturating_sub(mid) / 1000) as u32,
            px,
            core::mem::take(&mut self.since),
            busy as u32,
        );
        self.head = (self.head + 1) % FRAMES_KEPT;
        self.total += 1;
        self.last = t1;
    }

    /// Ответ на [`win::OP_FRAMES`]: заголовок и кольцо от старого к новому.
    fn encode(&self, w: u32, h: u32) -> Vec<u8> {
        let n = (self.total as usize).min(FRAMES_KEPT);
        let mut out = Vec::with_capacity(28 + n * 24);
        out.extend_from_slice(&(n as u32).to_le_bytes());
        out.extend_from_slice(&w.to_le_bytes());
        out.extend_from_slice(&h.to_le_bytes());
        out.extend_from_slice(&self.total.to_le_bytes());
        out.extend_from_slice(&self.commits.to_le_bytes());
        for k in 0..n {
            let i = (self.head + FRAMES_KEPT - n + k) % FRAMES_KEPT;
            let r = self.ring[i];
            for v in [r.0, r.1, r.2, r.3, r.4, r.5] {
                out.extend_from_slice(&v.to_le_bytes());
            }
        }
        out
    }
}

/// Веха 168.2 — ВСПЛЫВАШКА: что висит, когда появилась и когда погаснет.
///
/// Время появления пришлось запомнить ради движения: до этой вехи всплывашка возникала целиком и
/// целиком же исчезала. Уведомление — единственное, что система говорит человеку без спроса, и
/// возникнуть рывком посреди работы для него слишком много.
#[derive(Clone, Copy)]
struct Toast {
    id: u32,
    at: u64,
    until: u64,
}
/// Сколько байт списка отдаём за раз. Потолок нужен не «на всякий случай»: ответ едет через
/// приёмный буфер спрашивающего, и то, что в него не влезло, он не увидит вовсе.
const NOTES_REPLY_MAX: usize = 8 * 1024;

/// Веха 142.1 — переезд между СТОЛАМИ: старая лента уходит, новая приходит по вертикали.
///
/// Хранятся окна УХОДЯЩЕГО стола и его сдвиг ленты: после обмена лент `self.scroll_x` уже чужой,
/// и рисовать по нему старые окна значило бы сдвинуть их вбок на ровном месте.
struct Slide {
    ids: Vec<u32>,
    scroll: i32,
    /// +1 — новый стол приходит СНИЗУ (ушли на стол с бо́льшим номером), −1 — сверху.
    dir: i32,
    /// Веха 145.1 — ОТКУДА едет приходящая лента (пикселей по вертикали); едет она всегда в 0.
    ///
    /// Здесь стояло смещение, посчитанное от НАПРАВЛЕНИЯ: приходящая лента начинала ровно за
    /// экраном (`dir * h`) независимо от того, где картинка находится сейчас. Пока переезд
    /// доигрывал до конца, разницы не было; стоило переключить стол ПОСРЕДИ движения — и новая
    /// лента прыгала на целый экран от того места, где её только что видели, а потом ехала
    /// «мимо» стола (нашёл владелец: 1 → 2 → сразу обратно). Классическая ошибка «анимация как
    /// приращение»: у движения обязаны быть НАЧАЛО и КОНЕЦ, а не шаг в сторону.
    from: i32,
    at: u64,
    dur: u64,
}

impl Slide {
    /// Где приходящая лента ПРЯМО СЕЙЧАС. Уходящая всегда ровно на экран дальше по ходу.
    fn offset(&self, now: u64) -> i32 {
        if self.dur == 0 {
            return 0;
        }
        let t = ((now.saturating_sub(self.at)) * 1024 / self.dur).min(1024) as i32;
        lerp(self.from, 0, ease_out(t))
    }
}

/// Насколько окно «поджато» в начале открытия и в конце закрытия — в 1/256 от размера.
/// Небольшое (как в niri): большое превращает появление окна в аттракцион.
const POP: i32 = 232;

/// Ease-out кубический: `1 − (1−t)³`, всё в 1/1024.
// Кривая и доля пути — из тулкита (`ui::anim`). Копия жила здесь до Вехи 148.3, и в самом
// тулките рядом с ней стояла честная пометка «копия формулы композитора: две кривые дали бы две
// разные системы». Теперь кривая одна.
use ui::anim::{ease_out, lerp};

/// То, ЧТО РИСУЕТСЯ, — в отличие от того, что назначила раскладка. Между ними и живёт анимация.
#[derive(Clone, Copy, PartialEq)]
struct Shown {
    x: i32,
    y: i32,
    w: i32,
    h: i32,
    /// Непрозрачность в 1/256.
    a: u32,
}

impl Shown {
    /// Поджатый к центру вариант — начало открытия и конец закрытия.
    /// Поджатое состояние — начало открытия и конец закрытия.
    ///
    /// Веха 179 — **непрозрачное**. Раньше здесь стояло `a: 0`, то есть окно ещё и проявлялось;
    /// это противоречит языку движения оболочки («ничего не появляется прозрачностью, вещество
    /// меняет форму» — Веха 165) и стоит непозволительно дорого. Полупрозрачный пиксель не
    /// попадает ни в быструю строку, ни в короткий путь общей: он идёт через `blend` с
    /// делением на канал. Замер на стенде: сборка кадра во время открытия и закрытия **7,8 мс**
    /// при 470 тысячах перерисовываемых пикселей — при бюджете кадра 16 мс. На машине владельца
    /// (Sandy Bridge) того же запаса нет, и это ровно то «подлагивание», которое он увидел.
    ///
    /// Ту же ошибку и по той же причине уже чинили в панели (Веха 165, `void-motion-language`):
    /// «проявление ещё и жгло кадр делением на пиксель». Здесь оно жгло вдвое больше — двести
    /// тысяч пикселей карточки лаунчера против почти полумиллиона у окна.
    fn popped(&self) -> Shown {
        let (w, h) = (self.w * POP / 256, self.h * POP / 256);
        Shown { x: self.x + (self.w - w) / 2, y: self.y + (self.h - h) / 2, w, h, a: 256 }
    }
    fn mix(&self, to: &Shown, p: i32) -> Shown {
        Shown {
            x: lerp(self.x, to.x, p),
            y: lerp(self.y, to.y, p),
            w: lerp(self.w, to.w, p).max(2 * BORDER + 2),
            h: lerp(self.h, to.h, p).max(2 * BORDER + 2),
            a: lerp(self.a as i32, to.a as i32, p).clamp(0, 256) as u32,
        }
    }
    /// Прямоугольник рамки — В ЛЕНТЕ. У слоя лента не едет (см. [`Win::place`]).
    fn rect(&self) -> At<Strip> {
        At::new(self.x, self.y, self.w, self.h)
    }
}

/// Толщина рамки и радиус скругления (Веха 124 — вид взят из noctalia владельца).
///
/// ТИТУЛЬНОЙ ПОЛОСЫ БОЛЬШЕ НЕТ. В тайлинге она не несла ничего: окно не таскают мышью, крестика
/// нет, а имя программы и так видно по содержимому. Взамен — заметная рамка (она же индикатор
/// фокуса) и крупное скругление. Побочно исчезло мерцание заголовка: единственные пиксели,
/// которые писались дважды за кадр, были как раз его глифы.
const BORDER: i32 = 2;
const RADIUS: i32 = 12;

// ── раскладка (Веха 119, [[wm-keys]]) ────────────────────────────────────────
//
// Умолчания взяты из рабочего конфига владельца (niri): те же клавиши, те же смыслы. Схема
// живёт в КОНФИГЕ поколения строками `bind wm <клавиши> <действие>` — как у терминала с Вехи
// 100; зашитая здесь нужна ровно затем, чтобы система поднималась на пустом конфиге.
//
// Крестика закрытия нет и не будет: окно закрывает `Super+Q` (решение владельца).
const DEFAULT_BINDS: &str = "\
bind wm Super+Return spawn-term
bind wm Super+D launcher-toggle
bind wm Super+Q close-window
bind wm Super+H focus-column-left
bind wm Super+L focus-column-right
bind wm Super+Up focus-window-up
bind wm Super+Down focus-window-down
bind wm Super+Shift+H move-column-left
bind wm Super+Shift+L move-column-right
bind wm Super+Shift+Up move-window-up
bind wm Super+Shift+Down move-window-down
bind wm Super+BracketLeft move-to-column-left
bind wm Super+BracketRight move-to-column-right
bind wm Super+R width-next
bind wm Super+Equal width-plus
bind wm Super+Minus width-minus
bind wm Super+F maximize-column
bind wm Super+Shift+S save-session
bind wm Super+Shift+Q poweroff
bind wm Super+Tab toggle-overview
bind wm Super+Z switch-layout
bind wm Escape close-overview
bind wm Return close-overview
bind wm Super+1 workspace-1
bind wm Super+2 workspace-2
bind wm Super+3 workspace-3
bind wm Super+4 workspace-4
bind wm Super+5 workspace-5
bind wm Super+6 workspace-6
bind wm Super+7 workspace-7
bind wm Super+8 workspace-8
bind wm Super+9 workspace-9
bind wm Super+Shift+1 move-to-workspace-1
bind wm Super+Shift+2 move-to-workspace-2
bind wm Super+Shift+3 move-to-workspace-3
bind wm Super+Shift+4 move-to-workspace-4
bind wm Super+Shift+5 move-to-workspace-5
bind wm Super+Shift+6 move-to-workspace-6
bind wm Super+Shift+7 move-to-workspace-7
bind wm Super+Shift+8 move-to-workspace-8
bind wm Super+Shift+9 move-to-workspace-9
bind wm Super+Shift+Q quit
";

/// Код клавиши Super — тот же, что кладёт ядро (`ps2.rs::keysym`).
use win::sym::SUPER as SYM_SUPER;

/// Разобранная строка раскладки.
struct Bind {
    sym: u16,
    mods: u8,
    action: String,
}

/// `"Super+Shift+Q"` → (код клавиши, маска). Имена модификаторов — как в конфиге niri.
fn parse_combo(tok: &str) -> Option<(u16, u8)> {
    let mut mods = 0u8;
    let mut last = tok;
    for part in tok.split('+') {
        match part {
            "Super" | "Mod" => mods |= win::modk::SUPER,
            "Shift" => mods |= win::modk::SHIFT,
            "Ctrl" | "Control" => mods |= win::modk::CTRL,
            "Alt" => mods |= win::modk::ALT,
            other => last = other,
        }
    }
    let sym = match last {
        "Return" | "Enter" => win::sym::RETURN,
        "Escape" | "Esc" => win::sym::ESCAPE,
        "Tab" => win::sym::TAB,
        "Backspace" => win::sym::BACKSPACE,
        "Delete" => win::sym::DELETE,
        "Left" => win::sym::LEFT,
        "Right" => win::sym::RIGHT,
        "Up" => win::sym::UP,
        "Down" => win::sym::DOWN,
        "Home" => win::sym::HOME,
        "End" => win::sym::END,
        "PageUp" => win::sym::PAGE_UP,
        "PageDown" => win::sym::PAGE_DOWN,
        "Space" => b' ' as u16,
        // Имена как в конфиге niri: `=` и `-` в строке аккорда путались бы с разделителем `+`.
        "Equal" => b'=' as u16,
        "Minus" => b'-' as u16,
        "BracketLeft" => b'[' as u16,
        "BracketRight" => b']' as u16,
        s => {
            let c = s.chars().next()?;
            if s.chars().count() != 1 {
                return None;
            }
            // Клавиша именуется своим НЕсдвинутым символом: `Super+L` и буква `l` — про одну и
            // ту же клавишу, и различать их регистром значило бы завести две раскладки.
            (c.to_ascii_lowercase() as u32) as u16
        }
    };
    Some((sym, mods))
}

/// Номер рабочего стола из имени действия (`workspace-3` → 2). Считаем от нуля внутри, от
/// единицы снаружи: на клавиатуре нет нулевого стола.
fn digit(name: &str) -> Option<usize> {
    let d = name.rsplit('-').next()?.parse::<usize>().ok()?;
    (1..=SPACE_KEYS).contains(&d).then_some(d - 1)
}

/// Собрать раскладку: строки `bind wm …` из конфига поколения, иначе зашитая схема.
/// Второе значение — ОТКУДА она взялась.
///
/// Правило то же, что у терминала (Веха 100): хоть один `bind` в конфиге — и схема задаётся
/// ЦЕЛИКОМ оттуда. Иначе клавишу нельзя было бы отвязать. Но у правила есть цена, и она
/// всплыла на живом человеке (Веха 121.1): конфиг, посеянный ДО появления новых действий,
/// молча отменяет их все — раскладка есть, она просто старая. Поэтому источник теперь
/// называется вслух: «шесть сочетаний из конфига» при восемнадцати зашитых — это диагноз.
fn load_binds(text: &str) -> (Vec<Bind>, bool) {
    let out = parse_binds(text);
    if out.is_empty() {
        (parse_binds(DEFAULT_BINDS), false)
    } else {
        (out, true)
    }
}

/// Веха 139 — имя картинки для обоев: строка `desktop wallpaper <объект store>` из конфига
/// поколения. Ничего нет — обоев нет, и это нормальный вид системы, а не отсутствие настройки.
///
/// Хвост строки берём ЦЕЛИКОМ, не разбивая по пробелам: имя корня в store — произвольная строка,
/// и пробел в ней не наше дело. Именно из-за разбора по пробелам имя нельзя было передать через
/// `arg:` в самом конфиге (`init::apply_with` режет строку на токены) — здесь конец пути, и
/// резать его второй раз незачем.
fn wallpaper_name(text: &str) -> Option<&str> {
    void_conf::get(text, "desktop", "wallpaper")
}

/// Веха 155/157 — КОМУ композитор отдаёт свои права: строки `desktop <право> <имя программы>`
/// в конфиге поколения. Ничего нет — не отдаёт никому, и это правильный вид системы по умолчанию.
///
/// Решение здесь — ДЕКЛАРАЦИЯ ВЛАДЕЛЬЦА, а не политика композитора: тот лишь проверяет, тот ли
/// проситель, и спрашивает об этом ядро (см. [`win::OP_GRANT`]). Имя, а не content-id, потому что
/// хэш образа меняется с каждой пересборкой — сверять его в конфиге значило бы править конфиг
/// после каждой сборки; имя же процесса ядро берёт из имени программы в store, и подделать его
/// нельзя, не подменив саму программу (а это уже право писать в store).
///
/// Прав раздаётся два, и оба — по одной причине: ребёнок наследует копию таблицы родителя, поэтому
/// «выдать одному окну» без пометки `!` значит выдать ВСЕМ окнам.
/// - `sysview` (вид 13) — видеть процессы и отзывать их права (диспетчер задач);
/// - `power` (вид 10) — выключить машину. Нужен панели (кнопка выключения) и шеллу (`poweroff`);
///   до Вехи 154 они получали его наследством от композитора вместе со ВСЕМИ окнами.
///
/// Одно право можно отдать НЕСКОЛЬКИМ программам — строк с одним ключом бывает много.
/// Веха 166 — свой КАНАЛ К СЕРВЕРУ СЕТИ среди стартовых прав.
///
/// По адресату, а не по виду: вид у всех эндпоинтов один (4), и у композитора их несколько —
/// файловый сервер, свои клиенты. Кто из них сервер сети, знает ядро: `cap_info_ex` отдаёт
/// процесс на том конце, а имя процесса — обзор (`sysview`). Имя, а не позиция в конфиге:
/// порядок прав в строке — дело владельца, и привязываться к нему значит ломаться от
/// перестановки (тот же довод, что у `sysview` строкой выше).
fn find_net_ep() -> usize {
    let sysview = match sys::start_cap_of_kind(13) {
        Some((c, _)) => c,
        None => return sys::NO_CAP,
    };
    let mut buf = alloc::vec![0u8; sys::PROC_REC * 48];
    let Some(total) = sys::proc_list(sysview, &mut buf) else { return sys::NO_CAP };
    let mut net = u16::MAX;
    for k in 0..total.min(buf.len() / sys::PROC_REC) {
        let r = &buf[k * sys::PROC_REC..(k + 1) * sys::PROC_REC];
        let nlen = (r[7] as usize).min(24);
        if &r[40..40 + nlen] == b"net-srv" {
            net = u16::from_le_bytes([r[0], r[1]]);
            break;
        }
    }
    if net == u16::MAX {
        return sys::NO_CAP;
    }
    (0..32)
        .map(sys::start_cap)
        .take_while(|&c| c != sys::NO_CAP)
        .find(|&c| matches!(sys::cap_info_ex(c), Some((4, _, aux)) if aux == net))
        .unwrap_or(sys::NO_CAP)
}

fn grant_policy(text: &str) -> Vec<(u8, String)> {
    let mut out = Vec::new();
    for e in void_conf::of(text, "desktop") {
        let kind = match e.key() {
            "sysview" => 13,
            "power" => 10,
            // Веха 166 — `desktop net <имя>`: канал к серверу сети. Диспетчеру задач он нужен
            // под выключатель сети, и без строки конфига его не получит никто.
            "net" => 4,
            _ => continue,
        };
        let who = e.tail().trim();
        if !who.is_empty() {
            out.push((kind, String::from(who)));
        }
    }
    out
}

/// Веха 140 — просит ли конфиг поколения ПАНЕЛЬ: строка `desktop bar on`.
///
/// Выключателем, а не высотой: высота панели следует за шрифтом (8×16 плюс поля), и вынести её в
/// конфиг значило бы дать человеку рассогласовать одно с другим. Захочется другой кегль — тогда и
/// появится настройка, сразу для обоих чисел.
fn bar_wanted(text: &str) -> bool {
    void_conf::on(text, "desktop", "bar")
}

/// Веха 172 — **ЧТО ОТКРЫВАЕТСЯ ПРИ ВХОДЕ**: строки `autostart` конфига поколения.
///
/// Раньше это ехало аргументами процесса (`shell wm … arg:term` — их складывает `init::apply`), и
/// у такого способа два изъяна, оба вылезли на живом ISO. Во-первых, аргументы — механизм ЯДРА:
/// чтобы убрать терминал со стола, человеку надо было знать про argv и найти его посреди списка
/// ПРАВ композитора. Во-вторых, конфиг поколения разбирается по пробелам, поэтому имя с
/// аргументом (`img wall`) доезжало сюда двумя словами и запускало две несуществующие программы.
///
/// Строка `autostart` — обычная запись конфига: её видно в `sysdef`, её переживает `rebuild`, её
/// откатывает `switch` вместе с поколением. И она же — самое короткое объяснение того, как в
/// VOID вообще всё настраивается; ровно это и показывает окно «добро пожаловать», которое здесь
/// стоит по умолчанию.
///
/// Пустой список значит «в конфиге не сказано» — тогда берём argv, как раньше: поколения,
/// собранные до этой вехи, лежат в store у людей и обязаны продолжать работать.
fn autostart(text: &str) -> Vec<String> {
    void_conf::of(text, "autostart")
        .flat_map(|e| e.words())
        .map(String::from)
        .collect()
}

fn parse_binds(text: &str) -> Vec<Bind> {
    let mut out = Vec::new();
    for e in void_conf::of(text, "bind") {
        // Первое поле `bind` — РЕЖИМ, и он же делит схемы: `wm` наша, `normal`/`pane` — терминала
        // (тот читает тот же текст и берёт свои).
        let mut w = e.words();
        if w.next() != Some("wm") {
            continue;
        }
        let (Some(combo), Some(action)) = (w.next(), w.next()) else { continue };
        if let Some((sym, mods)) = parse_combo(combo) {
            out.push(Bind { sym, mods, action: String::from(action) });
        }
    }
    out
}

/// Активное поколение конфига — тем же способом, каким его читает терминал.
/// Content-id, на который указывает корень store. `None` — корня нет.
fn read_root_id(scap: usize, name: &[u8]) -> Option<[u8; 32]> {
    let mut id = [0u8; 32];
    (sys::obj_get_root(scap, name, &mut id) == 32).then_some(id)
}

/// Веха 151 — content-id строкой в 64 знака. Обратно его читает `sys::obj_resolve` — то самое
/// правило «64 hex-знака значат content-id», которое Веха 148.6 свела в одно место.
fn hex32(id: &[u8; 32]) -> String {
    let mut s = String::with_capacity(64);
    for b in id {
        s.push_str(&alloc::format!("{:02x}", b));
    }
    s
}

/// Потолок на объект, который композитор согласен взять в память: снимок полного экрана —
/// 7.3 МиБ (1600×1200×4), и вдвое больше этого уже не снимок, а чужая ошибка.
const OBJ_MAX: usize = 16 * 1024 * 1024;

/// Прочитать объект ЦЕЛИКОМ. Длину спрашиваем первым же вызовом с пустым буфером: `obj_get_ex`
/// возвращает и «сколько влезло», и «сколько всего», — второе и есть ответ.
fn read_obj(scap: usize, id: &[u8; 32]) -> Option<Vec<u8>> {
    let (_, full) = sys::obj_get_ex(scap, id, &mut []);
    if full == 0 || full == usize::MAX || full > OBJ_MAX {
        return None;
    }
    let mut v = vec![0u8; full];
    let (got, _) = sys::obj_get_ex(scap, id, &mut v);
    (got == full).then_some(v)
}

/// Текст именованного корня целиком.
fn read_root_text(scap: usize, name: &[u8]) -> Option<String> {
    let id = read_root_id(scap, name)?;
    String::from_utf8(read_obj(scap, &id)?).ok()
}

/// Веха 151 — ОДНА ЗАПИСЬ СЕАНСА: где лежало окно и чем его вернуть.
struct Rec {
    space: usize,
    col: usize,
    width: usize,
    focus: bool,
    bw: i32,
    bh: i32,
    shot: Option<String>,
    run: String,
}

/// Разобрать строку `window <n> space <s> col <c> … run <командная строка>`.
///
/// Пары «имя значение» до слова `run`, дальше — хвост как есть. Именованные поля, а не порядок:
/// сеанс переживает перезагрузку, то есть его читает ЗАВТРАШНЯЯ версия композитора, и поле,
/// вставленное в середину, не должно менять смысл соседних.
fn parse_rec(e: &void_conf::Entry) -> Option<Rec> {
    let (head, run) = e.tail().split_once(" run ")?;
    let mut r = Rec {
        space: 0,
        col: 0,
        width: 1,
        focus: false,
        bw: 0,
        bh: 0,
        shot: None,
        run: String::from(run.trim()),
    };
    let mut it = head.split_whitespace();
    while let Some(k) = it.next() {
        let Some(v) = it.next() else { break };
        match k {
            "space" => r.space = v.parse().ok()?,
            "col" => r.col = v.parse().ok()?,
            "width" => r.width = v.parse().ok()?,
            "focus" => r.focus = v == "1",
            "bw" => r.bw = v.parse().ok()?,
            "bh" => r.bh = v.parse().ok()?,
            "shot" => r.shot = (v != "-").then(|| String::from(v)),
            // Поле от версии, которой мы не знаем: пропускаем молча. Отказаться от всей записи
            // из-за одного незнакомого слова значило бы потерять стол на ровном месте.
            _ => {}
        }
    }
    (!r.run.is_empty()).then_some(r)
}

/// Конфиг активного поколения: `system/current` → имя → `system/<имя>` → текст.
///
/// Веха 171 — **на каждом отказе говорит, на каком шаге он случился.** Раньше функция молча
/// возвращала `None`, а вызывающий так же молча брал умолчания: композитор поднимался без обоев,
/// без панели и с зашитой раскладкой — то есть выглядел работающим. Отличить «в конфиге так и
/// написано» от «конфиг не прочитан» было нельзя ничем, и на живом ISO это стоило полудня.
fn read_generation(scap: usize) -> Option<String> {
    let mut id = [0u8; 32];
    if sys::obj_get_root(scap, b"system/current", &mut id) != 32 {
        sys::write_console("[wm] конфиг: нет корня system/current\n".as_bytes());
        return None;
    }
    let mut name = [0u8; 64];
    let n = sys::obj_get(scap, &id, &mut name);
    if n == 0 || n > name.len() {
        sys::write_console("[wm] конфиг: имя поколения не прочиталось\n".as_bytes());
        return None;
    }
    let mut root = alloc::vec::Vec::from(&b"system/"[..]);
    root.extend_from_slice(&name[..n]);
    if sys::obj_get_root(scap, &root, &mut id) != 32 {
        sys::write_console("[wm] конфиг: нет корня ".as_bytes());
        sys::write_console(&root);
        sys::write_console(b"\n");
        return None;
    }
    let mut buf = vec![0u8; 64 * 1024];
    let n = sys::obj_get(scap, &id, &mut buf);
    if n == 0 || n > buf.len() {
        sys::write_console("[wm] конфиг: текст поколения не прочитался\n".as_bytes());
        return None;
    }
    buf.truncate(n);
    match String::from_utf8(buf) {
        Ok(s) => Some(s),
        Err(_) => {
            sys::write_console("[wm] конфиг: текст поколения не UTF-8\n".as_bytes());
            None
        }
    }
}

fn main_loop() -> ! {
    let Some(fb_cap) = find_fb_cap() else {
        sys::write_console("[wm] нет права на экран (mmio:fb в конфиге)\n".as_bytes());
        sys::exit(1);
    };
    let Some(info) = sys::video_info(fb_cap) else {
        sys::write_console("[wm] ядро не отдало описание видеорежима\n".as_bytes());
        sys::exit(1);
    };
    if !sys::mmio_map(fb_cap, FB_VA) {
        sys::write_console("[wm] не удалось замапить фреймбуфер\n".as_bytes());
        sys::exit(1);
    }
    sys::write_console(alloc::format!("[wm] композитор VOID, {}\n", BUILD).as_bytes());
    let me = sys::self_endpoint();
    let store = store_cap();

    // Веха 142.1 — раскладка каналов пикселя считается ОДИН раз. `pack` звался на каждый пиксель
    // кадра и каждый раз перебирал три канала циклом с clamp'ом — при миллионе пикселей это и
    // была основная цена сборки (замер: 27 мс на кадр).
    let rgb = [
        (info.rgb[0].0 as u32, 8 - info.rgb[0].1.clamp(1, 8) as u32),
        (info.rgb[1].0 as u32, 8 - info.rgb[1].1.clamp(1, 8) as u32),
        (info.rgb[2].0 as u32, 8 - info.rgb[2].1.clamp(1, 8) as u32),
    ];
    let rgb8 = rgb.iter().all(|&(_, drop)| drop == 0);

    // Конфиг поколения читаем ОДИН раз: из него и раскладка клавиш, и обои, и — с Вехи 148.3 —
    // ПАЛИТРА. Читать его надо до первой заливки: фон стола красится уже из темы.
    let generation = read_generation(store).unwrap_or_default();
    // Веха 178 — язык из того же поколения, что и тема.
    ui::i18n::set_from_config(&generation);
    let theme = Theme::from_config(&generation);

    let mut wm = Wm {
        info,
        rgb,
        rgb8,
        work: At::new(0, 0, info.width as i32, info.height as i32),
        // Веха 150 — буфер обмена ПЕРЕЖИВАЕТ ПЕРЕЗАГРУЗКУ: он лежит корнем в store, и здесь мы
        // его просто поднимаем. Вид после загрузки считаем текстом: других видов сегодня нет, а
        // когда появятся — рядом ляжет их признак.
        clip: read_root_id(store, b"clip/current").map(|id| (win::CLIP_TEXT, id)),
        // Перетаскивание, в отличие от буфера, перезагрузку НЕ переживает и не должно: груз в
        // руке — это движение, а не хранилище. Корень `drag/current` от прошлого раза остаётся в
        // store и будет заменён первым же новым перетаскиванием.
        carry: None,
        dropped: None,
        saving: None,
        session_last: String::new(),
        session_at: 0,
        store,
        // Веха 155 — своё право обзора ищем по ВИДУ, а не по месту в конфиге: порядок прав в
        // строке поколения — дело владельца, и привязываться к нему значит ломаться от перестановки.
        sysview: sys::start_cap_of_kind(13).map_or(sys::NO_CAP, |(c, _)| c),
        power: sys::start_cap_of_kind(10).map_or(sys::NO_CAP, |(c, _)| c),
        // Канал к серверу сети ищется по АДРЕСАТУ: вид у всех эндпоинтов один (4), и «первый
        // попавшийся вид 4» — это файловый сервер.
        netcap: find_net_ep(),
        grants: grant_policy(&generation),
        liveness_at: 0,
        kmods: 0,
        notes: Vec::new(),
        next_note: 1,
        toast: None,
        toast_box: None,
        frames: Frames::new(),
        anim_busy: false,
        dnd: false,
        wins: Vec::new(),
        next_id: 1,
        cursor: Pt::new(info.width as i32 / 2, info.height as i32 / 2),
        buttons: 0,
        cols: Vec::new(),
        cur: 0,
        scroll_x: 0,
        scroll_from: 0,
        scroll_to: 0,
        scroll_at: 0,
        scroll_dur: 0,
        focus: None,
        grains: [0; SHM_WORDS],
        damage: Vec::new(),
            shadow: vec![0u32; info.width * info.height],
        present_all: false,
        // Веха 137 — стол ровно один, пустой. Дальше их число ведёт `tidy_spaces`.
        ov_bands: Vec::new(),
        spaces: vec![Space::default()],
        space: 0,
        overview: false,
        ov_cam: (0, 0),
        cam_from: (0, 0),
        cam_to: (0, 0),
        cam_at: 0,
        cam_dur: 0,
        super_held: false,
        hover: None,
        grab: None,
        commit_reply: Vec::new(),
        ov: Vec::new(),
        ov_t: 0,
        ov_from: 0,
        ov_to: 0,
        ov_at: 0,
        ov_dur: 0,
        ov_band_y: 0,
        status: (0, 1, None, 0, false, 0, false),
        anim: ANIM_MS,
        drag: None,
        slide: None,
        th: theme,
    };

    // Рабочий стол целиком — единственная полная заливка за всю сессию.
    wm.fill_rect(0, 0, info.width as i32, info.height as i32, tri(wm.th.desktop));
    wm.draw_cursor();
    // Веха 142 — скорость анимаций из конфига (`desktop anim <мс>`). Значение чужое, поэтому
    // потолок ставим свой: срок длиннее секунды делает систему не плавной, а задумчивой.
    if let Some(ms) = void_conf::num::<u64>(&generation, "desktop", "anim") {
        wm.anim = ms.min(ANIM_MAX);
        sys::write_console(alloc::format!("[wm] анимации: {} мс\n", wm.anim).as_bytes());
    }

    // Веха 139 — обои. Это ТАКОЙ ЖЕ клиент, как терминал, только просит он поверхность слоя, а
    // не окно; композитор о картинках по-прежнему не знает ничего. Имя картинки уезжает
    // аргументом — здесь это можно, а в конфиге поколения нельзя (см. `wallpaper_name`).
    if let Some(name) = wallpaper_name(&generation) {
        let mut arg = Vec::from(name.as_bytes());
        arg.push(0);
        match sys::spawn_with_endpoint(store, b"wall", &arg, me, b"WM\0") {
            Some(_) => {
                sys::write_console("[wm] обои: ".as_bytes());
                sys::write_console(name.as_bytes());
                sys::write_console(b"\n");
            }
            None => sys::write_console("[wm] обои не запустились (нет bin/wall?)\n".as_bytes()),
        }
    }

    // Веха 140 — ПАНЕЛЬ. Второй клиент слоя и первый, кому нужны клики: столы в ней кликабельны.
    // Как и обои, это отдельная программа, а не часть композитора: панель ходит за состоянием по
    // протоколу (`OP_STATUS`), рисует шрифтом и знает про часы — три умения, которых у держателя
    // всех оконных буферов быть не должно.
    if bar_wanted(&generation) {
        match sys::spawn_with_endpoint(store, b"bar", &[], me, b"WM\0") {
            Some(_) => sys::write_console("[wm] панель запущена\n".as_bytes()),
            None => sys::write_console("[wm] панель не запустилась (нет bin/bar?)\n".as_bytes()),
        }
    }

    // Клиенты — из АВТОЗАПУСКА. Право на себя отдаём под именем `WM`: терминал даёт детям
    // `STDIO`, мы даём окна, и путать эти два хоста нельзя.
    // Веха 151 — ПРОШЛЫЙ СЕАНС поднимается ДО клиентов из конфига, и это не порядок ради
    // порядка: сеанс говорит, КАК ЛЕЖАЛО, а конфиг — ЧТО ВООБЩЕ должно быть на столе. Позванное
    // сеансом конфиг вторым разом не зовёт; чего в сеансе не было — запустится как обычно.
    let restored = wm.restore_session(store, me);

    let argv = sys::argv::Argv::take();
    let list = autostart(&generation);
    let names: Vec<&[u8]> = if list.is_empty() {
        argv.rest().collect()
    } else {
        list.iter().map(|s| s.as_bytes()).collect()
    };
    let mut spawned = restored.len();
    for prog in names {
        if restored.iter().any(|r| r.as_bytes() == prog) {
            sys::write_console("[wm] уже поднят сеансом: ".as_bytes());
            sys::write_console(prog);
            sys::write_console(b"\n");
            continue;
        }
        // Аргумента у клиента из `apps` быть не может, и это не наше ограничение: конфиг
        // поколения — текст, разбираемый по ПРОБЕЛАМ (`init::apply_with`), поэтому `arg:img wall`
        // доедет сюда двумя токенами. Обои этой стены не заметили: у них своя строка конфига
        // (`desktop wallpaper …`), которую мы читаем сами и передаём дальше уже аргументом.
        match sys::spawn_with_endpoint(store, prog, &[], me, b"WM\0") {
            Some(pid) => {
                sys::write_console("[wm] запущен клиент ".as_bytes());
                sys::write_console(prog);
                sys::write_console(b"\n");
                let _ = pid;
                spawned += 1;
            }
            None => {
                sys::write_console("[wm] не запустился клиент ".as_bytes());
                sys::write_console(prog);
                sys::write_console(b"\n");
            }
        }
    }
    if spawned == 0 {
        sys::write_console("[wm] клиентов нет — пустой рабочий стол\n".as_bytes());
    }

    let (binds, from_config) = load_binds(&generation);
    let builtin = parse_binds(DEFAULT_BINDS).len();
    sys::write_console(
        alloc::format!(
            "[wm] раскладка: {} сочетаний {} (зашитая знает {})\n",
            binds.len(),
            if from_config { "ИЗ КОНФИГА ПОКОЛЕНИЯ" } else { "— зашитая схема" },
            builtin,
        )
        .as_bytes(),
    );
    if from_config && binds.len() < builtin {
        sys::write_console(
            "[wm] конфиг знает МЕНЬШЕ действий, чем система: он посеян раньше.              `ved /etc/system/terminal.vv` → wm_keys = [] вернёт схему по умолчанию\n"
                .as_bytes(),
        );
    }

    let mut msg = [0u8; 1024];
    let mut mouse = [sys::MouseEvent { dx: 0, dy: 0, buttons: 0, wheel: 0 }; 32];
    // Начало прошлой отрисовки — точка отсчёта бюджета кадра (`FRAME_NS`).
    let mut frame_at = sys::monotonic_ns();
    loop {
        let mut worked = false;

        // ── клавиши: сперва АККОРДЫ, потом обычный ввод окну в фокусе ──────────────────
        //
        // Клавиши читаются ПЕРЕД мышью (Веха 142), и порядок этот не косметический. Мышь с
        // модификатором — тоже команда системе (`Super`+колесо переключает столы, `Super`+кнопка
        // тащит окно), а держит ли человек Super, композитор узнаёт из очереди КЛАВИШ. Пока мышь
        // разбиралась первой, событие мыши, попавшее в тот же оборот, что и нажатие Super, видело
        // модификатор ещё не нажатым — и уходило в программу как обычный клик. Со стороны это
        // «Super+колесо не работает» и «окно иногда не тащится»: не всегда, а когда рука успела
        // сделать оба движения быстрее одного оборота цикла.
        let mut kev = [sys::KeyEvent { sym: 0, mods: 0, down: false, ch: 0 }; 32];
        let kn = sys::key_read(&mut kev);
        if kn > 0 {
            worked = true;
            for e in &kev[..kn] {
                wm.key_event(e, &binds, store, me);
            }
        }

        // ── мышь ───────────────────────────────────────────────────────────────────────
        let mn = sys::mouse_read(&mut mouse);
        if mn > 0 {
            worked = true;
            for e in &mouse[..mn] {
                wm.on_mouse(e);
            }
        }

        // ── ушедшие клиенты ────────────────────────────────────────────────────────────
        // Окно живёт, пока жив его хозяин. Полагаться на прощание нельзя: программа может
        // упасть, и тогда её рамка осталась бы на экране навсегда — с картинкой, за которой
        // никого нет. Спрашиваем ядро, а не верим на слово.
        wm.reap();

        // ── всплывашка догорела ────────────────────────────────────────────────────────────
        // Гаснет по времени, а не по действию человека: уведомление — это сообщение, а не
        // вопрос, и требовать на него ответа значило бы превратить экран в очередь диалогов.
        if wm.toast.is_some_and(|t| sys::monotonic_ns() >= t.until) {
            wm.damage_toast();
            wm.toast = None;
        }

        // ── запросы клиентов ───────────────────────────────────────────────────────────
        // Спим только когда делать нечего — и просыпаемся по клавише ИЛИ движению мыши
        // (Веха 115 научила ядро будить на мышь тех же, кого будит клавиша).
        // Пока что-то движется, спать до события нельзя: кадры анимации рисуем мы сами — но и
        // «спать поменьше» не значит «рисовать почаще»: см. [`FRAME_NS`]. Ждём ровно до конца
        // бюджета текущего кадра, отсчитанного от начала прошлой отрисовки.
        let now = sys::monotonic_ns();
        let moving = wm.animate(now);
        // Веха 145 — спать не дольше, чем до ближайшего ЧУЖОГО срока. Клиенты просят сроки сами
        // (`next_event_timeout`), но проверяем мы их только проснувшись: с шагом простоя в 200 мс
        // клиент, попросивший 16, получал ответ через двести. Часам бара это было незаметно, а
        // анимации внутри его поверхности — смертельно: меню выезжало пятью кадрами в секунду.
        let idle = wm.next_deadline(now).map_or(200_000_000, |d| {
            d.saturating_sub(now).clamp(1_000_000, 200_000_000)
        });
        let got = if worked {
            sys::try_recv(&mut msg)
        } else {
            // Веха 139.3 — срок в НАНОСЕКУНДАХ. Эти же два числа стояли здесь и раньше, но
            // обёртка брала ТИКИ: 200 тактов TSC — это 60 нс, то есть сна не было вовсе.
            // Композитор крутил оборот за оборотом на пустом экране и жёг целое ядро (замер:
            // 100% при простое). Ошибка не видна ни в чём, кроме счётчика процессора: кадры
            // рисуются по damage, поэтому лишние обороты ничего не портили — только грелись.
            // Остаток бюджета кадра, но не меньше миллисекунды: кадр, не уложившийся в 16 мс,
            // не должен превращать ожидание в холостой оборот — соседям тоже нужен процессор.
            let pace = (frame_at + FRAME_NS).saturating_sub(now).clamp(1_000_000, FRAME_NS);
            sys::recv_console(&mut msg, if moving { pace } else { idle })
        };
        if let Some(m) = got {
            wm.request(&m, &msg);
        }

        // Веха 140 — состояние рабочего места и сроки ожидания: одно место на оба, в конце
        // оборота, когда учтены и ввод, и запросы клиентов. Точность срока здесь — шаг простоя
        // композитора (200 мс): часам в баре этого достаточно, анимации — нет, о чём сказано в
        // протоколе.
        wm.notify_status();
        wm.expire_waits(sys::monotonic_ns());
        // Веха 151 — идёт сбор сеанса: ответили все или вышел срок? Здесь же, в конце оборота,
        // по той же причине, что и сроки ожидания: к этому месту учтены ответы клиентов.
        wm.tick_save(sys::monotonic_ns());
        // Веха 151.1 — и сверка сеанса с тем, что на экране: раз в пять секунд, запись — только
        // при разнице.
        wm.tick_session(sys::monotonic_ns());

        // Кадр — ОДИН на оборот, в самом конце: к этому месту учтены все события пачки, все
        // ответы клиентов и все ушедшие окна. Пока рисовало каждое событие само, рука обгоняла
        // экран (Веха 120.2). Отметка времени берётся ЗДЕСЬ, до отрисовки: от неё отсчитывается
        // бюджет кадра, и стоимость самого кадра попадает внутрь бюджета, а не сверх него.
        //
        // Веха 145.4 — и не чаще ОДНОГО за бюджет, пока идёт движение.
        //
        // Рисовал каждый оборот, а будят нас не только сроки: клиент прислал запрос, ответил
        // бар, пришла клавиша. Пока сон промахивался на четыре миллисекунды, лишние обороты в
        // этом промахе тонули; стоило ядру научиться будить точно (`timer_arm_at`, Веха 145.4) —
        // и на каждый кадр стало приходиться по два лишних, каждый ценой полной сборки. Бюджет
        // обязан ограничивать ОТРИСОВКУ, а не только сон: иначе точность пробуждения покупается
        // ростом расхода, то есть меняет одну беду на другую.
        //
        // Вне движения ограничения нет: там кадр рисуется по событию, и задержать ответ на
        // клавишу ради ровного темпа — ровно та ошибка, которую чинили Вехой 120.2.
        let t = sys::monotonic_ns();
        if !moving || t.saturating_sub(frame_at) >= FRAME_NS {
            frame_at = t;
            wm.flush();
            // Веха 170.6 — и только теперь отпускаем клиента, чей кадр мы собрали: его буфер
            // общий, и рисовать в него следующий кадр он может лишь после того, как мы дочитали
            // этот (см. [`Wm::commit_reply`]). Ждать ему не дольше бюджета кадра: вне движения
            // сборка идёт каждый оборот, в движении — раз в `FRAME_NS`.
            for cap in wm.commit_reply.drain(..) {
                sys::reply(cap, &[]);
            }
        }
    }
}

/// Веха 129 — окно ВА композитора под ЧУЖИЕ буферы кадров: между своей кучей (`0x6000_0000`) и
/// своим стеком (вершина `0x8000_0000`, под ним 64 страницы).
///
/// ## Веха 169.1 — ЗЕРНО в мебибайт вместо слота в восемь
///
/// Было тридцать один слот по 8 МиБ: столько, сколько занимает ПОЛНОЭКРАННЫЙ кадр. Каждое окно
/// брало целый слот независимо от размера — а окно в ленте из двадцати колонок это триста точек
/// в ширину, меньше мебибайта. Восьмикратный перерасход самого дефицитного здесь ресурса, и он
/// упирался в потолок ровно там, где владелец его и нашёл: «открываешь очень много терминалов —
/// в какой-то момент окна перестают что-либо показывать». Это не память кончалась (её ещё много),
/// а **адресное пространство композитора**: тридцать первый слот был последним.
///
/// Теперь область берёт столько ЗЁРЕН по мебибайту, сколько нужно её кадру. Полноэкранное окно
/// возьмёт четыре зерна, окно колонки — одно. Зёрен четыреста восемь, то есть потолок отодвинулся
/// с трёх десятков окон до нескольких сотен — дальше раньше кончится что-нибудь ещё, и это уже
/// будет честный ответ, а не молчаливое окно цвета рамки.
///
/// Условие на область: её длина не должна превышать взятые зёрна, иначе она накрыла бы соседа.
/// Клиенты создают кадр ровно `ширина×высота×4` ([`win::Window`]), поэтому это не ограничение, а
/// проверка — на чужого клиента, который решит завести область с запасом.
const SHM_BASE: usize = 0x6600_0000;
const SHM_GRAIN: usize = 1024 * 1024;
const SHM_GRAINS: usize = 408; // 0x6600_0000 + 408 МиБ = 0x7F80_0000 — ниже стека
/// Слов по 64 бита в карте занятых зёрен.
const SHM_WORDS: usize = SHM_GRAINS.div_ceil(64);

/// Одно окно.
struct Win {
    id: u32,
    owner: usize,
    /// Левый верхний угол РАМКИ на экране.
    x: i32,
    y: i32,
    w: i32,
    h: i32,
    /// Заголовок от клиента. Композитор его больше не рисует (полосы заголовка нет), но
    /// хранит: он понадобится подписям в обзоре и списку окон.
    #[allow(dead_code)]
    title: String,
    /// Веха 129 — ОБЩИЙ буфер кадра клиента, отображённый у нас: адрес, длина, право и слот
    /// нашего окна ВА. `buf == 0` — буфера нет (клиент его не дал).
    ///
    /// Копии больше нет вовсе. До этой вехи здесь лежал `Vec<u8>`, куда вклеивались куски,
    /// прочитанные из store по content-id, — и платили мы не за пиксели, а за бухгалтерию вокруг
    /// них ([[compositor-damage]]). Теперь это ТЕ ЖЕ страницы, в которые пишет клиент, и
    /// отображены они ТОЛЬКО НА ЧТЕНИЕ: композитор в чужой кадр не пишет, и это свойство железа,
    /// а не обещание.
    buf: usize,
    buf_len: usize,
    cap: usize,
    /// Веха 169.1 — какие ЗЁРНА окна ВА заняты этой областью: первое и сколько ([`SHM_GRAIN`]).
    slot: usize,
    span: usize,
    /// Размер, в котором клиент РИСУЕТ (раскладка буфера). Отдельно от назначенного размера окна
    /// (Веха 126.1): между «раскладка решила, что окно теперь другое» и «клиент завёл буфер под
    /// новый размер» проходит время, и всё это время надо показывать СТАРУЮ картинку, растянув
    /// её. Раньше копия обнулялась сразу — окно чернело, а при складывании в стопку это
    /// выглядело как артефакты.
    bw: i32,
    bh: i32,
    /// Веха 168.3 — **ЧТО КЛИЕНТ ВООБЩЕ РИСОВАЛ** в этот буфер: объединение всех его кадров, в
    /// координатах буфера. Пусто — не рисовал ничего.
    ///
    /// Нужно, чтобы убрать поверхность стоило по площади нарисованного, а не по площади
    /// поверхности. Слой панели растянут на весь экран, но закрашено в нём полотно меню и полоса;
    /// остальное — нули, то есть прозрачность, и пересобирать под ним стол незачем: без слоя там
    /// получится ровно тот же пиксель.
    ///
    /// До этой вехи закрытие меню стоило миллион точек и 11 мс сборки — единственный кадр во всём
    /// замере, выпадавший из бюджета ([`Frames`], `bin/fps`).
    touched: Rect,
    /// Отложенный ответ на `OP_EVENT` (клиент спит в `SYS_CALL`).
    waiting: Option<usize>,
    /// Веха 140 — СРОК отложенного ответа (монотонные наносекунды). `None` — ждать бессрочно, как
    /// ждали все клиенты до бара. Вышел срок — отвечаем пусто: «событий не было».
    wait_until: Option<u64>,
    /// Веха 140 — подписан ли на `EV_STATUS` (смена стола, их числа, фокуса). Подписка явная:
    /// обоям состояние стола не нужно, и будить их на каждую смену фокуса не за что.
    watching: bool,
    /// События, накопленные до того, как клиент спросил.
    inbox: Vec<win::Event>,
    /// Что рисуется сейчас (Веха 125). Между `shown` и рамкой из раскладки и живёт анимация.
    shown: Shown,
    /// Откуда началось нынешнее движение и куда идёт.
    from: Shown,
    to: Shown,
    /// Когда началось и сколько длится; `dur == 0` — стоим на месте.
    at: u64,
    dur: u64,
    /// Окно ещё не раскладывали ни разу — появиться оно должно ростом, а не рывком с нуля.
    fresh: bool,
    /// Окно ЗАКРЫВАЕТСЯ: хозяина уже нет, но пиксели держим, пока доигрывает сжатие.
    closing: bool,
    /// Лежит ли окно на АКТИВНОМ рабочем столе (Веха 122). Окно с чужого стола живо, помнит
    /// свои пиксели и продолжает работать — его просто не видно и не потрогать.
    visible: bool,
    /// Веха 139 — поверхность СЛОЯ (обои, бар), а не окно ленты. `None` — обычное окно.
    ///
    /// Одна структура на оба вида намеренно. Всё, что делает окно окном, — буфер, события,
    /// damage, смерть хозяина — у слоя ровно то же самое; разница только в том, кто назначает
    /// место и где оно в стопке. Заведи мы второй список, каждая из этих общих вещей
    /// существовала бы в двух копиях и разошлась бы на первой же правке.
    layer: Option<LayerCfg>,
    /// Веха 147.1 — НОВЫЙ буфер, принятый, но ещё НЕ ПОКАЗАННЫЙ (`OP_REBUF` до первого
    /// `OP_COMMIT`). `None` — показываем то, что есть.
    ///
    /// Раньше `OP_REBUF` подменял буфер сразу, и между «принял» и «клиент нарисовал» проходило
    /// 6–25 мс (замер) — то есть кадр-другой композитор показывал ПУСТУЮ область. Панель на этом
    /// мигала при открытии меню, и владелец это видел.
    next: Option<Pending>,
    /// Веха 147 — ПЛИТКА ЗАПУСКА: место в ленте, занятое под ещё не появившееся окно. `None` —
    /// обычное окно или слой.
    ///
    /// Снова поле в той же структуре, а не третий список, — и довод тот же, что у слоёв: плитку
    /// раскладывают, двигают, показывают и закрывают ровно так же, как окно. Отличий два, и оба
    /// в одном месте каждое: клиента у неё нет (некому слать события и незачем ждать ответа), а
    /// пиксели рисует сам композитор ([`Win::own`]).
    launch: Option<Launch>,
    /// Веха 151.1 — ЧЕМ ВЕРНУТЬ это окно: последний ответ на «сохранись» ([`win::OP_PERSIST`]).
    ///
    /// Помним, а не спрашиваем каждый раз, ровно ради того, чтобы сеанс писался ПО ХОДУ ДЕЛА:
    /// перекладывание окон и смена фокуса стоят десятков байт, и платить за них опросом всех
    /// клиентов было бы нелепо. Спрашиваем один раз — когда окно появилось.
    run: Option<String>,
    /// Веха 151.1 — последний СНИМОК кадра: `(content-id шестнадцатеричным, ширина, высота)`.
    ///
    /// Обновляется только при полном сохранении (снимок — мегабайты), а переписывание раскладки
    /// несёт прежний. Картинка при этом может отстать от содержимого — и это верный размен:
    /// живое окно заменит её через секунду после загрузки.
    snap: Option<(String, i32, i32)>,
    /// Веха 151.1 — спрашивали ли уже это окно. Молчуна не переспрашиваем: `winbox` и прочие
    /// демо на «сохранись» не отвечают вовсе, и долбить их каждые пять секунд незачем.
    asked: bool,
    /// Веха 147 — пиксели, нарисованные НАМИ (плитка запуска), а не присланные клиентом.
    ///
    /// Отдельное поле, а не `buf`: тот держит ЧУЖУЮ область, отображённую через `shm_map`, и
    /// отпускается она `shm_unmap`. Своя память освобождается сама вместе с окном, и путать эти
    /// два способа владения нельзя — как раз на таком «почти одинаковом» и живут двойные
    /// освобождения.
    own: Option<Vec<u8>>,
}

/// Веха 147.1 — принятый, но ещё не показанный буфер кадра ([`Win::next`]).
struct Pending {
    va: usize,
    len: usize,
    cap: usize,
    slot: usize,
    span: usize,
    w: i32,
    h: i32,
}

/// Веха 147 — что композитор знает о запуске, которого ещё не видно ([[launch-tile]]).
struct Launch {
    /// Номер запущенного процесса. По нему плитка узнаёт СВОЁ окно: первый `OP_CREATE` от этого
    /// процесса или его потомка её и заменяет.
    pid: usize,
    /// Что показываем человеку — имя, названное запускающим.
    name: String,
    /// Когда сказали «запускаю» (монотонные наносекунды): из него и «долго запускается».
    since: u64,
    /// Итог: код выхода и хвост вывода. `None` — ещё ждём.
    ///
    /// Ровно ради этого поля веха и затевалась: плитка, которая крутится после смерти процесса,
    /// запрещена ADR 0016 дословно.
    done: Option<(u32, String)>,
    /// Что уже нарисовано в [`Win::own`] — чтобы не перерисовывать плитку каждый кадр.
    drawn: Option<(i32, i32, u32)>,
    /// Веха 151 — пиксели плитки это СНИМОК окна из прошлого сеанса, а не наш рисунок.
    ///
    /// Плитка восстановления — та же плитка запуска, и это не экономия кода, а совпадение по
    /// смыслу: и та и другая держат место в ленте под окно, которого ещё нет, и уступают его,
    /// когда окно приходит. Разница ровно в том, что нарисовано внутри, — и в том, что бегунок
    /// поверх снимка был бы ложью: мы не «запускаем с нуля», мы возвращаем то, что было.
    ///
    /// Если запуск СОРВЁТСЯ, снимок уступит место карточке с кодом выхода (`done`): врать
    /// картинкой о живой программе, которой нет, нельзя.
    shot: bool,
}

/// Чего поверхность слоя попросила у композитора (Веха 139) — см. [`win::Layer`].
#[derive(Clone, Copy)]
struct LayerCfg {
    layer: u8,
    anchor: u8,
    /// Сколько пикселей у своего края поверхность отнимает у окон.
    exclusive: i32,
    /// Веха 144 — у пикселей значима альфа: смешивать, а не копировать (`win::LAYER_ALPHA`).
    alpha: bool,
    /// Веха 146 — поверхности нужна клавиатура (`win::LAYER_KBD`): клавиши идут ей, а не окну.
    kbd: bool,
}

/// Разобрать тело запроса — или ответить пусто и уйти (Веха 148.4).
///
/// Не разобралось — значит сообщение короче, чем говорит его операция. Отвечаем ПУСТО, а не
/// молчим: молчание повесило бы вызвавшего навсегда, а падать из-за чужого кривого запроса
/// композитору нельзя вовсе — вместе с ним пропадёт экран.
macro_rules! body {
    ($m:expr, $e:expr) => {
        match $e {
            Some(v) => v,
            None => {
                sys::reply($m.reply_cap, &[]);
                return;
            }
        }
    };
}

/// Отправить событие ответом на отложенный `OP_EVENT` или на `OP_POLL`.
///
/// Байтами событие становится ровно здесь и ровно одним способом — [`win::Event::encode`],
/// который лежит рядом с разбором на клиентской стороне.
fn reply_event(cap: usize, e: win::Event) {
    let mut b = [0u8; 8];
    let n = e.encode(&mut b);
    sys::reply(cap, &b[..n]);
}

impl Win {
    /// Кадр клиента, как его видим мы: RGBA8888 по строкам `bw × bh`. Пусто — буфера нет.
    ///
    /// У плитки запуска (Веха 147) клиента нет вовсе, и кадр её рисует сам композитор — отсюда
    /// первая ветка. Дальше по всему пути рисования разницы уже никакой: плитка проходит через
    /// тот же `draw_win_row`, то же масштабирование и то же повреждение.
    fn px(&self) -> &[u8] {
        if let Some(p) = &self.own {
            return p;
        }
        if self.buf == 0 {
            return &[];
        }
        unsafe { core::slice::from_raw_parts(self.buf as *const u8, self.buf_len) }
    }

    /// Обычное ли это окно (участвует в ленте, берёт фокус, получает клавиши).
    fn tiled(&self) -> bool {
        self.layer.is_none()
    }
    /// Слой НИЖЕ окон ленты: обои и подложка.
    fn under(&self) -> bool {
        self.layer.is_some_and(|l| l.layer < win::LAYER_TOP)
    }
    /// Слой ВЫШЕ окон ленты: бар, панель, всплывающее.
    fn over(&self) -> bool {
        self.layer.is_some_and(|l| l.layer >= win::LAYER_TOP)
    }
    /// Веха 144 — поверхность просит смешивания по альфе каждого пикселя.
    fn alpha_px(&self) -> bool {
        self.layer.is_some_and(|l| l.alpha)
    }
    /// Веха 146 — поверхность слоя просит КЛАВИАТУРУ: клавиши идут ей, а не окну в фокусе.
    fn grabs_kbd(&self) -> bool {
        self.layer.is_some_and(|l| l.kbd)
    }
    /// Толщина рамки и радиус скругления. У слоя их нет: обои в рамке с уголками — это не
    /// оформление, а ошибка, и бар со скруглёнными углами оставил бы щели у краёв экрана.
    fn deco(&self) -> (i32, i32) {
        if self.tiled() {
            (BORDER, RADIUS)
        } else {
            (0, 0)
        }
    }

    /// Начать движение к `target`.
    fn start(&mut self, target: Shown, ms: u64, now: u64) {
        // Веха 142 — `anim = 0` в конфиге значит «без анимаций», и это законная настройка.
        // Ставим на место СРАЗУ: иначе `tick` с нулевым сроком вернул бы «не двигалось», и окно
        // навсегда осталось бы там, откуда собиралось ехать, — поджатым при открытии.
        if ms == 0 {
            self.shown = target;
            self.from = target;
            self.to = target;
            self.at = now;
            self.dur = 0;
            return;
        }
        self.from = self.shown;
        self.to = target;
        self.at = now;
        self.dur = ms * 1_000_000;
    }

    /// Продвинуть анимацию. `true` — на этом кадре окно ДВИНУЛОСЬ (значит его старое и новое
    /// места надо перерисовать).
    ///
    /// Отвечаем «двинулось» и на последнем шаге тоже. Веха 126.1: раньше последний шаг возвращал
    /// `false`, и если анимация укладывалась в ОДИН кадр (кадр длиннее её срока — на медленной
    /// машине или при заминке), окно молча перескакивало, ничего не пометив, а на старом месте
    /// оставался его снимок. Именно это владелец видел, складывая окна в стопку.
    fn tick(&mut self, now: u64) -> bool {
        if self.dur == 0 {
            return false;
        }
        let t = ((now.saturating_sub(self.at)) * 1024 / self.dur).min(1024) as i32;
        self.shown = self.from.mix(&self.to, ease_out(t));
        if t >= 1024 {
            self.shown = self.to;
            self.dur = 0;
        }
        true
    }

    /// Где окно НАРИСОВАНО — в экранных координатах.
    ///
    /// Единственное место, знающее правило «у СЛОЯ лента не едет»: обои и панель стоят в экране
    /// намертво, их не двигают ни прокрутка, ни обзор — поэтому им прокрутка равна нулю. Всё
    /// остальное обязано спрашивать место здесь, а не считать его самому: три ошибки подряд
    /// (см. шапку про пространства) были ровно попытками посчитать самому.
    fn place(&self, scroll: i32) -> At<Screen> {
        self.shown.rect().to_screen(if self.tiled() { scroll } else { 0 })
    }

    /// Попадание — по ВИДИМОМУ положению: человек целится в то, что нарисовано.
    fn hit_frame(&self, p: Pt<Screen>, scroll: i32) -> bool {
        self.place(scroll).contains(p)
    }

    /// Веха 149.1 — точка экрана → точка в БУФЕРЕ клиента.
    ///
    /// Считается от НАРИСОВАННОГО прямоугольника (`shown` минус прокрутка ленты) — от того же,
    /// по которому решается попадание. До этой вехи здесь стоял `content_at()`, то есть место
    /// окна В ЛЕНТЕ, и получалось так: попадание считалось в экранных координатах, а точка,
    /// которую композитор называл клиенту, — в координатах ленты. Пока лента стоит на нуле, это
    /// одно и то же; стоит ей уехать (третья колонка, широкая колонка, `Super+F`) — и клиент
    /// получает точку, сдвинутую на всю прокрутку. Владелец увидел это так: **кнопки вьювера
    /// корней рисуются в окне, а нажимаются там, где окно было раньше**. Ровно та же ловушка уже
    /// ловила damage-прямоугольник клиента — там она записана в коде ниже.
    ///
    /// Заодно переводим масштаб: на экран содержимое кладётся растянутым из буфера
    /// (`bw × bh` → `cw × ch`, см. `draw_win_row`), и пока буфер не догнал новый размер — а между
    /// `EV_RESIZE` и `OP_REBUF` так бывает у любого клиента, — это две разные системы координат.
    ///
    /// Обрезка по буферу не косметика: `hit_frame` пускает сюда и точку НА РАМКЕ, а `-1`,
    /// приведённый к `u16`, даёт `0xffff` — код «курсор ушёл с поверхности» (`Event::GONE`).
    /// Движение по левому краю окна читалось клиентом как уход мыши.
    fn client_point(&self, p: Pt<Screen>, scroll: i32) -> (u16, u16) {
        let (b, _) = self.deco();
        let f = self.place(scroll).rect();
        let (cw, ch) = ((f.w - 2 * b).max(1), (f.h - 2 * b).max(1));
        let (bw, bh) = (self.bw.max(1), self.bh.max(1));
        let lx = (p.x - f.x - b) * bw / cw;
        let ly = (p.y - f.y - b) * bh / ch;
        (lx.clamp(0, bw - 1) as u16, ly.clamp(0, bh - 1) as u16)
    }
}

/// Колонка ленты (Веха 121): окна одно под другим плюс ширина колонки.
///
/// Модель — скроллируемый тайлинг niri ([[wm-keys]]): окна живут в колонках на бесконечной ленте,
/// экран — окно просмотра, которое по ней ездит. Плавающие окна остаются исключением, а не
/// основой; сегодня их нет вовсе.
struct Column {
    /// Идентификаторы окон сверху вниз.
    ids: Vec<u32>,
    /// Индекс в [`WIDTHS`].
    width: usize,
    /// Какое окно колонки в фокусе.
    focus: usize,
}

/// Отложенный рабочий стол: его лента ждёт своей очереди (Веха 122).
///
/// АКТИВНЫЙ стол живёт прямо в полях [`Wm`], а остальные — здесь. Так вся раскладка работает с
/// одной лентой и не знает про столы вовсе; переключение — это обмен лентами, и он в одном месте.
#[derive(Default)]
struct Space {
    cols: Vec<Column>,
    cur: usize,
    scroll_x: i32,
}

/// Сколько столов достижимо ПРЯМЫМ переходом с клавиатуры — по числу цифр (`Super+1…9`).
/// Столов при этом может быть и больше, и меньше: их число живёт своей жизнью (см. [`Wm::tidy_spaces`]).
const SPACE_KEYS: usize = 9;

/// Пресеты ширины колонки — доли экрана. Те же, что у владельца в niri.
const WIDTHS: [(i32, i32); 4] = [(1, 3), (1, 2), (2, 3), (1, 1)];

/// Зазор между окнами и до края экрана.
const GAP: i32 = 8;

/// Меньше этого рабочую область не ужать никакой панели (Веха 139): клиент вправе попросить
/// занятую зону во весь экран, но остаться совсем без места для окон система не должна.
const MIN_WORK: i32 = 64;

/// Масштаб обзора — ровно половина. Фиксированный: см. `build_overview`.
const OV_NUM: i32 = 1;
const OV_DEN: i32 = 2;
/// Зазор между полосами столов в обзоре. Заметно больше оконного: он и разделяет столы.
const OV_GAP: i32 = 48;

struct Wm {
    info: sys::VideoInfo,
    /// Веха 139 — РАБОЧАЯ ОБЛАСТЬ `(x, y, w, h)`: экран минус зоны, занятые слоями (бар).
    /// Лента живёт в ней, а не на экране; без слоёв с занятой зоной она равна экрану.
    work: At<Screen>,
    /// Веха 137 — полосы столов в обзоре: `(x, y, w, h, активный)` в координатах обзора.
    /// Нужны, чтобы стол было ВИДНО, когда на нём нет окон: с динамическими столами последний
    /// всегда пустой, и без полосы про него неоткуда узнать — ровно то возражение, из-за
    /// которого динамические столы и откладывали.
    /// Полосы столов в обзоре: `(x, y, w, h, номер стола)`. Номер, а не признак «активный»:
    /// по нему же считается клик по пустому месту стола (Веха 142).
    ov_bands: Vec<(At<Screen>, usize)>,
    /// Порядок = z-order: последнее окно рисуется поверх и получает клики первым.
    wins: Vec<Win>,
    /// Лента колонок слева направо.
    cols: Vec<Column>,
    /// Колонка в фокусе.
    cur: usize,
    /// Сдвиг ленты относительно экрана: лента длиннее экрана, экран по ней ездит.
    ///
    /// Веха 125.2 — сдвиг АНИМИРУЕТСЯ отдельно от окон, и это принципиально. Раньше он входил
    /// в координату каждого окна, поэтому «лента поехала» означало «каждое окно поехало само по
    /// себе, из своего места»: окна прибывали вразнобой, наслаивались и оставляли следы. Лента
    /// — одно целое, и двигаться обязана как целое; окна анимируются только когда меняют место
    /// В ЛЕНТЕ.
    scroll_x: i32,
    scroll_from: i32,
    scroll_to: i32,
    scroll_at: u64,
    scroll_dur: u64,
    next_id: u32,
    cursor: Pt<Screen>,
    buttons: u8,
    focus: Option<u32>,
    /// Занятые ЗЁРНА окна ВА под буферы клиентов — по биту на зерно (Вехи 129, 169.1).
    grains: [u64; SHM_WORDS],
    /// Что перерисовать в конце оборота (Веха 120.2). Раньше каждое событие рисовало САМО, и
    /// перетаскивание превращалось в тридцать перерисовок на один оборот цикла.
    damage: Vec<At<Screen>>,
    /// Строка пикселей в RAM: собираем её здесь, а во фреймбуфер отдаём одной последовательностью.
    /// ТЕНЕВОЙ КАДР (Веха 126): весь экран в обычной памяти. Кадр собирается здесь, а на экран
    /// уходит блитом. Затевалось ради разрывов, а понадобилось ради СТОИМОСТИ: прокрутка ленты
    /// перерисовывала миллион пикселей на кадр, а с теневым кадром она — сдвиг памяти плюс
    /// сборка открывшейся полосы.
    shadow: Vec<u32>,
    /// Отдать на экран весь кадр (после сдвига памяти изменилось всё).
    present_all: bool,
    /// Неактивные рабочие столы (активный — в полях выше).
    spaces: Vec<Space>,
    /// Номер активного стола.
    space: usize,
    /// Включён ли ОБЗОР (Веха 123): столы уменьшены и видны разом.
    overview: bool,
    /// Держат ли сейчас Super. Нужно колесу: `Super+колесо` крутит столы, а голое колесо
    /// принадлежит программе. Маска модификаторов есть у событий КЛАВИШ, у мыши её нет —
    /// поэтому состояние ведём здесь, по нажатиям и отпусканиям.
    /// Веха 142.1 — `(сдвиг, сколько бит отбросить)` на канал: готовая раскладка пикселя.
    rgb: [(u32, u32); 3],
    /// Все три канала по восемь бит — тогда разбор пикселя это сдвиг, а не деление.
    rgb8: bool,
    super_held: bool,
    /// Веха 144 — номер поверхности ПОД КУРСОРОМ. Нужен только для того, чтобы сказать прежней,
    /// что курсор ушёл: без этого подсветка виджетов под курсором залипала бы навсегда.
    hover: Option<u32>,
    /// Веха 169 — **ЗАХВАТ УКАЗАТЕЛЯ**: поверхность, на которой нажали кнопку. Пока её держат,
    /// движение и отпускание принадлежат ей, куда бы ни ушла рука.
    ///
    /// Без захвата протяжка ломалась ровно там, где она нужна, — при выходе за край окна. Пример
    /// владельца — выделение мышью в терминале, и там было сразу две беды. Первая: уходя с окна,
    /// курсор получал `EV_MOTION` с координатами `0xffff` («ушёл»), а терминал считал их точкой и
    /// клал конец выделения в последнюю ячейку кадра — выделение «уезжало». Вторая хуже: ОТПУСКАНИЕ
    /// уезжало соседу, и терминал так и оставался в режиме протяжки — дальше выделение ходило за
    /// курсором без единой нажатой кнопки.
    ///
    /// Чинить это в терминале значило бы починить один терминал: то же самое ждёт всякого, кто
    /// тащит полосу прокрутки или ведёт выделение в поле ввода. Захват — общее правило оконных
    /// систем ровно поэтому, и координаты у нас уже зажимаются краем поверхности
    /// ([`Win::client_point`]) — то есть уход за край читается как «у самого края», чего протяжка
    /// и ждёт.
    grab: Option<u32>,
    /// Веха 170.6 — **отложенный ответ на `OP_COMMIT`**: право ответа клиента, который сказал
    /// «нарисовал», но которого мы ещё не отпустили.
    ///
    /// Буфер окна ОДИН и общий: клиент в него пишет, композитор из него читает. Пока ядро было
    /// одно, порядок был гарантирован даром — ответ делал клиента готовым, но исполнять его было
    /// некому: композитор шёл дальше и собирал кадр до того, как уснуть. С двумя ядрами клиент
    /// просыпается НА СОСЕДНЕМ и начинает рисовать следующий кадр прямо поверх того, который
    /// композитор в эту секунду читает. На экране это разрыв — верх окна из нового кадра, низ из
    /// старого; владелец увидел его как «мерцает верхняя часть диспетчера при движении мыши».
    ///
    /// Поэтому ответ уезжает ПОСЛЕ сборки кадра. Заодно это честный ритм: клиент рисует не чаще,
    /// чем экран показывает, — ровно то, чего добивались бюджетом кадра с другой стороны.
    ///
    /// Полного порядка это не даёт: композитор может перечитать буфер и без нового коммита —
    /// например, когда поверх окна проехало соседнее. Такой случай закрывается только вторым
    /// буфером на окно, и это отдельная работа (в известных пробелах — «нет двойной буферизации»).
    ///
    /// Именно ОЧЕРЕДЬ, а не одно место. Между двумя сборками кадра оборотов бывает несколько (в
    /// движении кадр рисуется раз в бюджет, а обороты идут чаще), и коммитов за это время
    /// приходит столько же. С одним местом второй коммит затирал право ответа первого — и тот
    /// клиент замирал НАВСЕГДА, потому что ответа ему уже никто не пошлёт. На экране это
    /// выглядело как «система почти встала»: за десять секунд один кадр.
    commit_reply: Vec<usize>,
    /// Веха 142 — длительность ПЕРЕЕЗДА окна в мс; остальные сроки — доли от неё
    /// ([`D_OPEN`], [`D_CLOSE`], [`D_OV`]). Ноль означает «без анимаций»: рывком, но честно.
    anim: u64,
    /// Веха 148.3 — палитра системы из конфига поколения. Одна на композитор, панель и родные
    /// программы: до неё композитор держал свою и три цвета из пяти успели разойтись.
    th: Theme,
    /// Веха 142 — идёт перетаскивание мышью с Super (ЛКМ — переставить, ПКМ — ширина).
    drag: Option<Drag>,
    /// Веха 142.1 — идёт переезд между столами.
    slide: Option<Slide>,
    /// Где стоит камера обзора. Хранится, а не вычисляется каждый раз, — и в этом суть
    /// (Веха 123.2): камера едет за ОСОЗНАННЫМ выбором (клавиши, колесо, вход в обзор), а
    /// наведение мышью только переносит фокус.
    ov_cam: (i32, i32),
    /// Анимация камеры обзора: откуда, куда, когда началась и сколько длится.
    cam_from: (i32, i32),
    cam_to: (i32, i32),
    cam_at: u64,
    cam_dur: u64,
    /// Что и куда нарисовано в обзоре. Считается один раз при каждом изменении — и рисованием,
    /// и попаданием мыши пользуется ОДИН этот список: два расчёта «где что» означали бы, что
    /// клик приходит не в то окно, которое человек видит.
    ov: Vec<OvItem>,
    /// Переход «лента ↔ обзор» (Веха 126.6): 0 — лента, 1024 — обзор. Одного числа хватает на
    /// всё: обзор — это ОДНА картинка, и наезд камеры на свой стол выражается одним
    /// преобразованием ([`Wm::ov_xform`]), а не анимацией каждого окна по отдельности.
    ov_t: i32,
    ov_from: i32,
    ov_to: i32,
    ov_at: u64,
    ov_dur: u64,
    /// Веха 150 — БУФЕР ОБМЕНА: вид и content-id того, что в нём лежит. `None` — пуст.
    ///
    /// Здесь только ИМЯ содержимого: байты лежат в store, и композитор их не возит и не хранит
    /// (ADR 0016). Корень `clip/current` на них держит он же — иначе сборка мусора store забрала
    /// бы скопированное как недостижимое, а заодно буфер не пережил бы перезагрузку.
    clip: Option<(u8, [u8; 32])>,
    /// Веха 150.1 — что тащат ПРЯМО СЕЙЧАС. `None` — ничего не тащат.
    carry: Option<Payload>,
    /// Веха 151 — идёт сбор сеанса. `None` — не идёт.
    saving: Option<Saving>,
    /// Веха 151.1 — что записано в `session/current` НАШИМИ руками. Сверяем с этим, чтобы не
    /// писать одно и то же: на неподвижном столе сеанс не стоит ни байта записи.
    session_last: String,
    /// Когда сверялись в прошлый раз (монотонные нс).
    session_at: u64,
    /// Веха 150.1 — уронённое, которое ещё не забрали: `(окно, вид, content-id)`.
    ///
    /// Живёт между `EV_DROP` и `OP_DROP` и отдаётся ровно один раз — тому окну, в которое
    /// целились. Копить их незачем: рука роняет по одному, и вторая посылка означала бы, что
    /// первую не забрали, то есть она никому не нужна.
    dropped: Option<(u32, u8, [u8; 32])>,
    /// Право на store: нужно, чтобы двигать корень буфера обмена. Хранится полем, а не тянется
    /// параметром через полдюжины вызовов, — композитору оно нужно и так, с самого запуска.
    store: usize,
    /// Веха 155 — право ОБЗОРА процессов (`sysview:rwg!` в конфиге), [`sys::NO_CAP`] — не выдано.
    ///
    /// Композитору оно нужно ровно для двух вещей, и обе — про раздачу, а не про слежку: узнать
    /// у ядра ИМЯ просителя (подделать его нельзя) и отдать урезанную копию тому, кого назвал
    /// конфиг. Помечено «не наследуется», поэтому окна его не получают (Веха 154).
    sysview: usize,
    /// Веха 157 — право ВЫКЛЮЧИТЬ машину (`power:wg!`). Композитор гасит систему сам
    /// (`Super+Shift+Q`) и отдаёт это право названным в конфиге — панели и шеллу.
    power: usize,
    /// Веха 166 — КАНАЛ К СЕРВЕРУ СЕТИ (`endpoint:net-srv` в строке композитора). Сам композитор
    /// в сеть не ходит: право у него затем же, зачем `sysview` и `power`, — раздать названным в
    /// конфиге (`desktop net <имя>`). Без этого у окна нет сети вовсе: клиенты композитора
    /// рождаются его спавном, а стартовый набор им объявляет он.
    netcap: usize,
    /// Веха 155/157 — что кому отдавать: `(вид права, имя программы)` из `desktop`-строк.
    grants: Vec<(u8, String)>,
    /// Веха 166.1 — когда последний раз сверяли живость ЧУЖИХ хозяев окон по списку процессов.
    liveness_at: u64,
    /// Веха 168 — накопленные УВЕДОМЛЕНИЯ, свежие первыми, и номер для следующего.
    notes: Vec<Note>,
    next_note: u32,
    /// Какое из них сейчас висит всплывашкой.
    toast: Option<Toast>,
    /// Веха 168.2 — сколько её ВИДНО на этом кадре. Считается раз за оборот ([`Wm::animate`]), а
    /// не в строке отрисовки: строке пришлось бы спрашивать время у ядра, то есть делать по
    /// системному вызову на каждую строку экрана.
    toast_box: Option<At<Screen>>,
    /// Веха 168.3 — счёт кадров экрана и «вёл ли композитор своё движение на этом обороте».
    ///
    /// Флаг нужен счётчику, чтобы отличить ПРОСТОЙ от РЫВКА: между кадрами может лежать секунда
    /// просто потому, что ничего не происходило, и считать её пропущенным кадром — врать самому
    /// себе. Кадр «в работе» — тот, на котором либо приехало чужое содержимое, либо двигались мы
    /// сами.
    frames: Frames,
    anim_busy: bool,
    /// Веха 168.1 — «не беспокоить»: всплывашек нет, счёт идёт.
    dnd: bool,
    /// Веха 167 — модификаторы клавиатуры, как их видел последний раз. Уезжают клиенту вместе
    /// со щелчком мыши: у события мыши своих модификаторов нет ни в железе, ни в ядре.
    kmods: u8,
    /// Начало полосы СВОЕГО стола в координатах обзора — точка, в которую наезжает камера.
    /// Считается там же, где сам обзор: иначе разошлось бы с ним при первой же правке.
    ov_band_y: i32,
    /// Веха 140 — снимок того, что видит бар: `(стол, столов, окно в фокусе)`. Сравнивается раз
    /// за оборот, и подписчикам уходит `EV_STATUS` только при РАЗНИЦЕ.
    ///
    /// Одно место, а не рассылка из `sync_focus`, `switch_space` и `tidy_spaces`: состояние
    /// меняют ещё закрытие окна, обзор и раскладка, и каждый новый путь пришлось бы вспоминать.
    /// Забытая рассылка — это бар, молча показывающий прошлое.
    /// Веха 145 — пятым идёт ОБЗОР: он тоже меняет то, что бару надо знать (см. `win::ST_OVERVIEW`).
    status: (usize, usize, Option<u32>, usize, bool, usize, bool),
}

/// Окно в обзоре: куда его уменьшили и с какого стола оно родом.
struct OvItem {
    id: u32,
    space: usize,
    /// Место эскиза НА ЭКРАНЕ: камера обзора уже учтена. Это третье место, где встречались
    /// лента и экран, — и до типизации (Веха 149.2) отличить его от места окна в ленте было
    /// нечем, обе величины были четвёрками чисел.
    r: At<Screen>,
}

/// Потолок списка повреждений. Список нужен, чтобы движение курсора в углу не тянуло за собой
/// перерисовку окна в другом углу; но и длинный список вреден — накладные расходы на каждый
/// прямоугольник свои. При переполнении всё сливается в один охватывающий.
const DAMAGE_MAX: usize = 8;

/// Знаковое расстояние от пикселя до края скруглённого прямоугольника, в 1/256 пикселя
/// (отрицательное — внутри). Веха 125.1.
///
/// Здесь была ошибка, из-за которой владелец видел «то толстую, то тонкую обводку», пропадающие
/// рамки и мусор в углах: форма и её сглаживание считались ДВУМЯ разными способами — бинарный
/// отступ края отдельно, доля покрытия отдельно, — и в углах они расходились. Обводка при этом
/// отмерялась от бинарного отступа, поэтому её толщина гуляла от строки к строке.
///
/// Теперь одно число отвечает на все вопросы сразу: попал ли пиксель в окно (`d < 0`), насколько
/// он накрыт (доля от `d`), и рамка это или содержимое (`d > -BORDER`). Формула стандартная для
/// скруглённого прямоугольника; считаем в полупикселях, чтобы не терять точность на целых.
///
/// Веха 169 — а КОРЕНЬ берётся с точностью 1/128 полупикселя, а не целым. Целый давал на весь
/// край угла три уровня покрытия (0, половина, полностью): пиксель, накрытый на четыре пятых,
/// светился наполовину, и по всем скруглениям системы шла рябь. Подробный разбор — у близнеца
/// этой формулы в тулките (`ui::paint::rrect_sd`); две копии обязаны совпадать, иначе окно и
/// панель скругляются по-разному.
fn rrect_sd(px: i32, py: i32, x: i32, y: i32, w: i32, h: i32, r: i32) -> i32 {
    // Всё в удвоенных единицах: центр прямоугольника попадает между пикселями.
    let ax = (2 * px - (2 * x + w - 1)).abs();
    let ay = (2 * py - (2 * y + h - 1)).abs();
    let qx = ax - (w - 1 - 2 * r);
    let qy = ay - (h - 1 - 2 * r);
    let (mx, my) = (qx.max(0), qy.max(0));
    // Длина сразу в 1/256 пикселя: удвоенные ×128, то есть корень из `v · 2¹⁴`.
    let len = ((((mx * mx + my * my) as i64) << 14).isqrt()) as i32;
    let inside = qx.max(qy).min(0) * 128;
    len + inside - 2 * r * 128
}

impl Wm {
    // ── пиксели ────────────────────────────────────────────────────────────────────────
    //
    // Пишем ПРЯМО во фреймбуфер (он write-combining с Вехи 116.1 — 1,3+ ГБ/с на железе), без
    // теневого кадра: лишняя копия экрана стоила бы 4 МиБ памяти и второго прохода по ним.

    #[inline(always)]
    fn pack(&self, c: (u8, u8, u8)) -> u32 {
        ((c.0 as u32 >> self.rgb[0].1) << self.rgb[0].0)
            | ((c.1 as u32 >> self.rgb[1].1) << self.rgb[1].0)
            | ((c.2 as u32 >> self.rgb[2].1) << self.rgb[2].0)
    }

    /// Разобрать пиксель обратно в RGB — нужно смешиванию (сглаживание углов, дальше прозрачность).
    #[inline(always)]
    fn unpack(&self, px: u32) -> (u8, u8, u8) {
        // Веха 142.1 — восьмибитные каналы (все живые режимы, кроме 16-битных) разбираются
        // сдвигом, без деления. Общий путь ниже остаётся ради честности: 5-битное «31» обязано
        // стать 255, а не 248, — но платить за это шестью делениями на пиксель в каждом
        // смешивании не за что.
        if self.rgb8 {
            return (
                ((px >> self.rgb[0].0) & 0xff) as u8,
                ((px >> self.rgb[1].0) & 0xff) as u8,
                ((px >> self.rgb[2].0) & 0xff) as u8,
            );
        }
        let mut out = [0u8; 3];
        for (i, o) in out.iter_mut().enumerate() {
            let (pos, size) = self.info.rgb[i];
            let size = size.clamp(1, 8);
            let v = (px >> pos) & ((1u32 << size) - 1);
            *o = ((v * 255) / ((1u32 << size) - 1).max(1)) as u8;
        }
        (out[0], out[1], out[2])
    }

    /// Смешать цвет с тем, что уже лежит в пикселе, в пропорции `a` (0..256).
    #[inline(always)]
    fn blend(&self, dst: u32, src: (u8, u8, u8), a: u32) -> u32 {
        if a >= 256 {
            return self.pack(src);
        }
        if a == 0 {
            return dst;
        }
        let d = self.unpack(dst);
        let mix = |s: u8, d: u8| ((s as u32 * a + d as u32 * (256 - a)) / 256) as u8;
        self.pack((mix(src.0, d.0), mix(src.1, d.1), mix(src.2, d.2)))
    }

    #[inline]
    fn put(&self, x: i32, y: i32, px: u32) {
        if x < 0 || y < 0 || x >= self.info.width as i32 || y >= self.info.height as i32 {
            return;
        }
        let bpp = self.info.bpp / 8;
        let dst = FB_VA + y as usize * self.info.pitch + x as usize * bpp;
        unsafe {
            match bpp {
                4 => core::ptr::write_volatile(dst as *mut u32, px),
                2 => core::ptr::write_volatile(dst as *mut u16, px as u16),
                _ => {
                    core::ptr::write_volatile(dst as *mut u8, px as u8);
                    core::ptr::write_volatile((dst + 1) as *mut u8, (px >> 8) as u8);
                    core::ptr::write_volatile((dst + 2) as *mut u8, (px >> 16) as u8);
                }
            }
        }
    }

    /// Записать `n` пикселей одного цвета подряд, начиная с (x, y). Границы проверены ОДИН раз
    /// на строку, а не на пиксель: именно это и стоило дорого — не сама запись во фреймбуфер.
    ///
    /// По 8 байт, пока есть пары: замер на X54C (Веха 116.1) дал 3036 МБ/с против 1784 на
    /// четырёхбайтных записях. Write-combining любит длинные последовательные пачки.
    fn fill_run(&self, x: i32, y: i32, n: usize, px: u32) {
        if y < 0 || y >= self.info.height as i32 || n == 0 {
            return;
        }
        let bpp = self.info.bpp / 8;
        if bpp != 4 {
            for i in 0..n as i32 {
                self.put(x + i, y, px);
            }
            return;
        }
        let mut dst = FB_VA + y as usize * self.info.pitch + x as usize * bpp;
        let two = (px as u64) | ((px as u64) << 32);
        let mut i = 0usize;
        unsafe {
            while i + 1 < n {
                core::ptr::write_volatile(dst as *mut u64, two);
                dst += 8;
                i += 2;
            }
            if i < n {
                core::ptr::write_volatile(dst as *mut u32, px);
            }
        }
    }

    /// Записать готовую строку пикселей из RAM.
    fn write_row(&self, x: i32, y: i32, src: &[u32]) {
        if y < 0 || y >= self.info.height as i32 || src.is_empty() {
            return;
        }
        let bpp = self.info.bpp / 8;
        if bpp != 4 {
            for (i, px) in src.iter().enumerate() {
                self.put(x + i as i32, y, *px);
            }
            return;
        }
        let mut dst = FB_VA + y as usize * self.info.pitch + x as usize * bpp;
        let mut i = 0usize;
        unsafe {
            while i + 1 < src.len() {
                let two = (src[i] as u64) | ((src[i + 1] as u64) << 32);
                core::ptr::write_volatile(dst as *mut u64, two);
                dst += 8;
                i += 2;
            }
            if i < src.len() {
                core::ptr::write_volatile(dst as *mut u32, src[i]);
            }
        }
    }

    fn fill_rect(&self, x: i32, y: i32, w: i32, h: i32, c: (u8, u8, u8)) {
        let px = self.pack(c);
        let x0 = x.max(0);
        let x1 = (x + w).min(self.info.width as i32);
        if x1 <= x0 {
            return;
        }
        for yy in y.max(0)..(y + h).min(self.info.height as i32) {
            self.fill_run(x0, yy, (x1 - x0) as usize, px);
        }
        fence();
    }

    // ── композиция ─────────────────────────────────────────────────────────────────────

    /// Отметить прямоугольник как требующий перерисовки (Веха 120.2).
    ///
    /// Раньше каждое событие рисовало само, немедленно. У мыши это означало до тридцати двух
    /// перерисовок на один оборот цикла — по числу событий в пачке, — и окно продолжало ехать
    /// уже после того, как человек отпустил кнопку: очередь событий отставала от руки.
    /// Теперь событие меняет только СОСТОЯНИЕ, а рисуется всё один раз в конце оборота.
    fn damage(&mut self, r: At<Screen>) {
        // Пиксель запаса со всех сторон: сглаженный край живёт на границе прямоугольника, и
        // ровно по границе его обрезало бы — отсюда оставшиеся «кусочки обводки».
        let r = r.inset(-1).intersect(self.screen());
        if r.is_empty() {
            return;
        }
        // Пересекающиеся области сливаем: рисовать одни и те же пиксели дважды за оборот незачем.
        for d in self.damage.iter_mut() {
            if !d.intersect(r).is_empty() {
                *d = d.union(r);
                return;
            }
        }
        if self.damage.len() >= DAMAGE_MAX {
            let all = self.damage.drain(..).fold(r, At::union);
            self.damage.push(all);
            return;
        }
        self.damage.push(r);
    }

    /// Весь экран — прямоугольник, которым обрезается всё остальное.
    fn screen(&self) -> At<Screen> {
        At::new(0, 0, self.info.width as i32, self.info.height as i32)
    }

    /// Продвинуть все анимации на текущий момент; `true` — что-то ещё движется.
    ///
    /// Область под движущимся окном помечается по ОБЪЕДИНЕНИЮ старого и нового положения: за
    /// окном обязан затираться след, и это ровно та же арифметика, что при перетаскивании
    /// (Веха 120.2) — только шаг задаёт время, а не рука.
    fn animate(&mut self, now: u64) -> bool {
        let mut moving = false;
        let mut done: Vec<u32> = Vec::new();
        // Веха 168.2 — всплывашка вытягивается и втягивается сама, без чужого участия. Пока она
        // в движении, помечаем ВЕСЬ её прямоугольник, а не выросшую полоску: за краем карточки
        // остаётся то, что было под ней, и стереть его должен тот же кадр.
        let box_now = self.toast_sheet(now);
        if box_now != self.toast_box {
            self.toast_box = box_now;
            self.damage_toast();
            moving = true;
        }
        for i in 0..self.wins.len() {
            let sc = self.scroll_x;
            let was = self.wins[i].place(sc);
            if self.wins[i].tick(now) {
                moving |= self.wins[i].dur != 0;
                let now_at = self.wins[i].place(sc);
                self.damage(was);
                self.damage(now_at);
            } else if self.wins[i].closing {
                // Помечаем ВЕСЬ путь сжатия, а не последний кадр: окно уменьшалось из полного
                // размера, и стереть нужно всё, что оно занимало. Последний кадр покрывает лишь
                // поджатый прямоугольник — остальное осталось бы призраком на экране (нашлось
                // проверкой: область просто не перерисовывалась).
                let r = self.wins[i].from.rect().union(self.wins[i].shown.rect());
                self.damage(r.to_screen(sc));
                done.push(self.wins[i].id);
            }
        }
        // Досжавшиеся окна убираем — их хозяина давно нет.
        let mut gone = false;
        for id in done {
            if let Some(k) = self.win_at(id) {
                // Буфер отпускаем здесь, а не при смерти клиента: всё время сжатия окно рисуется
                // своей последней картинкой, а лежит она в общей области. Ушли оба держателя —
                // страницы вернулись системе.
                self.drop_next(k);
                self.drop_buf(k);
                self.wins.remove(k);
                gone = true;
            }
        }
        // Веха 147.1 — окно ушло ЗДЕСЬ, мимо раскладки, а список обзора строит раскладка. Не
        // перестроив его, мы оставили бы в обзоре призрака: он рисуется, ловит мышь и уводит на
        // стол, где его уже нет.
        if gone && self.overview {
            self.build_overview(false);
        }
        // Лента: пока она едет, меняется положение ВСЕГО на экране — помечаем экран целиком.
        // Это дороже точечных прямоугольников, но честно: половина экрана и так меняется, а
        // попытка обойтись кусочками и оставляла те самые следы.
        if self.scroll_dur != 0 {
            let prev_scroll = self.scroll_x;
            let t = ((now.saturating_sub(self.scroll_at)) * 1024 / self.scroll_dur).min(1024) as i32;
            self.scroll_x = lerp(self.scroll_from, self.scroll_to, ease_out(t));
            if t >= 1024 {
                self.scroll_x = self.scroll_to;
                self.scroll_dur = 0;
            } else {
                moving = true;
            }
            // Лента сдвинулась на `dx` — в теневом кадре это СДВИГ ПАМЯТИ, а собрать заново
            // надо лишь открывшуюся полосу с краю. Полная пересборка здесь и делала движение
            // рваным: миллион пикселей на кадр против нескольких тысяч.
            let dx = self.scroll_x - prev_scroll;
            let (sw, shh) = (self.info.width as i32, self.info.height as i32);
            if dx != 0 && dx.abs() < sw && !self.overview {
                let pitch = sw as usize;
                let mut sh = core::mem::take(&mut self.shadow);
                let n = dx.unsigned_abs() as usize;
                for yy in 0..shh as usize {
                    let row = &mut sh[yy * pitch..(yy + 1) * pitch];
                    if dx > 0 {
                        row.copy_within(n.., 0); // лента уехала влево
                    } else {
                        row.copy_within(..pitch - n, n);
                    }
                }
                self.shadow = sh;
                // Открывшаяся полоса + запас на сглаженные края.
                let strip = if dx > 0 { (sw - n as i32 - 2, n as i32 + 2) } else { (0, n as i32 + 2) };
                self.damage(At::new(strip.0, 0, strip.1, shh));
                // Веха 142.1 — и ВСЁ, ЧТО С ЛЕНТОЙ НЕ ЕДЕТ. Сдвиг памяти двигает кадр целиком, а
                // едет в нём только лента: обои, панель и курсор стоят на месте. Их сдвинутые
                // пиксели никто не чинил до конца анимации, и это владелец увидел так: «курсор
                // сперва уезжает влево, потом телепортируется на место», «обои слегка дёргаются».
                // Одна причина на оба наблюдения.
                //
                // Пересобираем не весь кадр (это те самые миллион пикселей, ради которых сдвиг и
                // заводили), а ровно дополнение к окнам: щели между колонками, поля, панель.
                self.damage_outside_windows();
                let (cx, cy) = (self.cursor.x, self.cursor.y);
                self.damage(At::new(cx - n as i32 - 2, cy - 2, CUR_W + 2 * n as i32 + 4, CUR_H + 4));
                self.present_all = true;
            } else {
                self.damage(self.screen());
            }
        }

        // Веха 142.1 — переезд между столами. Двигается ВСЁ содержимое ленты (обе), поэтому кадр
        // помечаем целиком: сдвигом памяти тут не обойтись — на экране одновременно две ленты,
        // и едут они в РАЗНЫЕ стороны.
        if let Some(sl) = &self.slide {
            let done = now.saturating_sub(sl.at) >= sl.dur;
            self.damage(self.screen());
            if done {
                // Уходящие окна больше не рисуем — раскладка вернёт им `visible = false`.
                self.slide = None;
                self.relayout();
            } else {
                moving = true;
            }
        }

        // Камера обзора едет так же, но своим сроком: обзор показывает всю систему, и резкость
        // там суетлива.
        if self.overview && self.cam_dur != 0 {
            let t = ((now.saturating_sub(self.cam_at)) * 1024 / self.cam_dur).min(1024) as i32;
            let p = ease_out(t);
            self.ov_cam = (
                lerp(self.cam_from.0, self.cam_to.0, p),
                lerp(self.cam_from.1, self.cam_to.1, p),
            );
            if t >= 1024 {
                self.ov_cam = self.cam_to;
                self.cam_dur = 0;
            } else {
                moving = true;
            }
            self.build_overview(false);
        }

        // Переход «лента ↔ обзор» (Веха 126.6). Двигается ВСЁ на экране, поэтому кадр
        // помечаем целиком — как и при движении ленты: попытка обойтись кусочками оставляла
        // бы следы, а половина экрана всё равно меняется.
        if self.ov_dur != 0 {
            let t = ((now.saturating_sub(self.ov_at)) * 1024 / self.ov_dur).min(1024) as i32;
            self.ov_t = lerp(self.ov_from, self.ov_to, ease_out(t));
            self.damage(self.screen());
            if t >= 1024 {
                self.ov_t = self.ov_to;
                self.ov_dur = 0;
                if self.ov_to == 0 {
                    // Выход доигран: дальше рисует лента, список обзора больше не нужен.
                    self.overview = false;
                    self.ov.clear();
                }
            } else {
                moving = true;
            }
        }

        // Веха 147 — плитки запуска. Пока плитка ЖДЁТ, композитор просыпается на кадр: по ней
        // бежит полоса. Это единственный источник кадров без единого клиента на экране, и он
        // ограничен сроком (`LAUNCH_ANIM_NS`) — вечно бегущая полоса и есть тот самый спиннер,
        // который ADR 0016 запрещает.
        let screen = self.screen().rect();
        for i in 0..self.wins.len() {
            let Some(l) = &self.wins[i].launch else { continue };
            let waiting = l.done.is_none() && now.saturating_sub(l.since) < LAUNCH_ANIM_NS;
            let shot = l.shot;
            let place = self.wins[i].place(self.scroll_x);
            let seen = !place.rect().intersect(screen).is_empty();
            // Веха 169.1 — **плитка за краем экрана пикселей не держит.**
            //
            // Плитка рисуется композитором в СВОЙ буфер (`Win::own`), а он размером с окно: у
            // окна в колонку это без малого два мебибайта. Пока плиток было одна-две (запуск из
            // строки запуска), это не значило ничего. А сеанс из сорока окон поднимает сорок
            // плиток разом — восемьдесят мебибайт, то есть больше всей кучи композитора: он
            // падал с «memory allocation failed» прямо на загрузке. Нашлось проверкой «открыть
            // очень много терминалов»: окна открывались, а следующая загрузка не поднималась.
            //
            // Лента длиннее экрана, и почти все эти плитки за его краем. Рисовать их незачем, а
            // держать их пиксели — тем более: вернётся в кадр — нарисуем заново, это один кадр.
            // Снимок прошлого сеанса так не выбросить (перечитывать его пришлось бы из store),
            // но их число ограничено бюджетом ([`SNAP_BUDGET`]).
            if !seen {
                if !shot && self.wins[i].own.take().is_some() {
                    if let Some(l) = self.wins[i].launch.as_mut() {
                        l.drawn = None;
                    }
                }
                moving |= waiting;
                continue;
            }
            if self.render_launch(i, now) {
                self.damage(place);
            }
            moving |= waiting;
        }
        // Веха 168.3 — запоминаем для счётчика кадров: по этому флагу он отличит рывок от
        // простоя (см. [`Frames`]).
        self.anim_busy = moving;
        moving
    }

    /// Начать переход обзора. `to`: 1024 — в обзор, 0 — обратно в ленту.
    /// Считаем ОТ ТЕКУЩЕГО положения, а не от края: нажатый посреди перехода `Super+Tab`
    /// разворачивает движение с того места, где оно есть, а не дёргает картинку к началу.
    fn ov_start(&mut self, to: i32) {
        self.ov_from = self.ov_t;
        self.ov_to = to;
        self.ov_at = sys::monotonic_ns();
        self.ov_dur = self.anim * D_OV / 100 * 1_000_000;
        // `anim = 0` — переход не доигрывается вовсе, поэтому его конец надо исполнить здесь,
        // иначе обзор не открылся бы и не закрылся (см. `Win::start`).
        if self.ov_dur == 0 {
            self.ov_t = to;
            if to == 0 {
                self.overview = false;
                self.ov.clear();
            }
            self.damage(self.screen());
        }
    }

    /// Уйти из обзора: лента встаёт в КОНЕЧНОЕ положение сразу, а видимый переход к ней
    /// доигрывает преобразование обзора.
    ///
    /// Порядок именно такой, и он не произволен: преобразование целится в конечные
    /// прямоугольники ленты, и если бы те в этот момент ещё ехали своей анимацией, окна
    /// приехали бы мимо — а в конце перехода их дёрнуло бы на место.
    fn leave_overview(&mut self) {
        self.relayout();
        self.settle();
        // Пересчитать элементы под новую ленту (в обзоре могли выбрать другой стол), но КАМЕРУ
        // не трогать: она осталась там, где человек смотрел, — значит прыжка не будет.
        self.build_overview(false);
        self.ov_start(0);
    }

    /// Досрочно доиграть движение ленты и окон — поставить всё туда, где оно окажется.
    fn settle(&mut self) {
        self.scroll_x = self.scroll_to;
        self.scroll_dur = 0;
        for w in self.wins.iter_mut() {
            if w.dur != 0 {
                w.shown = w.to;
                w.dur = 0;
            }
        }
    }

    /// Начать закрытие окна: пиксели держим, пока доигрывает сжатие (Веха 125).
    ///
    /// Раньше окно исчезало в тот же миг, когда умирал его хозяин. Чтобы оно успело сжаться,
    /// композитор обязан ПЕРЕЖИВАТЬ клиента — на сто тридцать миллисекунд у окна появляется
    /// состояние «закрывается, хозяина уже нет».
    fn begin_close(&mut self, id: u32) {
        let now = sys::monotonic_ns();
        let Some(k) = self.win_at(id) else { return };
        if self.wins[k].closing {
            return;
        }
        // Веха 139 — поверхность слоя уходит СРАЗУ, без сжатия: обои, уползающие в точку, это
        // не «оживление», а поломка на экране; а бар, доигрывающий анимацию после смерти
        // хозяина, всё это время держал бы занятую зону, и лента дёргалась бы дважды.
        if self.wins[k].layer.is_some() {
            let r = self.wins[k].place(self.scroll_x);
            // Веха 168.3 — стираем НАРИСОВАННОЕ, а не всю поверхность: строка запуска растянута
            // на весь экран, а закрашена в ней одна карточка. Остальное прозрачно, и стол под ним
            // уже такой, каким он останется без слоя.
            let r = self.touched_on(k, r);
            self.drop_next(k);
            self.drop_buf(k);
            self.wins.remove(k);
            self.damage(r);
            self.recompute_work();
            return;
        }
        self.wins[k].closing = true;
        self.wins[k].visible = true;
        let target = self.wins[k].shown.popped();
        let d = self.anim * D_CLOSE / 100;
        self.wins[k].start(target, d, now);
        self.unlink(id);
        // Веха 137 — закрылось последнее окно стола, и стол должен исчезнуть (кроме того, на
        // котором стоим, и последнего). Делается ЗДЕСЬ, а не внутри `unlink`: тот же `unlink`
        // зовут при переезде окна между столами, и убрать стол посреди переезда значило бы
        // сдвинуть номер назначения у себя под руками.
        self.tidy_spaces();
    }

    /// Веха 142.1 — пометить весь экран, КРОМЕ занятого окнами ленты.
    ///
    /// Нужно после сдвига памяти теневого кадра: сдвиг двигает всё, а едет только лента. Считаем
    /// вычитанием прямоугольников — экран минус каждое видимое окно; остаток это щели, поля,
    /// поверхности слоя и всё, что стоит на месте.
    ///
    /// Если остаток дробится слишком мелко (окон много), честнее пометить экран целиком: два
    /// десятка мелких прямоугольников обходятся дороже одного большого.
    fn damage_outside_windows(&mut self) {
        let screen = self.screen();
        let mut rest: Vec<At<Screen>> = vec![screen];
        for i in 0..self.wins.len() {
            if !self.wins[i].visible || !self.wins[i].tiled() {
                continue;
            }
            let hole = self.wins[i].place(self.scroll_x);
            let mut next = Vec::with_capacity(rest.len() + 3);
            for r in rest {
                next.extend(r.subtract(hole).into_iter().filter(|s| !s.is_empty()));
            }
            rest = next;
            if rest.len() > 24 {
                self.damage(screen);
                return;
            }
        }
        for r in rest {
            self.damage(r);
        }
    }

    /// Нарисовать всё накопленное. Ровно один раз за оборот цикла — это и есть «кадр».
    fn flush(&mut self) {
        if self.damage.is_empty() {
            return;
        }
        // Веха 168.3 — два чтения часов на кадр: одно здесь, одно на границе сборки и вывода.
        // Ими и меряется «подлагивает» ([`Frames`]).
        let t0 = sys::monotonic_ns();
        let rects = core::mem::take(&mut self.damage);
        for r in &rects {
            self.repaint(*r);
        }
        let mid = sys::monotonic_ns();
        // На экран — либо те же области, либо весь кадр (после сдвига памяти изменилось всё).
        let pitch = self.info.width as usize;
        let sh = core::mem::take(&mut self.shadow);
        let mut px = 0u32;
        if self.present_all {
            self.present_all = false;
            for yy in 0..self.info.height as i32 {
                let off = yy as usize * pitch;
                self.write_row(0, yy, &sh[off..off + pitch]);
            }
            px = (self.info.width * self.info.height) as u32;
        } else {
            for r in &rects {
                let r = r.rect();
                for yy in r.y..r.bottom() {
                    let off = yy as usize * pitch + r.x as usize;
                    self.write_row(r.x, yy, &sh[off..off + r.w as usize]);
                }
                px += (r.w * r.h).max(0) as u32;
            }
        }
        self.shadow = sh;
        fence();
        self.frames.put(t0, mid, sys::monotonic_ns(), px, self.anim_busy);
    }

    /// Перерисовать прямоугольник экрана. Строка собирается ЦЕЛИКОМ в памяти — стол, окна в
    /// порядке z, курсор — и уходит во фреймбуфер одной последовательностью записей.
    ///
    /// Отсюда исчезло мерцание (Веха 120.3). Раньше область сначала заливалась цветом стола, а
    /// потом поверх рисовались окна: пиксель под окном писался ДВАЖДЫ, и глаз успевал поймать
    /// промежуточное состояние — при перетаскивании это выглядело как мигание окна. Теперь
    /// каждый пиксель экрана пишется ровно один раз за кадр.
    fn repaint(&mut self, r: At<Screen>) {
        let r = r.intersect(self.screen()).rect();
        if r.is_empty() {
            return;
        }
        // Собираем в ТЕНЕВОЙ кадр; на экран он уйдёт блитом в `flush`.
        let mut sh = core::mem::take(&mut self.shadow);
        let pitch = self.info.width as usize;
        for yy in r.y..r.bottom() {
            let off = yy as usize * pitch + r.x as usize;
            self.compose_row(&mut sh[off..off + r.w as usize], yy, r.x);
        }
        self.shadow = sh;
    }

    /// Собрать одну строку экрана: стол → нижние слои → окна → верхние слои → курсор.
    fn compose_row(&self, out: &mut [u32], yy: i32, x0: i32) {
        let desktop = self.pack(tri(self.th.desktop));
        out.fill(desktop);
        let x1 = x0 + out.len() as i32;

        // Веха 139 — слои ПОД окнами. Рисуются и в ленте, и в обзоре, и порядок здесь не
        // порядок в `wins`, а порядок СЛОЁВ: композитор поднимает окно в стопке при фокусе, и
        // всплывшее окно не должно уметь оказаться под обоями.
        self.draw_layers(out, yy, x0, x1, false);
        if self.overview {
            self.compose_row_overview(out, yy, x0, x1);
            self.draw_layers(out, yy, x0, x1, true);
            self.draw_cursor_row(out, yy, x0, x1);
            return;
        }

        // Веха 142.1 — смещения переезда столов: две ленты едут по вертикали как одно целое.
        // Веха 145.1 — приходящая едет ОТ `sl.from` К НУЛЮ, а уходящая жёстко привязана к ней
        // ровно на экран: пара не может разъехаться, и переключение посреди движения продолжает
        // картинку с того места, где она есть, а не прыгает на экран в сторону.
        let (dy_in, dy_out, sl_scroll) = match &self.slide {
            Some(sl) => {
                let dy = sl.offset(sys::monotonic_ns());
                (dy, dy - sl.dir * self.info.height as i32, sl.scroll)
            }
            None => (0, 0, 0),
        };

        for win in &self.wins {
            if !win.visible || !win.tiled() {
                continue;
            }
            // Рисуем ПО АНИМИРОВАННОМУ прямоугольнику, а не по тому, что назначила раскладка
            // (Веха 125). Отсюда следствие: содержимое приходится масштабировать — во время
            // переезда и сжатия окно на экране не совпадает со своим буфером.
            let active = self.focus == Some(win.id);
            let leaving = self.slide.as_ref().is_some_and(|s| s.ids.contains(&win.id));
            let (sc, dy) = if leaving { (sl_scroll, dy_out) } else { (self.scroll_x, dy_in) };
            let rect = win.shown.rect().to_screen(sc).offset(0, dy);
            self.draw_win_row(out, yy, x0, x1, rect, win, active, win.shown.a);
        }

        self.draw_layers(out, yy, x0, x1, true);
        self.draw_cursor_row(out, yy, x0, x1);
    }

    /// Строка поверхностей слоя: `over = false` — те, что под окнами, `true` — те, что над.
    ///
    /// Место у слоя ФИКСИРОВАННОЕ и в экранных координатах: ни прокрутка ленты, ни обзор его не
    /// трогают. Обои, уезжающие вместе с лентой, были бы не обоями, а очень широким окном.
    fn draw_layers(&self, out: &mut [u32], yy: i32, x0: i32, x1: i32, over: bool) {
        for win in &self.wins {
            if if over { !win.over() } else { !win.under() } {
                continue;
            }
            // Непрозрачность берём У ПОВЕРХНОСТИ, а не «256»: с Вехи 142 обои проявляются, и
            // прибитая единица делала их появление мгновенным независимо от анимации.
            self.draw_win_row(out, yy, x0, x1, win.place(0), win, false, win.shown.a);
        }
    }

    /// Одна строка ОДНОГО окна по экранному прямоугольнику — общая для ленты и обзора.
    ///
    /// Вынесено из [`Self::compose_row`] Вехой 126.6. До неё обзор рисовал окна своим кодом:
    /// квадратная рамка в один пиксель, без скруглений и сглаживания. Это были ДВА РАЗНЫХ ВИДА
    /// одного окна, и переход между ними анимировать нечем — как ни двигай прямоугольник, в
    /// момент переключения картинка менялась скачком. С общим кодом остаётся ровно одна
    /// разница — прямоугольник, — а прямоугольник анимируется.
    ///
    /// Масштаб берётся из соотношения прямоугольника и буфера окна: выборка ближайшего пикселя.
    /// Усреднение было бы красивее, но стоит нескольких чтений на каждый выводимый пиксель, а
    /// обзор перерисовывается на каждое движение курсора; текст в уменьшенном окне всё равно
    /// нечитаем — важно узнать окно по форме и цвету.
    #[allow(clippy::too_many_arguments)]
    fn draw_win_row(
        &self,
        out: &mut [u32],
        yy: i32,
        x0: i32,
        x1: i32,
        place: At<Screen>,
        win: &Win,
        active: bool,
        alpha: u32,
    ) {
        {
            // Пиксели пространства не имеют — дальше всё экранное.
            let Rect { x: fx, y: fy, w: fw, h: fh } = place.rect();
            // Веха 139 — рамка и скругление берутся У ОКНА, а не из констант: у поверхности
            // слоя их нет вовсе, и с нулевой рамкой этот же код превращается в честное
            // «содержимое от края до края» — без единой отдельной ветки на слои.
            let (bord, rad) = win.deco();
            if yy < fy || yy >= fy + fh || fw <= 2 * bord || fh <= 2 * bord {
                return;
            }
            let (sx, ex) = (fx.max(x0), (fx + fw).min(x1));
            if ex <= sx {
                return;
            }
            let border = self.unpack(self.pack(tri(if active { self.th.accent } else { self.th.border })));
            let (cw, ch) = (fw - 2 * bord, fh - 2 * bord);
            let src_row = (yy - fy - bord) * win.bh / ch.max(1);
            let px = win.px();
            let has_content = !px.is_empty() && src_row >= 0 && src_row < win.bh;
            // Расстояние до края нужно ТОЛЬКО у краёв. В середине окна ответ известен заранее,
            // а корень там стоил бы дороже всего остального вместе взятого: полноэкранная
            // перерисовка — это миллион пикселей, и миллион квадратных корней на кадр
            // превращали плавное движение в рывки (Веха 125.3).
            let top = yy - fy;
            let corner_row = top < rad || fy + fh - 1 - yy < rad;
            let edge_row = top < bord || fy + fh - 1 - yy < bord;
            let opaque = alpha >= 256;

            // Веха 144 — ПОВЕРХНОСТЬ СО ЗНАЧИМОЙ АЛЬФОЙ (панель на скруглённых островах).
            // Отдельная ветка, а не флажок в общем пути, ровно потому, что у слоя нет ни рамки,
            // ни скругления: строка здесь — это чистое наложение src-over, без единого вопроса
            // про углы. Влезь она в общий путь, «прозрачный пиксель» пришлось бы отличать от
            // «пикселя за рамкой», а те рисуются ЦВЕТОМ РАМКИ — панель получила бы серую сетку
            // вместо обоев в дырках.
            if win.alpha_px() {
                if !has_content {
                    return;
                }
                for xx in sx..ex {
                    let col = (xx - fx) * win.bw / fw.max(1);
                    let p = ((src_row * win.bw + col) * 4) as usize;
                    if col < 0 || col >= win.bw || p + 3 >= px.len() {
                        continue;
                    }
                    // Альфа кадра, приглушённая непрозрачностью самой поверхности: одно и то же
                    // число управляет и «панель полупрозрачна», и «панель проявляется».
                    let a = px[p + 3] as u32 * 256 / 255 * alpha / 256;
                    if a == 0 {
                        continue;
                    }
                    let i = (xx - x0) as usize;
                    out[i] = self.blend(out[i], (px[p], px[p + 1], px[p + 2]), a);
                }
                return;
            }

            // Веха 142.1 — БЫСТРАЯ СТРОКА: непрозрачное содержимое один-к-одному, вдали от углов
            // и рамки. Это подавляющее большинство пикселей кадра — вся середина каждого окна и
            // все обои целиком, — и общий путь считал на каждый из них две ЦЕЛОЧИСЛЕННЫЕ ДЕЛЕНИЯ
            // (столбец источника и смешивание) плюс пяток ветвей. Замер: сборка кадра 27 мс, из
            // них почти всё здесь; после этой ветки — единицы миллисекунд.
            //
            // Условие «один-к-одному» проверяется по размерам, а не предполагается: во время
            // переезда и в обзоре окно ЯВНО масштабируется, и там работает общий путь.
            if opaque && has_content && !corner_row && !edge_row {
                // Границы содержимого ЗАЖИМАЮТСЯ в перерисовываемый отрезок `[sx, ex)`, и оба
                // конца обязательны. Здесь стояли `max(sx)` и `min(ex)` — по одному зажиму на
                // конец, — и этого не хватало: если перерисовать надо кусок, целиком попавший в
                // рамку окна (а при трёх окнах лента ездит, и такие куски идут постоянно), один
                // из концов уезжал за отрезок. Индекс `-1` в срез строки — паника, композитор
                // мёртв, экран вернулся ядру. Ошибка Вехи 142.1, найдена владельцем.
                let cs = (fx + bord).clamp(sx, ex);
                let ce = (fx + fw - bord).clamp(sx, ex);
                let bp = self.pack(border);
                for xx in sx..cs {
                    out[(xx - x0) as usize] = bp;
                }
                // Копирование идёт СРЕЗАМИ, а не по индексам: так с каждого пикселя уходят
                // четыре проверки границ (три байта источника и запись), а их цена на миллионе
                // пикселей сравнима с самим преобразованием цвета.
                let off = cs - fx - bord; // столбец источника под `cs`; см. зажим выше
                if ce > cs && off >= 0 && win.bw == cw {
                    let b0 = (src_row * win.bw) as usize * 4 + off as usize * 4;
                    let b1 = b0 + (ce - cs) as usize * 4;
                    if b1 <= px.len() {
                        let dst = &mut out[(cs - x0) as usize..(ce - x0) as usize];
                        for (d, s) in dst.iter_mut().zip(px[b0..b1].chunks_exact(4)) {
                            *d = self.pack((s[0], s[1], s[2]));
                        }
                    }
                } else if ce > cs && off >= 0 {
                    // Веха 179 — МАСШТАБИРОВАННАЯ быстрая строка.
                    //
                    // До неё быстрый путь требовал «один-к-одному», и всё, что нарисовано в
                    // другом размере, уходило в общий путь — с проверкой углов, рамки и
                    // смешиванием на каждый пиксель. А в другом размере рисуется ровно то, что
                    // человек видит чаще всего: ОТКРЫТИЕ И ЗАКРЫТИЕ ОКНА (рамка едет от
                    // поджатого размера к полному) и обзор столов.
                    //
                    // Середина строки от этого не меняется: она по-прежнему непрозрачная, вдали
                    // от углов и рамки — то есть ей нужен только столбец источника. Он растёт
                    // равномерно, значит считается сложением (`err` копит остаток), а не
                    // делением на каждый пиксель. Это то же деление, разложенное в приращения:
                    // результат совпадает до пикселя.
                    let cwx = cw.max(1);
                    let n0 = off * win.bw;
                    let mut col = n0 / cwx;
                    let mut err = n0 % cwx;
                    let row = (src_row * win.bw) as usize * 4;
                    for xx in cs..ce {
                        let p = row + col.max(0) as usize * 4;
                        if col >= 0 && col < win.bw && p + 2 < px.len() {
                            out[(xx - x0) as usize] =
                                self.pack((px[p], px[p + 1], px[p + 2]));
                        }
                        err += win.bw;
                        while err >= cwx {
                            err -= cwx;
                            col += 1;
                        }
                    }
                }
                for xx in ce..ex {
                    out[(xx - x0) as usize] = bp;
                }
                return;
            }

            // Веха 179 — СТОЛБЕЦ ИСТОЧНИКА БЕЗ ДЕЛЕНИЯ НА ПИКСЕЛЬ.
            //
            // Сюда попадает всё, что нарисовано НЕ один-к-одному: обзор и — главное — открытие и
            // закрытие окна, где рамка едет от поджатого размера к полному. Замер на стенде:
            // сборка кадра во время анимации 7–9 мс против «единиц миллисекунд» на быстрой
            // строке (Веха 142.1), и виноват был `(xx - fx - bord) * bw / cw` — деление на
            // КАЖДЫЙ пиксель окна, шестьдесят раз в секунду.
            //
            // Столбец растёт равномерно, значит считается сложением: `err` копит остаток, и
            // столбец сдвигается, когда остаток перевалил ширину. Результат ТОТ ЖЕ до пикселя —
            // это то же деление, разложенное в приращения, а не приближение к нему.
            let cwx = cw.max(1);
            let c0 = (fx + bord).max(sx); // первый пиксель СОДЕРЖИМОГО: левее него счёт не нужен
            let n0 = (c0 - fx - bord).max(0) * win.bw;
            let mut col_at = n0 / cwx;
            let mut err = n0 % cwx;
            for xx in sx..ex {
                let col_now = col_at;
                if xx >= c0 {
                    err += win.bw;
                    while err >= cwx {
                        err -= cwx;
                        col_at += 1;
                    }
                }
                let dh = xx - fx;
                let near_x = dh < rad || fx + fw - 1 - xx < rad;
                let (cover, inner) = if corner_row && near_x {
                    let d = rrect_sd(xx, yy, fx, fy, fw, fh, rad);
                    (
                        (128 - d).clamp(0, 256) as u32,
                        (128 - (d + bord * 256)).clamp(0, 256) as u32,
                    )
                } else if edge_row || dh < bord || fx + fw - 1 - xx < bord {
                    (256, 0) // прямая часть рамки
                } else {
                    (256, 256) // содержимое
                };
                let cover = cover * alpha / 256;
                if cover == 0 {
                    continue;
                }
                let content = if has_content && inner != 0 {
                    let col = col_now;
                    let p = ((src_row * win.bw + col) * 4) as usize;
                    if col >= 0 && col < win.bw && p + 2 < px.len() {
                        (px[p], px[p + 1], px[p + 2])
                    } else {
                        border
                    }
                } else {
                    border
                };
                let i = (xx - x0) as usize;
                // Быстрый путь: непрозрачный пиксель в середине — просто цвет, без смешивания.
                if opaque && cover >= 256 && (inner >= 256 || inner == 0) {
                    out[i] = self.pack(if inner == 0 { border } else { content });
                    continue;
                }
                // Веха 169.1 — ОДИН мазок на пиксель, тем же доводом, что и в тулките
                // (`ui::paint::rrect_bordered`): два наложения подряд дают не то покрытие, о
                // котором просили. Здесь ошибка была в другую сторону — рамка клалась на ВЕСЬ
                // `cover`, а содержимое сверху, — но результат тот же род: угол окна на дуге
                // выходил плотнее и темнее, чем должен.
                //
                // Складываем ЦВЕТ по долям (`cover − ic` рамки, `ic` содержимого) и кладём его
                // один раз с покрытием `cover`.
                let ic = inner * cover / 256;
                let bc = cover - ic;
                let col = if ic == 0 {
                    border
                } else if bc == 0 {
                    content
                } else {
                    let mix = |b: u8, c: u8| ((b as u32 * bc + c as u32 * ic) / cover) as u8;
                    (
                        mix(border.0, content.0),
                        mix(border.1, content.1),
                        mix(border.2, content.2),
                    )
                };
                out[i] = self.blend(out[i], col, cover);
            }
        }
    }

    /// Обзор: те же окна тем же кодом ([`Self::draw_win_row`]), но через преобразование обзора.
    fn compose_row_overview(&self, out: &mut [u32], yy: i32, x0: i32, x1: i32) {
        let (a, bx, by) = self.ov_xform();
        // Полосы столов — ПОД окнами и только в самом обзоре (`ov_t`): на переходе они бы
        // разъезжались вместе с камерой и мигали по краям кадра.
        if self.ov_t > 512 {
            for &(band, sp) in &self.ov_bands {
                let active = sp == self.space;
                let band = band.rect();
                let (rx, ry) = (band.x * a / 1024 + bx, band.y * a / 1024 + by);
                let (rw, rh) = ((band.w * a / 1024).max(2), (band.h * a / 1024).max(2));
                if yy < ry || yy >= ry + rh {
                    continue;
                }
                let edge = yy == ry || yy == ry + rh - 1;
                let c = tri(if active { self.th.band_on } else { self.th.band });
                let (lo, hi) = (rx.max(x0), (rx + rw).min(x1));
                for x in lo..hi {
                    let i = (x - x0) as usize;
                    let on_side = x == rx || x == rx + rw - 1;
                    if edge || on_side {
                        out[i] = self.pack(c);
                    }
                }
            }
        }
        for it in &self.ov {
            let Some(k) = self.win_at(it.id) else { continue };
            let win = &self.wins[k];
            let it_r = it.r.rect();
            let rect = At::new(
                it_r.x * a / 1024 + bx,
                it_r.y * a / 1024 + by,
                (it_r.w * a / 1024).max(2 * BORDER + 2),
                (it_r.h * a / 1024).max(2 * BORDER + 2),
            );
            let active = self.focus == Some(it.id) && it.space == self.space;
            self.draw_win_row(out, yy, x0, x1, rect, win, active, 256);
        }
    }

    /// Преобразование обзора для текущего кадра: `экран = обзор × A / 1024 + B` (Веха 126.6).
    ///
    /// При `ov_t = 1024` (обзор целиком) это тождество — обзор рисуется ровно так, как посчитан.
    /// При `ov_t = 0` оно возвращает окна активного стола ТОЧНО туда, где они лежат в ленте:
    /// поэтому крайний кадр перехода совпадает с кадром ленты пиксель в пиксель, и переключения
    /// режима на экране не видно вовсе — видно только движение.
    ///
    /// Полосы прочих столов при этом уезжают за край сами собой, без единой строки кода на это:
    /// соседняя полоса отстоит на `band_h + OV_GAP`, а увеличение вдвое уносит её за высоту
    /// экрана. Ровно это и значит «камера наезжает на свой стол».
    fn ov_xform(&self) -> (i32, i32, i32) {
        let p = self.ov_t; // 0 — лента, 1024 — обзор
        let a = lerp(1024 * OV_DEN / OV_NUM, 1024, p);
        // Куда должно смещаться, чтобы при `p = 0` совпасть с лентой (вывод — в заметке
        // [[overview]]): по горизонтали камера обзора минус прокрутка ленты, по вертикали —
        // начало полосы СВОЕГО стола.
        let b0x = self.ov_cam.0 * OV_DEN / OV_NUM - self.scroll_x;
        let b0y = -self.ov_band_y * OV_DEN / OV_NUM;
        (a, lerp(b0x, 0, p), lerp(b0y, 0, p))
    }

    /// Веха 150.1 — место ЯРЛЫКА перетаскивания у курсора. `None` — ничего не тащат.
    ///
    /// Ярлык живёт в экранных координатах и привязан к руке, а не к окну, — как и сам курсор:
    /// груз человек несёт мимо окон, и принадлежать он им не может.
    ///
    /// У края экрана ярлык ПРИЖИМАЕТСЯ, а не уезжает за границу. Именно у края чаще всего и
    /// целятся в соседнее окно, и ярлык, ушедший за экран, перестал бы отвечать на единственный
    /// вопрос, ради которого нарисован: «что я сейчас несу».
    fn badge_at(&self, p: Pt<Screen>) -> Option<At<Screen>> {
        let c = self.carry.as_ref()?;
        let w = c.label.chars().count() as i32 * sys::glyph::W as i32 + 2 * BADGE_PAD_X;
        let h = sys::glyph::H as i32 + 2 * BADGE_PAD_Y;
        let sc = self.screen().rect();
        Some(At::new(
            (p.x + CUR_W - 2).clamp(0, (sc.w - w).max(0)),
            (p.y + CUR_H - 4).clamp(0, (sc.h - h).max(0)),
            w,
            h,
        ))
    }

    /// Сколько места занимает УКАЗАТЕЛЬ целиком: курсор и ярлык под ним.
    ///
    /// Одна функция на оба, потому что помечать их порознь — это ровно тот способ оставить след
    /// на экране, на котором Веха 121.2 уже стояла с курсором: помечено старое место, а новое в
    /// пометку не попало.
    fn pointer_rect(&self, p: Pt<Screen>) -> At<Screen> {
        let cur = p.rect(CUR_W, CUR_H);
        match self.badge_at(p) {
            Some(b) => cur.union(b),
            None => cur,
        }
    }

    fn damage_pointer(&mut self, p: Pt<Screen>) {
        let r = self.pointer_rect(p);
        self.damage(r);
    }

    /// Веха 150.1 — ЯРЛЫК ПЕРЕТАСКИВАНИЯ: рамка, заливка и подпись шрифтом ядра.
    ///
    /// Рисуется строкой, как и всё остальное в кадре (Веха 120.3): пиксель экрана пишется ровно
    /// один раз за кадр, и ярлык — не исключение, а такой же участник сборки строки.
    fn draw_badge_row(&self, out: &mut [u32], yy: i32, x0: i32, x1: i32) {
        let (Some(c), Some(b)) = (self.carry.as_ref(), self.badge_at(self.cursor)) else {
            return;
        };
        let r = b.rect();
        let ry = yy - r.y;
        if ry < 0 || ry >= r.h {
            return;
        }
        let ink = self.pack(tri(self.th.accent));
        let bg = self.pack(tri(self.th.bg));
        for xx in r.x.max(x0)..r.right().min(x1) {
            let edge = ry == 0 || ry == r.h - 1 || xx == r.x || xx == r.right() - 1;
            out[(xx - x0) as usize] = if edge { ink } else { bg };
        }
        let gy = ry - BADGE_PAD_Y;
        if gy < 0 || gy >= sys::glyph::H as i32 {
            return;
        }
        let mut cx = r.x + BADGE_PAD_X;
        for ch in c.label.chars() {
            let bits = sys::glyph::rows(ch)[gy as usize];
            for bit in 0..8 {
                let xx = cx + bit;
                if bits & (0x80 >> bit) != 0 && xx >= x0 && xx < x1 {
                    out[(xx - x0) as usize] = ink;
                }
            }
            cx += sys::glyph::W as i32;
        }
    }

    /// Курсор поверх всего: он не принадлежит ни одному окну.
    fn draw_cursor_row(&self, out: &mut [u32], yy: i32, x0: i32, x1: i32) {
        // Веха 168 — всплывашка ПОД курсором и ярлыком: она сообщение, а они — рука человека,
        // и закрывать руку сообщением нельзя.
        self.draw_toast_row(out, yy, x0, x1);
        // Ярлык — ПОД курсором: он говорит, что несут, а курсор говорит, куда целятся, и
        // закрывать второе первым нельзя.
        self.draw_badge_row(out, yy, x0, x1);
        let cy = yy - self.cursor.y;
        if cy >= 0 && cy < CUR_H {
            let fill = self.pack(if self.buttons != 0 { tri(self.th.accent) } else { (255, 255, 255) });
            let edge = self.pack((0, 0, 0));
            for (col, ch) in CURSOR[cy as usize].bytes().enumerate() {
                if ch == b' ' {
                    continue;
                }
                let xx = self.cursor.x + col as i32;
                if xx >= x0 && xx < x1 {
                    out[(xx - x0) as usize] = if ch == b'#' { edge } else { fill };
                }
            }
        }
    }

    // ── раскладка колонками (Веха 121) ─────────────────────────────────────────────────────

    fn win_at(&self, id: u32) -> Option<usize> {
        self.wins.iter().position(|w| w.id == id)
    }

    /// Веха 140 — поверхность слоя под точкой, которой достаётся мышь. `None` — там её нет.
    ///
    /// Только слои НАД окнами (бар, всплывающее): они и нарисованы поверх, значит человек целится
    /// в них. Слои ПОД окнами мыши не получают вовсе — обои лежат под всем экраном, и отдавать им
    /// указатель значило бы, что до окон он не доходит никогда. Клик по пустому месту стола
    /// поэтому не делает ничего, и это ровно то, чего от него ждут.
    ///
    /// Лента при этом не при чём (`scroll` = 0): слой не ездит с ней и не уменьшается обзором.
    fn layer_at(&self, p: Pt<Screen>) -> Option<usize> {
        self.wins
            .iter()
            .rposition(|w| w.visible && w.over() && !w.closing && w.hit_frame(p, 0))
    }

    /// Ширина колонки в пикселях по её пресету — от РАБОЧЕЙ ОБЛАСТИ, а не от экрана.
    /// Веха 142 — сколько пикселей руки стоит один шаг перетаскивания: `(по X, по Y)`.
    ///
    /// Для ПЕРЕСТАНОВКИ шаг — половина ширины колонки и четверть высоты рабочей области: рука
    /// проходит примерно то расстояние, на которое окно и переедет, поэтому движение читается
    /// как перенос, а не как переключатель. Для ШИРИНЫ шаг мельче: ступеней всего четыре
    /// ([`WIDTHS`]), и проходить экран ради последней было бы утомительно.
    fn drag_steps(&self, resize: bool) -> (i32, i32) {
        let (ow, oh) = (self.work.rect().w, self.work.rect().h);
        if resize {
            return ((ow / 10).max(40), i32::MAX);
        }
        let cw = self.cols.get(self.cur).map_or(ow / 2, |c| self.col_width(c));
        ((cw / 2).max(60), (oh / 4).max(60))
    }

    fn col_width(&self, c: &Column) -> i32 {
        let (n, d) = WIDTHS[c.width.min(WIDTHS.len() - 1)];
        (self.work.rect().w - GAP) * n / d - GAP
    }

    /// Веха 139 — где лежит поверхность слоя: якорь + запрошенный размер → прямоугольник экрана.
    ///
    /// Прижата к обоим краям оси — растянута по ней (обои прижаты ко всем четырём и занимают
    /// экран целиком). Прижата к одному — стоит у него своим размером. Ни к одному — по центру:
    /// это не «правильное» поведение, а единственное осмысленное на бессмысленный запрос.
    ///
    /// Считается от ЭКРАНА, а не от рабочей области: слой сам её и определяет, и считать его
    /// место от неё значило бы бесконечно уточнять само себя.
    fn layer_rect(&self, l: &LayerCfg, w: i32, h: i32) -> At<Screen> {
        let (sw, sh) = (self.info.width as i32, self.info.height as i32);
        let axis = |anchor_lo: bool, anchor_hi: bool, size: i32, screen: i32| match (
            anchor_lo, anchor_hi,
        ) {
            (true, true) => (0, screen),
            (true, false) => (0, size.min(screen)),
            (false, true) => ((screen - size).max(0), size.min(screen)),
            (false, false) => (((screen - size) / 2).max(0), size.min(screen)),
        };
        let (x, rw) = axis(
            l.anchor & win::ANCHOR_LEFT != 0, l.anchor & win::ANCHOR_RIGHT != 0, w, sw,
        );
        let (y, rh) = axis(
            l.anchor & win::ANCHOR_TOP != 0, l.anchor & win::ANCHOR_BOTTOM != 0, h, sh,
        );
        At::new(x, y, rw, rh)
    }

    /// Веха 139 — пересчитать РАБОЧУЮ ОБЛАСТЬ: экран минус зоны, занятые слоями.
    ///
    /// Это и есть весь смысл «занятой зоны»: бар сверху не накрывает окна, а сдвигает их —
    /// иначе первая строка терминала уходила бы под панель. Отсчитывается зона от края ЭКРАНА,
    /// а не от края поверхности: так два бара на одном краю просто не складываются в лесенку, а
    /// перекрываются, и это честнее, чем зависимость раскладки от порядка запуска клиентов.
    fn recompute_work(&mut self) {
        let (sw, sh) = (self.info.width as i32, self.info.height as i32);
        let (mut x0, mut y0, mut x1, mut y1) = (0, 0, sw, sh);
        for w in &self.wins {
            let Some(l) = w.layer else { continue };
            if l.exclusive <= 0 || w.closing {
                continue;
            }
            // Зона имеет смысл только у прижатого к ОДНОМУ краю оси: «панель посередине отняла
            // тридцать пикселей» не значит ничего — непонятно, с какой стороны.
            let (t, b) = (l.anchor & win::ANCHOR_TOP != 0, l.anchor & win::ANCHOR_BOTTOM != 0);
            let (le, r) = (l.anchor & win::ANCHOR_LEFT != 0, l.anchor & win::ANCHOR_RIGHT != 0);
            match (t, b) {
                (true, false) => y0 = y0.max(l.exclusive),
                (false, true) => y1 = y1.min(sh - l.exclusive),
                _ => {}
            }
            match (le, r) {
                (true, false) => x0 = x0.max(l.exclusive),
                (false, true) => x1 = x1.min(sw - l.exclusive),
                _ => {}
            }
        }
        // Панель во весь экран не должна оставлять раскладку с отрицательной шириной: окну
        // всегда есть куда лечь, даже если это выглядит тесно.
        let work = At::new(x0, y0, (x1 - x0).max(MIN_WORK), (y1 - y0).max(MIN_WORK));
        if work != self.work {
            self.work = work;
            self.relayout();
        }
    }

    /// Геометрия ленты в ЕЁ СОБСТВЕННЫХ координатах: рамки окон и полная ширина ленты.
    ///
    /// Чистая функция, ничего не меняющая, — и это важно: по ней живут ДВА потребителя,
    /// раскладка экрана и обзор. Две копии одной арифметики разъехались бы на первой же правке
    /// (обзор показывал бы не то, что получится при выходе из него).
    fn strip_layout(&self, cols: &[Column]) -> (Vec<(u32, At<Strip>)>, i32) {
        // Веха 139 — считаем от РАБОЧЕЙ ОБЛАСТИ. Её начало входит прямо в координаты ленты, а не
        // прибавляется где-то потом: иначе смещение пришлось бы помнить и рисованию, и попаданию
        // мыши, и обзору — трём местам сразу, то есть трём случаям разойтись.
        // Лента ОБЪЯВЛЕНА начинающейся там же, где экран: прокрутка меряется именно оттуда,
        // поэтому перевод здесь с нулевым сдвигом — не фокус, а запись этого решения.
        let work = self.work.to_strip(0).rect();
        let (ox, oy, oh) = (work.x, work.y, work.h);
        let mut out = Vec::new();
        let mut x = ox + GAP;
        for c in cols {
            let cw = self.col_width(c);
            let n = c.ids.len().max(1) as i32;
            let cell = (oh - GAP) / n - GAP;
            for (wi, id) in c.ids.iter().enumerate() {
                let y = oy + GAP + wi as i32 * (cell + GAP);
                let h = if wi + 1 == c.ids.len() { oy + oh - GAP - y } else { cell };
                out.push((*id, At::new(x, y, cw, h)));
            }
            x += cw + GAP;
        }
        (out, x)
    }

    /// Пересчитать геометрию всех окон и прокрутку ленты; всем, у кого размер изменился, послать
    /// `EV_RESIZE`.
    ///
    /// Один пересчёт на любое изменение — вместо правки координат в каждом действии. Так
    /// «переехала колонка», «сменилась ширина», «закрылось окно» и «появилось новое» не могут
    /// разойтись в понимании того, где что лежит.
    fn relayout(&mut self) {
        let screen_h = self.info.height as i32;
        // Срок анимаций берём ДО цикла: внутри `self` уже занят изменяемой ссылкой на окно.
        let anim = self.anim;
        // Видно ровно то, что лежит на активном столе. Считаем это здесь, а не при
        // переключении: раскладка и так обходит все окна активной ленты — второй список
        // «кто виден» разошёлся бы с первым при первой же правке.
        // Уходящий стол дорисовывает переезд — его окна видимы, пока едут (Веха 142.1).
        let sliding: Vec<u32> = self.slide.as_ref().map(|s| s.ids.clone()).unwrap_or_default();
        // Веха 169.1 — **изменилось ли хоть что-нибудь**. Отсюда решается, помечать ли экран в
        // конце: подробности у самой пометки. Видимость сравниваем со СНИМКОМ до пересчёта — сам
        // пересчёт идёт в два захода (сперва всем «нет», потом попавшим в раскладку «да»), и
        // ловить изменение внутри первого захода значило бы поймать его у каждого окна ленты.
        let mut moved = false;
        let was_vis: Vec<bool> = self.wins.iter().map(|w| w.visible).collect();
        for w in self.wins.iter_mut() {
            // Закрывающееся окно остаётся видимым: его уже нет в раскладке, но сжатие доигрывает.
            // Поверхность слоя видна ВСЕГДА: обои и бар не принадлежат столу (Веха 139).
            w.visible = w.closing || !w.tiled() || sliding.contains(&w.id);
        }
        let (frames, _) = self.strip_layout(&self.cols);

        // Куда уехала лента: колонка в фокусе обязана быть видна целиком; если она шире рабочей
        // области, показываем её левый край.
        let (ox, ow) = (self.work.rect().x, self.work.rect().w);
        let mut x = ox + GAP;
        let mut want = self.scroll_to;
        for (i, c) in self.cols.iter().enumerate() {
            let cw = self.col_width(c);
            if i == self.cur {
                if x - want < ox + GAP {
                    want = x - ox - GAP;
                }
                if x + cw - want > ox + ow - GAP {
                    want = x + cw - (ox + ow) + GAP;
                }
            }
            x += cw + GAP;
        }
        if self.cols.is_empty() {
            want = 0;
        }
        if want != self.scroll_to {
            self.scroll_from = self.scroll_x;
            self.scroll_to = want;
            self.scroll_at = sys::monotonic_ns();
            self.scroll_dur = self.anim * 1_000_000;
            if self.scroll_dur == 0 {
                self.scroll_x = want;
            }
            moved = true;
        }

        let mut resized: Vec<(u32, i32, i32)> = Vec::new();
        for (id, f) in frames {
            let Some(k) = self.win_at(id) else { continue };
            let f = f.rect(); // раскладка отдала место В ЛЕНТЕ — `Shown` его и хранит
            self.wins[k].visible = true;
            // Клиенту назначается размер СОДЕРЖИМОГО: рамку и заголовок рисуем мы.
            let (cw2, ch2) = ((f.w - 2 * BORDER).max(32), (f.h - 2 * BORDER).max(32));
            self.wins[k].x = f.x;
            self.wins[k].y = f.y;
            let target = Shown {
                x: f.x,
                y: f.y,
                w: cw2 + 2 * BORDER,
                h: ch2 + 2 * BORDER,
                a: 256,
            };
            let now = sys::monotonic_ns();
            if self.wins[k].fresh {
                // Первое появление: растём из поджатого и проявляемся.
                self.wins[k].fresh = false;
                self.wins[k].shown = target.popped();
                self.wins[k].start(target, anim * D_OPEN / 100, now);
                moved = true;
            } else if self.wins[k].to != target {
                self.wins[k].start(target, anim, now);
                moved = true;
            }
            if self.wins[k].w != cw2 || self.wins[k].h != ch2 {
                moved = true;
                self.wins[k].w = cw2;
                self.wins[k].h = ch2;
                // Буфер НЕ трогаем: пусть старая картинка тянется, пока клиент не заведёт новый
                // (`OP_REBUF`). Обнулять его здесь значило бы чернить окно на всё время между
                // решением раскладки и ответом клиента — на складывании окон в стопку это
                // выглядело как артефакты (Веха 126.1).
                resized.push((id, cw2, ch2));
            }
        }
        let _ = screen_h;
        // Веха 142 — в ОБЗОРЕ пересобрать и его. Обзор рисуется по своему списку `ov`, и пока
        // раскладка меняла только ленту, новое окно, открытое из обзора (`Super+Return`), в этот
        // список не попадало: оно существовало, работало и получало ввод, но на экране его не
        // было до первого действия, которое обзор перестраивало. Одно место на всё — потому что
        // путей в раскладку много (открылось, закрылось, переехало, сменило ширину), и любой
        // забытый снова разошёлся бы с картинкой.
        if self.overview {
            self.build_overview(false);
        }
        for (id, w, h) in resized {
            if let Some(k) = self.win_at(id) {
                self.send(k, win::Event::Resize { w: w as u16, h: h as u16 });
            }
        }
        // Веха 169.1 — **экран целиком помечается только если раскладка ЧТО-ТО изменила.**
        //
        // Здесь стояла безусловная пометка всего экрана — миллион точек на каждый заход в
        // раскладку. Заходов много, и большинство ничего не двигают: фокус ходит за курсором
        // (Веха 121.1), и переезд мыши из окна в окно звал `relayout` ради подвижки ленты,
        // которой не требовалось. То есть плата шла за то, что на экране осталось прежним.
        //
        // Пометка нужна там, где перерисовать надо не окно, а ПРОМЕЖУТКИ: щели между колонками,
        // поля, освободившееся место. Всё это меняется ровно вместе с раскладкой — значит и
        // условие ровно одно: изменилась ли видимость, поехало ли окно, сменился ли размер или
        // сдвиг ленты. Само движение окон помечает себя само (`animate`: старое место ∪ новое).
        //
        // Обзор считаем изменившимся всегда: он перерисовывает эскизы всех окон разом, и его
        // «ничего не поменялось» стоит дешевле проверить пометкой, чем сравнением списка.
        moved |= self.overview;
        moved |= self.wins.iter().zip(&was_vis).any(|(w, &v)| w.visible != v);
        if moved {
            self.damage(At::new(0, 0, self.info.width as i32, screen_h));
        }
    }

    /// Пересчитать раскладку ОБЗОРА (Вехи 123, 123.1).
    ///
    /// Масштаб ФИКСИРОВАННЫЙ ([`OV_NUM`]/[`OV_DEN`]), а не «лишь бы всё влезло» — так сделано в
    /// niri, и владелец попросил так же. Разница не косметическая: при подгонке под содержимое
    /// каждое новое окно уменьшало ВСЕ остальные, то есть привычная картинка менялась от того,
    /// что где-то открылся ещё один терминал. При фиксированном окна просто уходят за край, и
    /// узнаваемость раскладки не зависит от их числа.
    ///
    /// Экран — это камера над столбцом столов: она наводится на стол в фокусе (по вертикали) и
    /// на окно в фокусе (по горизонтали). Всё, что не попало в кадр, честно остаётся за краем.
    fn build_overview(&mut self, recenter: bool) {
        self.ov.clear();
        self.ov_bands.clear();
        let (sw, sh) = (self.info.width as i32, self.info.height as i32);
        let band_h = sh * OV_NUM / OV_DEN;
        // Веха 137 — столы динамические, и пустых среди них не бывает нигде, кроме конца и
        // активного (это и есть инвариант `tidy_spaces`). Поэтому показываем ВСЕ: фильтр,
        // который здесь стоял, теперь ничего бы не отсекал, а прятал бы расхождение, если оно
        // всё-таки появится.
        let shown: Vec<usize> = (0..self.space_count()).collect();
        let me = shown.iter().position(|&i| i == self.space).unwrap_or(0) as i32;

        // Камера наводится ТОЛЬКО по осознанному выбору — клавишами, колесом, при входе в
        // обзор (Веха 123.2). Наведение мышью её не двигает, и это не лень, а необходимость:
        // стоило камере ехать за курсором, как окна разъезжались под ним, под курсором
        // оказывалось следующее, оно уезжало в центр — и так без конца. Среднее из трёх окон
        // выбрать было нельзя в принципе: оно перескакивало раньше, чем в него попадали.
        if recenter {
            let cam_y = GAP + me * (band_h + OV_GAP) + band_h / 2 - sh / 2;
            let focus_x = self
                .focused_id()
                .and_then(|id| {
                    let (frames, _) = self.strip_layout(&self.cols);
                    frames.iter().find(|f| f.0 == id).map(|f| {
                        let f = f.1.rect();
                        (f.x + f.w / 2) * OV_NUM / OV_DEN
                    })
                })
                .unwrap_or(sw / 2);
            self.aim_camera((focus_x - sw / 2, cam_y));
        }
        let (cam_x, cam_y) = self.ov_cam;

        for (bi, &sp) in shown.iter().enumerate() {
            let by = GAP + bi as i32 * (band_h + OV_GAP) - cam_y;
            // Своя полоса запоминается ДО отсечения: она может быть за кадром (камера уехала на
            // другой стол), а переходу её начало нужно в любом случае — это точка наезда.
            if sp == self.space {
                self.ov_band_y = by;
            }
            if by + band_h < 0 || by > sh {
                continue; // полоса целиком за кадром — считать её нечего
            }
            self.ov_bands.push((At::new(0, by, sw, band_h), sp));
            let cols: &[Column] =
                if sp == self.space { &self.cols } else { &self.spaces[sp].cols };
            let (frames, _) = self.strip_layout(cols);
            for (id, f) in frames {
                let f = f.rect();
                self.ov.push(OvItem {
                    id,
                    space: sp,
                    r: At::new(
                        f.x * OV_NUM / OV_DEN - cam_x,
                        by + f.y * OV_NUM / OV_DEN,
                        (f.w * OV_NUM / OV_DEN).max(1),
                        (f.h * OV_NUM / OV_DEN).max(1),
                    ),
                });
            }
        }
        // Веха 147.1 — ИНВАРИАНТ ОБЗОРА: полоса активного стола видна.
        //
        // Фокус всегда лежит в активном столе, и если его полоса ушла за кадр, человек управляет
        // тем, чего не видит: камера показывает один стол, а клавиши идут в другой. Владелец
        // поймал это как «камера уехала вниз, а фокус остался сверху» — редко и без видимой
        // причины.
        //
        // Причина в том, что координаты обзора СЧИТАЮТСЯ ОТ ЧИСЛА СТОЛОВ, а оно меняется под
        // ногами: досжавшееся окно исчезает вне раскладки (`animate`), опустевший стол снимает
        // `tidy_spaces`, — и все полосы ниже переезжают вверх на свою высоту. Камера остаётся в
        // пикселях старой раскладки и оказывается на чужой полосе.
        //
        // Чинить каждый такой путь по отдельности бессмысленно: их столько же, сколько причин
        // изменить число столов. Дешевле проверить сам инвариант там, где обзор и строится.
        let band_y = self.ov_band_y;
        if band_y + band_h <= 0 || band_y >= sh {
            let me_y = GAP + me * (band_h + OV_GAP) + band_h / 2 - sh / 2;
            let to = (self.ov_cam.0, me_y);
            // Только если ещё не едем туда же: иначе цель назначалась бы каждый кадр, и камера
            // ползла бы к ней бесконечно, всякий раз начиная путь заново.
            if self.cam_dur == 0 || self.cam_to != to {
                self.aim_camera(to);
            }
        }
        self.damage(At::new(0, 0, sw, sh));
    }

    /// Сколько столов существует СЕЙЧАС (Веха 137). Активный тоже занимает свой слот в
    /// `spaces` — его лента лишь временно вынута в поля `Wm`.
    fn space_count(&self) -> usize {
        self.spaces.len()
    }

    /// Пуст ли стол `i`. Активный спрашивать надо не у `spaces`: его лента вынута в поля `Wm`,
    /// и в массиве на его месте лежит пустышка. Об эту разницу спотыкается всё, что считает
    /// столы, — поэтому вопрос задаётся ровно в одном месте.
    fn space_is_empty(&self, i: usize) -> bool {
        if i == self.space {
            self.cols.is_empty()
        } else {
            self.spaces.get(i).is_none_or(|s| s.cols.is_empty())
        }
    }

    /// Веха 137 — привести число столов в порядок по правилу niri: **в конце всегда ровно один
    /// пустой стол, а опустевшие в середине исчезают**.
    ///
    /// Раньше столов было ровно девять — по числу цифр на клавиатуре. Это не «упрощение», а
    /// другая модель: в ней пустые столы всегда занимают места в обзоре, а десятый стол не
    /// существует, даже когда он нужен. Динамические столы откладывались до обзора («иначе про
    /// существование стола №7 узнать неоткуда»), и с Вехой 123 эта причина отпала.
    ///
    /// Активный стол не убираем, даже пустой: человек на нём стоит. Он исчезнет сам, когда с
    /// него уйдут, — как и в niri.
    fn tidy_spaces(&mut self) {
        let mut i = 0;
        while i < self.spaces.len() {
            let last = i + 1 == self.spaces.len();
            if !last && i != self.space && self.space_is_empty(i) {
                self.spaces.remove(i);
                if self.space > i {
                    self.space -= 1;
                }
                continue; // на месте удалённого теперь следующий — его и проверяем
            }
            i += 1;
        }
        if self.spaces.is_empty() {
            self.spaces.push(Space::default());
            self.space = 0;
        } else if !self.space_is_empty(self.spaces.len() - 1) {
            self.spaces.push(Space::default());
        }
    }

    /// Сделать стол `n` активным: ленты меняются местами (см. [[workspaces]]).
    ///
    /// Веха 137: после перехода число столов пересматривается — стол, с которого ушли пустым,
    /// исчезает, а за последним занятым появляется новый пустой.
    fn switch_space(&mut self, n: usize) {
        if n == self.space || n >= self.space_count() {
            return;
        }
        // Веха 142.1 — переезд столов виден. Раньше лента менялась мгновенно: только что было
        // одно, стало другое, и связь «куда я попал» приходилось достраивать в голове. В обзоре
        // переезда нет — там своя камера, и вторая анимация поверх неё была бы дракой.
        if self.anim > 0 && !self.overview {
            // Веха 145.2 — уезжает ровно ТА лента, с которой уходим, а не «всё, что видно».
            //
            // Здесь стоял отбор `tiled() && visible`, и посреди переезда он захватывал окна
            // ПРЕДЫДУЩЕЙ уходящей ленты: раскладка держит их видимыми, пока они доигрывают
            // (Веха 142.1). Переключил 1 → 2 и сразу обратно — и стол 1 попадал в уходящие
            // вместе со столом 2: приходить оказывалось нечему, обе ленты дружно улетали за
            // экран, а по концу переезда раскладка возвращала стол 1 на место прыжком. Ровно
            // это «уезжает далеко за стол и телепортируется обратно» и видно.
            //
            // Ленты старше предыдущей на экране не остаются: раскладка их спрячет, потому что
            // их нет ни в столе, ни в переезде. Быстрый пробег 1 → 2 → 3 обрывает первому
            // столу отъезд, но он к тому времени уже далеко за краем.
            let stale: &[u32] = self.slide.as_ref().map_or(&[], |s| s.ids.as_slice());
            let ids: Vec<u32> = self
                .wins
                .iter()
                .filter(|w| w.tiled() && w.visible && !stale.contains(&w.id))
                .map(|w| w.id)
                .collect();
            let now = sys::monotonic_ns();
            let dir = if n > self.space { 1 } else { -1 };
            // Веха 145.1 — новая лента начинает путь ОТ ТОГО МЕСТА, где картинка сейчас, плюс
            // экран в сторону перехода. Стол, с которого уходим, стоит ровно там, где он и
            // нарисован (`cur`), — поэтому подмена ленты посреди движения не видна вовсе.
            //
            // Отсюда же берётся приятная мелочь: переключил на 2 и тут же обратно — `cur` ещё
            // почти на экран, `dir` сменил знак, и `from` выходит около нуля. Экран не дёргается
            // совсем, потому что он никуда и не уехал.
            let cur = self.slide.as_ref().map_or(0, |sl| sl.offset(now));
            self.slide = Some(Slide {
                ids,
                scroll: self.scroll_x,
                dir,
                from: cur + dir * self.info.height as i32,
                at: now,
                dur: self.anim * D_OV / 100 * 1_000_000,
            });
        }
        self.spaces[self.space] = Space {
            cols: core::mem::take(&mut self.cols),
            cur: self.cur,
            scroll_x: self.scroll_x,
        };
        let s = core::mem::take(&mut self.spaces[n]);
        self.cols = s.cols;
        self.cur = s.cur;
        self.scroll_x = s.scroll_x;
        self.space = n;
        self.tidy_spaces();
    }

    /// Веха 140 — перейти на стол `n` целиком: лента, фокус, раскладка. Номер сверх числа столов
    /// не ошибка, а просьба «в самый дальний» (последний всегда пустой, Веха 137).
    ///
    /// Отдельным методом, потому что путей сюда стало два: аккорд `Super+N` и клик по столу в
    /// баре. Одно и то же действие, написанное дважды, разошлось бы на первой же правке.
    fn goto_space(&mut self, n: usize) {
        let n = n.min(self.space_count().saturating_sub(1));
        if n == self.space {
            return;
        }
        self.switch_space(n);
        self.sync_focus();
        self.relayout();
    }

    /// Навести камеру на новое место — не прыжком, а движением (Веха 125).
    fn aim_camera(&mut self, to: (i32, i32)) {
        if to == self.ov_cam && self.cam_dur == 0 {
            return;
        }
        self.cam_from = self.ov_cam;
        self.cam_to = to;
        self.cam_at = sys::monotonic_ns();
        self.cam_dur = self.anim * D_OV / 100 * 1_000_000;
        // `anim = 0` — ставим сразу: нулевой срок движение не доигрывает, а пропускает (см.
        // `Win::start`), и камера осталась бы там, где была.
        if self.cam_dur == 0 {
            self.ov_cam = to;
        }
    }

    /// Подвинуть камеру обзора минимально — так, чтобы окно `id` поместилось на экране целиком.
    ///
    /// Ничего не делает, если оно и так видно. Окно больше экрана прижимается левым/верхним
    /// краем: показать его целиком нельзя, а метаться между краями — хуже, чем не двигаться.
    fn ensure_visible(&mut self, id: u32) {
        let (sw, sh) = (self.info.width as i32, self.info.height as i32);
        let Some(it) = self.ov.iter().find(|it| it.id == id).map(|it| it.r.rect()) else {
            return;
        };
        let (mut dx, mut dy) = (0, 0);
        if it.x < GAP {
            dx = it.x - GAP;
        } else if it.x + it.w > sw - GAP {
            dx = (it.x + it.w - (sw - GAP)).min(it.x - GAP);
        }
        if it.y < GAP {
            dy = it.y - GAP;
        } else if it.y + it.h > sh - GAP {
            dy = (it.y + it.h - (sh - GAP)).min(it.y - GAP);
        }
        if dx == 0 && dy == 0 {
            return;
        }
        let to = (self.ov_cam.0 + dx, self.ov_cam.1 + dy);
        self.aim_camera(to);
    }

    /// Колонка и место окна в ней.
    fn locate(&self, id: u32) -> Option<(usize, usize)> {
        self.cols
            .iter()
            .enumerate()
            .find_map(|(ci, c)| c.ids.iter().position(|&x| x == id).map(|wi| (ci, wi)))
    }

    /// Окно в фокусе по нынешней колонке.
    fn focused_id(&self) -> Option<u32> {
        let c = self.cols.get(self.cur)?;
        c.ids.get(c.focus.min(c.ids.len().saturating_sub(1))).copied()
    }

    /// Синхронизировать `focus` с раскладкой и перерисовать обводку обоих окон.
    fn sync_focus(&mut self) {
        let was = self.focus;
        self.focus = self.focused_id();
        if was == self.focus {
            return;
        }
        for id in [was, self.focus].into_iter().flatten() {
            if let Some(k) = self.win_at(id) {
                self.damage_chrome(k);
            }
        }
    }

    /// Веха 151 — заменить номер окна во ВСЕХ лентах: плитка уступает место пришедшему окну.
    ///
    /// «Во всех» — потому что лент по хранению две штуки: активная вынута в поля `Wm`, прочие
    /// лежат в `spaces`. То же самое различие, ради которого существует [`Wm::unlink`], — и
    /// ровно на нём эта веха и споткнулась.
    ///
    /// **Как это выглядело.** До Вехи 151 плитки заводились только на активном столе: их создаёт
    /// `run`, а запускают его с того стола, где стоит человек, — поэтому замена, знавшая одну
    /// ленту, была верной и ошибки не содержала. Восстановление сеанса ставит плитки СРАЗУ НА ВСЕ
    /// столы, и окно, пришедшее на чужой стол, оказывалось в `wins`, но ни в одной ленте:
    /// невидимое, недостижимое и живое. Владелец увидел это так: «окна с другого стола не
    /// открываются» — хотя программы честно запускались, а в журнале стояло «сеанс поднят».
    fn relink(&mut self, old: u32, new: u32) {
        fn rename(cols: &mut [Column], old: u32, new: u32) {
            for c in cols.iter_mut() {
                for w in c.ids.iter_mut() {
                    if *w == old {
                        *w = new;
                    }
                }
            }
        }
        rename(&mut self.cols, old, new);
        for s in self.spaces.iter_mut() {
            rename(&mut s.cols, old, new);
        }
    }

    /// Убрать окно из ленты ЛЮБОГО стола; пустая колонка исчезает.
    ///
    /// Ищем везде, а не только на активном: программа с соседнего стола вправе завершиться, и
    /// её окно обязано исчезнуть оттуда, а не остаться призраком до перехода на тот стол.
    fn unlink(&mut self, id: u32) {
        for sp in self.spaces.iter_mut() {
            for ci in (0..sp.cols.len()).rev() {
                if let Some(wi) = sp.cols[ci].ids.iter().position(|&x| x == id) {
                    sp.cols[ci].ids.remove(wi);
                    if sp.cols[ci].ids.is_empty() {
                        sp.cols.remove(ci);
                        if sp.cur >= sp.cols.len() {
                            sp.cur = sp.cols.len().saturating_sub(1);
                        }
                    } else if sp.cols[ci].focus >= sp.cols[ci].ids.len() {
                        sp.cols[ci].focus = sp.cols[ci].ids.len() - 1;
                    }
                }
            }
        }
        if let Some((ci, wi)) = self.locate(id) {
            self.cols[ci].ids.remove(wi);
            if self.cols[ci].ids.is_empty() {
                self.cols.remove(ci);
                if self.cur >= self.cols.len() {
                    self.cur = self.cols.len().saturating_sub(1);
                }
            } else if self.cols[ci].focus >= self.cols[ci].ids.len() {
                self.cols[ci].focus = self.cols[ci].ids.len() - 1;
            }
        }
    }

    /// Перерисовать только ОБВОДКУ окна: рамку и титульную полосу.
    ///
    /// Смена фокуса меняет ровно их. Перерисовывать ради цвета рамки всё окно значит переписать
    /// сотни тысяч пикселей вместо нескольких тысяч — а фокус переезжает на каждый клик.
    fn damage_chrome(&mut self, i: usize) {
        // Рамка — это дополнение окна до его же прямоугольника, поджатого на толщину рамки:
        // четыре полосы, которые считает `Rect::subtract`. Прежде они выписывались руками.
        //
        // Прямоугольник берётся ПОКАЗАННЫЙ и в ЭКРАННЫХ координатах — тех же, в которых окно
        // рисуется. Прежний брал назначенный раскладкой и не вычитал прокрутку ленты, то есть
        // помечал место в координатах ЛЕНТЫ; на прокрученной ленте это чужое место. Заметить это
        // на экране не удалось ни в одном собранном сценарии (смену фокуса догоняют другие
        // пометки), поэтому здесь не исправление наблюдаемой поломки, а приведение к одной
        // системе координат.
        let f = self.wins[i].place(self.scroll_x);
        for strip in f.subtract(f.inset(BORDER)) {
            self.damage(strip);
        }
    }

    // ── курсор (тот же приём, что в `term`: он не часть кадра) ────────────────────────

    fn draw_cursor(&self) {
        let px_fill = self.pack(if self.buttons != 0 { tri(self.th.accent) } else { (255, 255, 255) });
        let px_edge = self.pack((0, 0, 0));
        for (row, line) in CURSOR.iter().enumerate() {
            for (col, ch) in line.bytes().enumerate() {
                if ch == b' ' {
                    continue;
                }
                let px = if ch == b'#' { px_edge } else { px_fill };
                self.put(self.cursor.x + col as i32, self.cursor.y + row as i32, px);
            }
        }
        fence();
    }

    /// Веха 150.1 — УРОНИТЬ то, что несут, в поверхность под курсором.
    ///
    /// Адресат — та же поверхность, которой достался бы клик: слой, если он там, иначе окно ленты
    /// под курсором. Другого ответа и быть не может — человек целится глазами, и «куда попал бы
    /// щелчок» это единственное, что совпадает с тем, что он видит.
    fn drop_here(&mut self, on_layer: Option<usize>) {
        // Ярлык уходит с экрана — пометить его место ДО того, как груз забыт: после `take`
        // прямоугольник указателя усохнет до курсора, и от ярлыка остался бы след.
        self.damage_pointer(self.cursor);
        let Some(p) = self.carry.take() else { return };
        let target = on_layer.or_else(|| {
            (!self.overview).then(|| {
                self.wins.iter().rposition(|w| {
                    w.visible && w.tiled() && w.hit_frame(self.cursor, self.scroll_x)
                })
            })?
        });
        // Мимо всего или в себя же — перетаскивание ОТМЕНЕНО. Отмена здесь исход, а не ошибка:
        // рука передумала на полпути, и сказать об этом человеку нечего — он и так видит, что
        // ярлык исчез. Отпустить там же, где нажал, — это как раз «передумал», а не передача
        // самому себе.
        let Some(i) = target.filter(|&i| self.wins[i].id != p.from) else { return };
        let sc = if self.wins[i].tiled() { self.scroll_x } else { 0 };
        let (lx, ly) = self.wins[i].client_point(self.cursor, sc);
        // Груз кладём ДО события: спросить «дай уроненное» окно может первым же, что сделает,
        // разобрав событие, и найти в этот момент пусто было бы враньём.
        self.dropped = Some((self.wins[i].id, p.kind, p.id));
        self.send(i, win::Event::Drop { x: lx, y: ly });
    }

    // ── СЕАНС: стол, переживающий перезагрузку (Веха 151) ──────────────────────────────
    //
    // Композитор знает про окно всё, кроме одного: КАК ЕГО ПОЗВАТЬ ОБРАТНО. Отсюда вся форма
    // вехи — он спрашивает («сохранись и назовись»), а отвечает программа, и отвечает она
    // командной строкой, а не образом памяти. Почему именно так — в протоколе (`win::OP_PERSIST`)
    // и в [[session]]; коротко: обязательный чекпойнт закрыл бы дверь тем, кого заморозить нечем.

    /// Разослать «сохранись» и завести сбор. `power` — гасить машину, когда допишем.
    fn begin_save(&mut self, power: bool) {
        if self.saving.is_some() {
            return; // сбор уже идёт: второй «сохранись» подряд — это тот же самый
        }
        // Спрашиваем окна ЛЕНТЫ. Слои (обои, панель) не спрашиваем: их поднимает конфиг
        // поколения, и класть их ещё и в сеанс значило бы завести вторую истину о том, из чего
        // состоит рабочий стол. Плитки не спрашиваем тем более — за ними никого нет.
        let ids: Vec<usize> = (0..self.wins.len())
            .filter(|&i| {
                let w = &self.wins[i];
                w.tiled() && w.launch.is_none() && !w.closing
            })
            .collect();
        for &i in &ids {
            self.wins[i].asked = true;
            self.send(i, win::Event::Save);
        }
        self.saving = Some(Saving {
            asked: ids.len(),
            got: 0,
            until: sys::monotonic_ns() + SAVE_WAIT_NS,
            power,
        });
        // Спрашивать некого — писать можно прямо сейчас (пустой стол тоже сеанс).
        self.tick_save(sys::monotonic_ns());
    }

    /// Все ответили или вышел срок — писать.
    fn tick_save(&mut self, now: u64) {
        let ready = self
            .saving
            .as_ref()
            .is_some_and(|s| s.got >= s.asked || now >= s.until);
        if ready {
            self.finish_save();
        }
    }

    /// Веха 151.1 — СЕАНС ПО ХОДУ ДЕЛА: сверить запись с тем, что на экране, и переписать при
    /// разнице. Зовётся раз за оборот, работает раз в [`SESSION_TICK_NS`].
    ///
    /// Здесь и живёт ответ на «а если погас свет»: раскладка стоит сотню байт, поэтому её можно
    /// писать по ходу, и стол вернётся таким, каким был секунды назад, а не таким, каким его
    /// сохранили руками. Дорогое — снимки и опрос клиентов — сюда не попадает: снимок это
    /// мегабайты, и обновлять его каждые пять секунд значило бы вернуть ту самую привычку писать
    /// на каждый чих, от которой систему отучала Веха 33.
    fn tick_session(&mut self, now: u64) {
        if self.saving.is_some() || now < self.session_at + SESSION_TICK_NS {
            return;
        }
        self.session_at = now;
        // Окно, которого ещё не спрашивали, спросим — но ровно один раз. Ответ приедет своим
        // чередом и попадёт в следующую сверку; молчун (демо без сохранения) больше не побеспокоен.
        let fresh: Vec<usize> = (0..self.wins.len())
            .filter(|&i| {
                let w = &self.wins[i];
                w.tiled() && w.launch.is_none() && !w.closing && !w.asked && w.run.is_none()
            })
            .collect();
        for i in fresh {
            self.wins[i].asked = true;
            self.send(i, win::Event::Save);
        }
        let text = self.session_text();
        if text == self.session_last {
            return;
        }
        self.write_session(&text);
    }

    /// Положить текст сеанса в store и переставить корень. `false` — не вышло.
    fn write_session(&mut self, text: &str) -> bool {
        let mut id = [0u8; 32];
        let ok = sys::obj_put(self.store, text.as_bytes(), &mut id) == 0
            && sys::obj_set_root(self.store, b"session/current", &id) == 0;
        if ok {
            self.session_last = String::from(text);
        }
        ok
    }

    /// Записать сеанс в store и, если просили, погасить машину.
    fn finish_save(&mut self) {
        let Some(s) = self.saving.take() else { return };
        // Полное сохранение — единственное место, где обновляются СНИМКИ: они мегабайты.
        for i in 0..self.wins.len() {
            if self.wins[i].tiled() && self.wins[i].launch.is_none() && self.wins[i].run.is_some() {
                if let Some(snap) = self.put_shot(&self.wins[i]) {
                    self.wins[i].snap = Some(snap);
                }
            }
        }
        let text = self.session_text();
        let ok = self.write_session(&text);
        sys::write_console(
            alloc::format!(
                "[wm] сеанс {}: ответили {} из {} спрошенных, {} байт\n",
                if ok { "записан" } else { "НЕ записан" },
                s.got,
                s.asked,
                text.len(),
            )
            .as_bytes(),
        );
        if s.power {
            // Синк делает само выключение (`SYS_POWEROFF` коммитит store перед снятием питания),
            // поэтому отдельного коммита здесь нет и быть не должно: два места, отвечающие за
            // одно, расходятся.
            match sys::cap_named("POWER") {
                Some(pc) => {
                    sys::power_off(pc);
                }
                None => sys::write_console(
                    "[wm] выключить нечем: нет права `power` в конфиге поколения\n".as_bytes(),
                ),
            }
        }
    }

    /// Лента стола `sp`: активная вынута в поля `Wm`, остальные лежат в `spaces`.
    fn strip_of(&self, sp: usize) -> &[Column] {
        if sp == self.space {
            &self.cols
        } else {
            self.spaces.get(sp).map_or(&[][..], |s| s.cols.as_slice())
        }
    }

    /// Сеанс текстом — той же грамматикой, что и конфиг поколения (`void_conf`).
    ///
    /// Текстом, а не двоичной раскладкой, ровно по той причине, по какой текстом сделан конфиг:
    /// сеанс надо уметь ПРОЧИТАТЬ снаружи, когда стол вернулся не таким, каким его оставили
    /// (`void-store-import … cat session/current`). Цена — сотня байт на окно.
    fn session_text(&self) -> String {
        let mut out = String::new();
        out.push_str(&alloc::format!("session space {}\n", self.space));
        let mut n = 0usize;
        for sp in 0..self.space_count() {
            for (ci, c) in self.strip_of(sp).iter().enumerate() {
                for (ri, &id) in c.ids.iter().enumerate() {
                    let Some(k) = self.win_at(id) else { continue };
                    let w = &self.wins[k];
                    // Не ответил — не записываем. Выдумать за программу, чем её звать, нечем.
                    let Some(run) = w.run.as_deref() else { continue };
                    let (shot, bw, bh) = match &w.snap {
                        Some((s, bw, bh)) => (s.as_str(), *bw, *bh),
                        None => ("-", 0, 0),
                    };
                    out.push_str(&alloc::format!(
                        "window {} space {} col {} row {} width {} focus {} bw {} bh {} shot {} run {}\n",
                        n,
                        sp,
                        ci,
                        ri,
                        c.width,
                        (self.focus == Some(id)) as u8,
                        bw,
                        bh,
                        shot,
                        run,
                    ));
                    n += 1;
                }
            }
        }
        out
    }

    /// Веха 151 — ПОДНЯТЬ ПРОШЛЫЙ СЕАНС: вернуть окна на места и позвать программы обратно.
    ///
    /// Возвращает имена уже позванных программ — чтобы конфиг поколения не запустил их вторым
    /// разом. Сеанс при этом конфиг НЕ отменяет: он говорит, как лежало, а что вообще должно
    /// быть на столе, по-прежнему говорит конфиг. Иначе добавленное в `apps` не появлялось бы
    /// никогда — сеанс молча стал бы главнее декларации.
    fn restore_session(&mut self, store: usize, me: usize) -> Vec<String> {
        let Some(text) = read_root_text(store, b"session/current") else {
            return Vec::new();
        };
        // Веха 151.1 — то, что прочитали, и есть «последнее записанное»: пока стол не изменился,
        // переписывать нечего, и первая же сверка это увидит.
        self.session_last = text.clone();
        let want_space = void_conf::num::<usize>(&text, "session", "space").unwrap_or(0);
        let mut names: Vec<String> = Vec::new();
        let mut last: Option<(usize, usize)> = None;
        let mut focus_id: Option<u32> = None;
        // Веха 169.1 — сколько байт уже отдано под снимки восстановленных окон (см. ниже).
        let mut spent = 0usize;
        for e in void_conf::of(&text, "window") {
            let Some(r) = parse_rec(&e) else { continue };
            let prog = r.run.split_whitespace().next().unwrap_or("");
            if prog.is_empty() {
                continue;
            }
            // Аргументы — той же раскладкой, что у любого запуска: строки через ноль.
            let mut blob: Vec<u8> = Vec::new();
            for a in r.run.split_whitespace().skip(1) {
                blob.extend_from_slice(a.as_bytes());
                blob.push(0);
            }
            let Some(pid) = sys::spawn_with_endpoint(store, prog.as_bytes(), &blob, me, b"WM\0")
            else {
                sys::write_console(
                    alloc::format!("[wm] сеанс: не запустился {}\n", r.run).as_bytes(),
                );
                continue;
            };
            names.push(String::from(prog));
            sys::write_console(
                alloc::format!("[wm] сеанс: зову «{}» (стол {}, колонка {})\n", r.run, r.space, r.col)
                    .as_bytes(),
            );
            // Снимок прошлого кадра. Нет его — плитка просто нарисует обычный бегунок запуска:
            // место всё равно занято, и стол не прыгнет, когда окно придёт.
            //
            // Веха 169.1 — и на снимки есть БЮДЖЕТ. Снимок окна это его кадр целиком: у окна в
            // пол-экрана — два мебибайта, и композитор честно читал их все. Двадцать восстановленных
            // окон — сорок мебибайт, то есть больше всей его кучи: он падал с
            // «memory allocation failed» прямо на подъёме сеанса, и человек получал систему без
            // оболочки вовсе. Нашлось это проверкой «открыть очень много терминалов»: сеанс
            // сохранился, а следующая загрузка не поднялась.
            //
            // Бюджет, а не отказ от снимков: первые окна возвращаются с картинкой (их и видно —
            // они в фокусе и рядом), остальные — обычной плиткой запуска. Место в раскладке они
            // занимают одинаково, а разница живёт ровно до первого кадра настоящего окна.
            let need = (r.bw * r.bh * 4) as usize;
            let own = r
                .shot
                .as_deref()
                .filter(|_| need > 0 && spent + need <= SNAP_BUDGET)
                .and_then(|s| sys::obj_resolve(store, s.as_bytes()))
                .and_then(|id| read_obj(store, &id))
                .filter(|v| v.len() >= need)
                .inspect(|_| spent += need);
            let id = self.next_id;
            self.next_id += 1;
            let now = sys::monotonic_ns();
            let has_shot = own.is_some();
            let win = Win {
                id,
                // Хозяин плитки — САМА позванная программа, а не мы. У плитки запуска хозяин
                // другой (сторож `run`), и разница по делу: там за окном стоит чужой ребёнок и
                // некому сказать «он умер», а здесь ребёнок наш. Умер, не показав окна, — плитка
                // уходит с ним (`reap`), и пустого места от программы, которой нет, не остаётся.
                owner: pid,
                x: 0,
                y: 0,
                w: if has_shot { r.bw } else { 480 },
                h: if has_shot { r.bh } else { 320 },
                title: String::from(prog),
                buf: 0,
                buf_len: 0,
                cap: sys::NO_CAP,
                slot: 0,
                span: 0,
                bw: if has_shot { r.bw } else { 0 },
                bh: if has_shot { r.bh } else { 0 },
                touched: Rect::ZERO,
                waiting: None,
                wait_until: None,
                watching: false,
                inbox: Vec::new(),
                shown: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                from: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                to: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                at: 0,
                dur: 0,
                fresh: true,
                closing: false,
                visible: true,
                layer: None,
                next: None,
                launch: Some(Launch {
                    pid,
                    name: String::from(prog),
                    since: now,
                    done: None,
                    drawn: None,
                    shot: has_shot,
                }),
                // Веха 151.1 — плитка помнит запись, из которой родилась: и команду, и снимок.
                // Иначе первое же переписывание раскладки (оно идёт по ходу дела, не спрашивая
                // клиентов) стёрло бы из сеанса окна, которые ещё не успели ответить, — то есть
                // загрузка сама бы и уничтожила то, что только что подняла.
                run: Some(r.run.clone()),
                snap: r.shot.clone().map(|s| (s, r.bw, r.bh)),
                asked: false,
                own,
            };
            self.wins.push(win);
            let key = (r.space, r.col);
            let fresh_col = last != Some(key);
            last = Some(key);
            self.place_restored(r.space, fresh_col, r.width, id);
            if r.focus {
                focus_id = Some(id);
            }
        }
        if names.is_empty() {
            return names;
        }
        self.tidy_spaces();
        if want_space != self.space && want_space < self.space_count() {
            self.switch_space(want_space);
        }
        if let Some((ci, wi)) = focus_id.and_then(|f| self.locate(f)) {
            self.cur = ci;
            self.cols[ci].focus = wi;
        }
        self.sync_focus();
        self.relayout();
        sys::write_console(
            alloc::format!("[wm] сеанс поднят: окон {}\n", names.len()).as_bytes(),
        );
        names
    }

    /// Положить восстановленную плитку в ленту нужного стола.
    ///
    /// Номер колонки из записи НЕ используется как индекс: записи идут по порядку, и «та же
    /// колонка, что у предыдущей записи» — это всё, что нужно, чтобы форма ленты повторилась.
    /// Индексом же можно было бы наделать пустых колонок, которых в раскладке не бывает.
    fn place_restored(&mut self, sp: usize, fresh_col: bool, width: usize, id: u32) {
        while self.spaces.len() <= sp {
            self.spaces.push(Space::default());
        }
        let active = sp == self.space;
        let strip = if active { &mut self.cols } else { &mut self.spaces[sp].cols };
        if fresh_col || strip.is_empty() {
            strip.push(Column { ids: vec![id], width: width.min(WIDTHS.len() - 1), focus: 0 });
        } else {
            let k = strip.len() - 1;
            strip[k].ids.push(id);
        }
    }

    /// Положить кадр окна в store: `(имя, ширина, высота)`. `None` — кадра нет.
    ///
    /// Кадр берётся ТОТ ЖЕ, что рисуется на экране (`px`), поэтому «сохранённое» и «увиденное»
    /// не могут разойтись. Дедуп при этом даром: не изменившееся окно второго объекта не создаёт.
    fn put_shot(&self, w: &Win) -> Option<(String, i32, i32)> {
        let px = w.px();
        let need = (w.bw * w.bh * 4) as usize;
        if need == 0 || px.len() < need {
            return None;
        }
        let mut id = [0u8; 32];
        (sys::obj_put(self.store, &px[..need], &mut id) == 0).then(|| (hex32(&id), w.bw, w.bh))
    }

    // ── ввод ───────────────────────────────────────────────────────────────────────────

    fn on_mouse(&mut self, e: &sys::MouseEvent) {
        let old = self.cursor;
        self.cursor.x = (self.cursor.x + e.dx as i32).clamp(0, self.info.width as i32 - 1);
        self.cursor.y = (self.cursor.y + e.dy as i32).clamp(0, self.info.height as i32 - 1);
        let was = self.buttons;
        self.buttons = e.buttons;

        // В обзоре клик выбирает окно и ВЫХОДИТ к нему — ради этого обзор и открывают.
        // Попадание считается по тому же списку, по которому обзор нарисован: отдельный расчёт
        // «где что» означал бы, что клик приходит не в то окно, которое человек видит.
        // Пока ВЫХОД из обзора доигрывает, ввод обзору уже не принадлежит: на экране идёт
        // наезд камеры, а список попаданий посчитан для неподвижной картинки — клик пришёл бы
        // не в то окно, которое человек видит. `ov_to != 0` и значит «мы всё ещё в обзоре».
        if was == 0 && e.buttons != 0 && self.overview && self.ov_to != 0 {
            if let Some(it) = self.ov.iter().find(|it| it.r.contains(self.cursor)) {
                let (id, sp) = (it.id, it.space);
                if sp != self.space {
                    self.action_inner(&alloc::format!("workspace-{}", sp + 1), 0, 0);
                }
                if let Some((ci, wi)) = self.locate(id) {
                    self.cur = ci;
                    self.cols[ci].focus = wi;
                }
                self.sync_focus();
                self.leave_overview();
            } else if let Some(&(_, sp)) = self
                .ov_bands
                .iter()
                .find(|(band, _)| band.rect().contains(self.cursor.x, self.cursor.y))
            {
                // Веха 142 — клик мимо окон, но по ПОЛОСЕ стола: перейти на этот стол и выйти.
                // Пустой стол иначе выбрать мышью было нечем — на нём нет ни одного окна, а
                // именно туда чаще всего и уходят из обзора, чтобы начать с чистого места.
                if sp != self.space {
                    self.switch_space(sp);
                    self.sync_focus();
                }
                self.leave_overview();
            }
            return;
        }

        // ── Веха 142: мышь с Super принадлежит КОМПОЗИТОРУ ──────────────────────────────────
        //
        // Super — тот же признак «это команда системе, а не программе», что и у клавиш. Поэтому
        // ни нажатие, ни движение с зажатым Super окну не отдаются: иначе редактор получал бы
        // выделение текста ровно там, где человек двигал окно.
        //
        // ЛКМ переставляет окно, ПКМ меняет ширину колонки. Обе тянут за собой ОБЫЧНЫЕ действия
        // раскладки (`move-column-*`, `width-*`), а не свою арифметику: в тайлинге место окна
        // задаётся лентой, и «положить окно в пиксель» тут значения не имеет. Побочно это значит,
        // что рука и клавиши делают ровно одно и то же — разойтись им нечем.
        // Веха 142 — БОКОВЫЕ кнопки (четвёртая и пятая). Ими же мышь сообщает наклон колеса
        // влево-вправо: у PS/2 отдельной оси для наклона нет, и тилт-колёса шлют его именно
        // кнопками. С Super это переход по колонкам — то же, что `Super+H`/`Super+L`.
        //
        // Разбирается ДО перетаскивания: «нажата кнопка» верно и для них, и не раздели мы эти
        // случаи, наклон колеса начинал бы таскать окно.
        let pressed = e.buttons & !was;
        if self.super_held && pressed & 0x18 != 0 {
            let name = if pressed & 0x08 != 0 { "focus-column-left" } else { "focus-column-right" };
            self.action_inner(name, 0, 0);
            self.damage_pointer(old);
            self.damage_pointer(self.cursor);
            return;
        }
        // Тащат ТОЛЬКО левой и правой: остальные кнопки к месту окна отношения не имеют.
        if self.super_held && !self.overview && was == 0 && e.buttons & 0x03 != 0 {
            if let Some(i) = self.wins.iter().position(|w| {
                w.visible && w.tiled() && w.hit_frame(self.cursor, self.scroll_x)
            }) {
                let id = self.wins[i].id;
                if let Some((ci, wi)) = self.locate(id) {
                    self.cur = ci;
                    self.cols[ci].focus = wi;
                    self.sync_focus();
                }
            }
            self.drag = Some(Drag { resize: e.buttons & 2 != 0, ax: 0, ay: 0 });
            self.damage_pointer(old);
            self.damage_pointer(self.cursor);
            return;
        }
        if let Some(mut d) = self.drag.take() {
            if e.buttons != 0 {
                d.ax += e.dx as i32;
                d.ay += e.dy as i32;
                // Шаг — доля ЭКРАННОГО размера, а не число пикселей: на большом экране окна
                // крупнее, и постоянный порог означал бы «на 4K окна прыгают от дрожи руки».
                let (sx, sy) = self.drag_steps(d.resize);
                while d.ax.abs() >= sx {
                    let right = d.ax > 0;
                    d.ax -= if right { sx } else { -sx };
                    self.action_inner(
                        match (d.resize, right) {
                            (true, true) => "width-plus",
                            (true, false) => "width-minus",
                            (false, true) => "move-column-right",
                            (false, false) => "move-column-left",
                        },
                        0,
                        0,
                    );
                }
                // По вертикали переставляем окно ВНУТРИ колонки. Ширину вертикалью не меняем:
                // высоту окна в ленте задаёт число соседей, отдельной высоты у него нет.
                while !d.resize && d.ay.abs() >= sy {
                    let down = d.ay > 0;
                    d.ay -= if down { sy } else { -sy };
                    self.action_inner(if down { "move-window-down" } else { "move-window-up" }, 0, 0);
                }
                self.drag = Some(d);
            }
            self.damage_pointer(old);
            self.damage_pointer(self.cursor);
            return;
        }

        // Веха 140 — есть ли под курсором ПОВЕРХНОСТЬ СЛОЯ (бар). Считается один раз и решает
        // всё дальнейшее: мышь достаётся ей, а фокус её не касается вовсе.
        //
        // Это и есть ответ на вопрос, оставленный Вехой 139: как курсор над панелью не уводит
        // фокус у окна под ней. Правило — «фокус ходит за указателем только по окнам ЛЕНТЫ»;
        // у слоя клавиатурного фокуса нет вовсе, поэтому уводить его нечем. Обратное («панель
        // берёт фокус, пока курсор над ней») означало бы, что набор текста прерывается всякий
        // раз, когда человек мышью тянется к часам, — а панель для того и висит с краю, чтобы
        // на неё смотрели, не бросая работу.
        //
        // Клавиши слою не отдаются вовсе (в `key_event` он не участвует). Это осознанное «нет»,
        // а не недоделка: клавиатурный слой (`keyboard_interactivity` в wlr-layer-shell) нужен
        // строке запуска и экрану блокировки, и у него свои вопросы — кто отдаёт фокус обратно
        // и что делает Escape. Появится такой клиент — будет и поле в [`win::Layer`].
        //
        // В ОБЗОРЕ слоёв под курсором не бывает: там композитор показывает столы целиком, и
        // панель на этой картинке — часть фона, а не собеседник.
        let on_layer = if self.overview {
            None
        } else {
            self.layer_at(self.cursor)
        };

        // Веха 150.1 — кнопку ОТПУСТИЛИ, а в руке груз: это и есть «уронил».
        //
        // Отсюда же следует, почему перетаскивание кончается именно здесь, а не по слову
        // источника: конец у него — движение руки, и знает о нём только тот, у кого рука.
        if self.carry.is_some() && was != 0 && e.buttons == 0 {
            self.drop_here(on_layer);
        }

        // Нажатие: выбрать окно под курсором. Перетаскивания в тайлинге нет — место окна
        // задаёт раскладка, а не рука; плавающий режим остаётся исключением на будущее
        // ([[wm-keys]]), и тащить окно понадобится ровно там.
        if was == 0 && e.buttons != 0 && on_layer.is_none() {
            if let Some(i) = self.wins.iter().position(|w| w.visible && w.tiled() && w.hit_frame(self.cursor, self.scroll_x))
            {
                let id = self.wins[i].id;
                if let Some((ci, wi)) = self.locate(id) {
                    self.cur = ci;
                    self.cols[ci].focus = wi;
                    self.sync_focus();
                    self.relayout();
                }
            }
        }

        // Фокус за указателем (Веха 121.1, просьба владельца): навёл — работаешь здесь.
        // Только на ДВИЖЕНИИ: иначе всплывшее под неподвижным курсором окно перехватывало бы
        // фокус у того, с кем человек работает.
        // В обзоре наведение тоже переносит фокус — и камера едет следом, ставя выбранное в
        // центр (просьба владельца, как в niri). Считаем по тому же списку, по которому обзор
        // нарисован, и перестраиваем его только при СМЕНЕ окна: иначе камера дёргалась бы на
        // каждое движение мыши.
        if (e.dx != 0 || e.dy != 0) && self.buttons == 0 && self.overview && self.ov_to != 0 {
            let hit = self.ov.iter().find(|it| it.r.contains(self.cursor));
            if let Some((id, sp)) = hit.map(|it| (it.id, it.space)) {
                // Веха 147.1 — окно из списка обзора могло исчезнуть: досжавшееся окно уходит из
                // `wins` в `animate`, мимо раскладки, а список обзора перестраивает раскладка.
                // Переключиться на стол призрака и не найти там окна значит развести стол с
                // фокусом — то самое «камера внизу, фокус сверху».
                let alive = self.wins.iter().any(|w| w.id == id && !w.closing);
                if !alive {
                    self.build_overview(false);
                } else if self.focus != Some(id) {
                    if sp != self.space {
                        self.switch_space(sp);
                    }
                    if let Some((ci, wi)) = self.locate(id) {
                        self.cur = ci;
                        self.cols[ci].focus = wi;
                    }
                    self.sync_focus();
                    self.build_overview(false);
                    // …и подвинуть камеру РОВНО настолько, чтобы выбранное влезло целиком
                    // (идея владельца, Веха 124). Это безопасно там, где «поставить в центр»
                    // ломалось: минимальная подвижка имеет неподвижную точку — как только окно
                    // влезло, следующее наведение на него не двигает ничего. Центрирование
                    // такой точки не имеет, поэтому и качалось.
                    self.ensure_visible(id);
                }
            }
        }

        if (e.dx != 0 || e.dy != 0) && self.buttons == 0 && !self.overview && on_layer.is_none() {
            if let Some(i) = self.wins.iter().position(|w| w.visible && w.tiled() && w.hit_frame(self.cursor, self.scroll_x))
            {
                let id = self.wins[i].id;
                if self.focus != Some(id) {
                    if let Some((ci, wi)) = self.locate(id) {
                        self.cur = ci;
                        self.cols[ci].focus = wi;
                        self.sync_focus();
                        // …и ПОДВИНУТЬ ЛЕНТУ, чтобы фокусная колонка влезла целиком.
                        //
                        // Здесь этого не было, и разница вылезала ровно там, где её труднее
                        // всего заметить: клик по наполовину видимому окну камеру двигал
                        // (ниже по этой же функции стоит `relayout`), а НАВЕДЕНИЕ — нет.
                        // А фокус у нас ходит за указателем (Веха 121.1), то есть в жизни
                        // работает как раз наведение: человек ведёт мышь к торчащему из-за
                        // края окну, оно получает фокус — и остаётся торчать.
                        //
                        // Гоняться за указателем это не заставляет: подвижка минимальна
                        // (`relayout` трогает прокрутку, только если колонка не влезла), а
                        // колонка, которую подвинули под курсор, становится видна ЦЕЛИКОМ —
                        // значит следующее движение внутри неё не двигает ничего. Тот же
                        // довод, что у камеры обзора в Вехе 124: у минимальной подвижки есть
                        // неподвижная точка, у центрирования её нет.
                        self.relayout();
                    }
                }
            }
        }

        // Курсор: пометить И СТАРОЕ место, И НОВОЕ (Веха 121.2).
        //
        // Здесь была настоящая ошибка, и внесла её Веха 120.3. До неё `repaint` дорисовывал
        // курсор в конце БЕЗУСЛОВНО, поэтому хватало пометить старое место. Когда курсор
        // переехал в построчную сборку кадра, он стал рисоваться только внутри перерисованных
        // областей — а новое место в них не попадало. При медленном движении области
        // пересекались и всё выглядело целым; при быстром курсор терял куски, а на большом
        // скачке пропадал совсем. Ровно это владелец и увидел.
        self.damage_pointer(old);
        self.damage_pointer(self.cursor);

        // Колесо: в обзоре — просто крутить столы, вне обзора — с Super (просьба владельца).
        // Без модификатора вне обзора колесо принадлежит программе: прокрутка страницы важнее.
        // Веха 148 — колесо БЕЗ Super и вне обзора принадлежит программе. Так было задумано с
        // Вехи 123.1, но доставки клиенту не существовало, и колесо в окне просто пропадало.
        if e.wheel != 0 && !self.overview && !self.super_held {
            if let Some(i) = self.layer_at(self.cursor).or_else(|| {
                self.wins.iter().rposition(|w| {
                    w.visible && w.tiled() && w.hit_frame(self.cursor, self.scroll_x)
                })
            }) {
                let sc = if self.wins[i].tiled() { self.scroll_x } else { 0 };
                let (lx, ly) = self.wins[i].client_point(self.cursor, sc);
                self.send(i, win::Event::Wheel { x: lx, y: ly, delta: e.wheel as i8 });
            }
        }
        if e.wheel != 0 && (self.overview || self.super_held) {
            let step = if e.wheel > 0 { -1i32 } else { 1i32 };
            let mut to = self.space as i32 + step;
            to = to.clamp(0, self.space_count() as i32 - 1);
            if to as usize != self.space {
                self.switch_space(to as usize);
                self.sync_focus();
                if self.overview {
                    self.build_overview(true);
                } else {
                    self.relayout();
                }
            }
            return;
        }

        // Событие поверхности под курсором: слою, если он там, иначе окну ленты. Один и тот же
        // код на оба случая — разница только в том, ЧТО нашлось под курсором (Веха 140).
        //
        // Веха 149.1 — в ОБЗОРЕ окно ленты под курсором не ищем вовсе. Там окна нарисованы не по
        // `shown`, а по списку обзора (уменьшенные, со своей камерой), и попадание по `shown`
        // назвало бы и не то окно, и не ту точку в нём. В обзоре указатель принадлежит обзору:
        // наведение переносит фокус, клик выбирает окно — это выше по этой же функции.
        let hit = on_layer.or_else(|| {
            (!self.overview).then(|| {
                self.wins.iter().rposition(|w| {
                    w.visible && w.tiled() && w.hit_frame(self.cursor, self.scroll_x)
                })
            })?
        });
        // Веха 169 — ЗАХВАТ (см. [`Wm::grab`]): нажали — запомнили, на ком. Снимается он НИЖЕ,
        // уже после отправки события: само отпускание обязано доехать до того, на ком нажимали,
        // иначе протяжка так и останется незакрытой (и терминал будет выделять текст мышью,
        // которую никто не держит, — на этом я и попался, проверяя эту самую веху).
        if was == 0 && e.buttons != 0 {
            self.grab = hit.map(|i| self.wins[i].id);
        }
        let held = self.grab.and_then(|id| self.wins.iter().position(|w| w.id == id));
        let under = held.or(hit);
        // Веха 144 — сказать прежней поверхности, что курсор УШЁЛ. Событие то же самое
        // (`EV_MOTION`), но с координатами вне поверхности: `0xffff` не бывает настоящей точкой,
        // а заводить отдельное событие ради одного признака значило бы раздувать протокол.
        //
        // Понадобилось панели: у её виджетов появилась подсветка под курсором, а сообщения
        // «мыши больше нет над тобой» в протоколе не было вовсе — подсветка залипала на том
        // месте, где курсор ушёл с панели в окно.
        let now_id = under.map(|i| self.wins[i].id);
        if self.hover != now_id {
            if let Some(k) = self.hover.and_then(|h| self.wins.iter().position(|w| w.id == h)) {
                self.send(k, win::Event::GONE);
            }
            self.hover = now_id;
        }
        if let Some(i) = under {
            let sc = if self.wins[i].tiled() { self.scroll_x } else { 0 };
            let (lx, ly) = self.wins[i].client_point(self.cursor, sc);
            if was != e.buttons {
                let ev = win::Event::Button {
                    x: lx,
                    y: ly,
                    buttons: e.buttons,
                    down: e.buttons != 0,
                    // Веха 167 — состояние модификаторов НА МОМЕНТ щелчка. Композитор его и так
                    // видит (клавиши-модификаторы приходят ему событиями, `mods` в каждом), а
                    // клиенту взять его больше неоткуда: без этого байта `Ctrl+щелчок` от
                    // простого не отличить.
                    mods: self.kmods,
                };
                self.send(i, ev);
            } else {
                self.send(i, win::Event::Motion { x: lx, y: ly });
            }
        }
        // Кнопок больше не держат — захвата тоже нет.
        if e.buttons == 0 {
            self.grab = None;
        }
    }

    /// Клавиша: сперва ищем АККОРД в раскладке, и только если его нет — отдаём символ окну.
    ///
    /// Порядок принципиален: `Super+Q` не должен доехать до программы буквой `q`. Отпускания
    /// клавиш окну не отдаём вовсе — программам нужен текст, а не состояние клавиатуры.
    fn key_event(&mut self, e: &sys::KeyEvent, binds: &[Bind], store: usize, me: usize) {
        // Веха 167.2 — СОСТОЯНИЕ МОДИФИКАТОРОВ обновляем ПЕРВЫМ делом, до всякого отсева.
        //
        // Рядом ровно та же защита стоит у Super («иначе залипнет нажатым навсегда»), и
        // наступил я на неё же: `self.kmods` присваивался ниже, ПОСЛЕ `if !e.down { return }`.
        // Нажатие `Ctrl` доезжало, отпускание — нет, и щелчки мышью до конца сеанса считались
        // выделяющими. Симптом ровно такой, каким его назвал владелец: «клавишу отпустил, а она
        // будто нажата».
        self.kmods = e.mods;
        // Super держат или отпустили — это нужно колесу, и знать об этом надо ДО отсева
        // отпусканий: иначе Super «залипнет» нажатым навсегда.
        if e.sym == SYM_SUPER {
            self.super_held = e.down;
        }
        if !e.down {
            return;
        }
        if let Some(b) = binds.iter().find(|b| b.sym == e.sym && b.mods == e.mods) {
            // `Escape` и `Return` привязаны БЕЗ модификатора — они закрывают обзор. Вне обзора
            // забирать их у программы нельзя: редактору Escape нужен ему, а не нам. Поэтому
            // действие, осмысленное только в обзоре, вне его не срабатывает и клавиша уходит
            // дальше как обычная.
            if !(b.action == "close-overview" && !self.overview) {
                self.action(&b.action.clone(), store, me);
                return;
            }
        }
        // Аккорд с Super, которому не нашлось действия, программе не отдаём: иначе промах по
        // раскладке печатал бы букву посреди текста.
        if e.mods & win::modk::SUPER != 0 {
            return;
        }
        // Веха 146 — поверхность слоя, попросившая клавиатуру (`win::LAYER_KBD`), забирает
        // клавиши у окна в фокусе. Ищем ПОСЛЕДНЮЮ такую: если их вдруг две, набирает верхняя —
        // тот же порядок, в котором они лежат в стопке и рисуются.
        //
        // Аккорды разобраны ВЫШЕ и работают по-прежнему. Это осознанный выбор, а не упущение:
        // строка запуска не должна отнимать у человека управление системой, пока она открыта.
        // Экрану блокировки будет нужно обратное — записано в [[known-gaps]].
        let ev = win::Event::Key { sym: e.sym, mods: e.mods, ch: e.ch, down: e.down };
        if let Some(i) = self.wins.iter().rposition(|w| w.grabs_kbd() && w.visible) {
            self.send(i, ev);
            return;
        }
        // Веха 127: клавиша уходит в окно ЦЕЛИКОМ — код, модификаторы, символ. Прежде здесь
        // стояло `|| e.ascii == 0`, то есть всё, что не печатает символ, молча выбрасывалось:
        // стрелки, Home/End, PageUp. Именно поэтому в окне не работали ни они, ни собственные
        // клавиши терминала.
        let Some(id) = self.focus else { return };
        let Some(i) = self.wins.iter().position(|w| w.id == id) else { return };
        self.send(i, ev);
    }

    /// Выполнить действие раскладки.
    ///
    /// В обзоре действия те же: он показывает ту же ленту, только уменьшенной. Отдельная схема
    /// «клавиши обзора» означала бы вторую модель управления ради одного экрана.
    fn action(&mut self, name: &str, store: usize, me: usize) {
        let was_overview = self.overview;
        self.action_inner(name, store, me);
        // Обзор перестраиваем ПОСЛЕ действия: фокус мог переехать на другой стол, а картинка
        // обязана показывать то, что есть сейчас.
        if self.overview && was_overview && self.ov_to != 0 && name != "toggle-overview" {
            self.build_overview(true);
        }
    }

    fn action_inner(&mut self, name: &str, store: usize, me: usize) {
        match name {
            "spawn-term" => {
                if sys::spawn_with_endpoint(store, b"term", &[], me, b"WM\0").is_none() {
                    sys::write_console("[wm] терминал не запустился\n".as_bytes());
                }
            }
            // Веха 146 — строка запуска: ПЕРЕКЛЮЧАТЕЛЬ, а не «запустить ещё одну».
            //
            // Второй `Super+D` при открытой строке породил бы вторую такую же поверхность поверх
            // первой — с виду ничего не изменилось бы, а клавиши стали бы уходить в невидимую
            // копию. Поэтому: открыта (есть слой, забравший клавиатуру) — просим её закрыться,
            // нет — запускаем. Закрываемся ПРОСЬБОЙ (`EV_CLOSE`), а не убийством: программа
            // наш ребёнок, но убитая молча она не отличалась бы от упавшей.
            "launcher-toggle" => {
                if let Some(i) = self.wins.iter().rposition(|w| w.grabs_kbd() && w.visible) {
                    self.send(i, win::Event::Close);
                } else if sys::spawn_with_endpoint(store, b"launcher", &[], me, b"WM\0").is_none() {
                    sys::write_console("[wm] строка запуска не запустилась\n".as_bytes());
                }
            }
            // Веха 151 — записать СЕАНС, не выключаясь. Нужно и человеку («сохрани, как лежит»),
            // и проверке: сохранение, которое можно увидеть только выключив машину, нечем
            // отладить.
            "save-session" => self.begin_save(false),
            // …и выключение. Живёт ЗДЕСЬ, а не в шелле, ровно потому, что сеанс — это композитор:
            // спросить окна и записать стол может только тот, кто их держит. `poweroff` в шелле
            // остаётся и по-прежнему гасит машину МИМО сеанса — это записано в [[known-gaps]].
            "poweroff" => self.begin_save(true),
            "close-window" => {
                // Закрываем ОКНО, а не процесс: клиенту говорят «закройся», и он решает сам.
                // Убить его силой мы могли бы (он наш ребёнок), но тогда несохранённое пропадёт
                // молча — а это ровно то, чего порядочная система не делает.
                if let Some(id) = self.focus {
                    if let Some(i) = self.wins.iter().position(|w| w.id == id) {
                        // Веха 147 — у ПЛИТКИ запуска клиента нет: просить её закрыться некого,
                        // и ждать нечего. Убираем сразу. Плитка при этом ещё ждущая — значит
                        // человек снимает с экрана запуск, который ему больше не интересен;
                        // сам процесс мы не трогаем (его не мы запускали).
                        if self.wins[i].launch.is_some() {
                            self.begin_close(id);
                            self.sync_focus();
                            self.relayout();
                        } else {
                            self.send(i, win::Event::Close);
                        }
                    }
                }
            }
            // ── навигация по ленте (Веха 121) ──
            "focus-column-left" | "focus-column-right" => {
                if self.cols.is_empty() {
                    return;
                }
                let last = self.cols.len() - 1;
                self.cur = if name.ends_with("right") {
                    (self.cur + 1).min(last)
                } else {
                    self.cur.saturating_sub(1)
                };
                self.sync_focus();
                self.relayout();
            }
            "focus-window-up" | "focus-window-down" => {
                let Some(c) = self.cols.get_mut(self.cur) else { return };
                if c.ids.is_empty() {
                    return;
                }
                let last = c.ids.len() - 1;
                c.focus = if name.ends_with("down") {
                    (c.focus + 1).min(last)
                } else {
                    c.focus.saturating_sub(1)
                };
                self.sync_focus();
            }
            // Переносить колонку целиком — это МЕНЯТЬ ЕЁ МЕСТО В ЛЕНТЕ, а не двигать пиксели.
            "move-column-left" | "move-column-right" => {
                if self.cols.len() < 2 {
                    return;
                }
                let to = if name.ends_with("right") {
                    (self.cur + 1).min(self.cols.len() - 1)
                } else {
                    self.cur.saturating_sub(1)
                };
                if to != self.cur {
                    self.cols.swap(self.cur, to);
                    self.cur = to;
                }
                self.relayout();
            }
            "move-window-up" | "move-window-down" => {
                let Some(c) = self.cols.get_mut(self.cur) else { return };
                if c.ids.len() < 2 {
                    return;
                }
                let to = if name.ends_with("down") {
                    (c.focus + 1).min(c.ids.len() - 1)
                } else {
                    c.focus.saturating_sub(1)
                };
                if to != c.focus {
                    c.ids.swap(c.focus, to);
                    c.focus = to;
                }
                self.relayout();
            }
            // Окно из своей колонки — в соседнюю (или в новую с краю ленты).
            "move-to-column-left" | "move-to-column-right" => {
                let Some(id) = self.focused_id() else { return };
                let right = name.ends_with("right");
                let ci = self.cur;
                self.unlink(id);
                let to = if right { ci + 1 } else { ci.saturating_sub(1) };
                if to >= self.cols.len() || (right && to == ci) {
                    self.cols.insert(to.min(self.cols.len()), Column { ids: vec![id], width: 1, focus: 0 });
                    self.cur = to.min(self.cols.len() - 1);
                } else {
                    self.cols[to].ids.push(id);
                    self.cols[to].focus = self.cols[to].ids.len() - 1;
                    self.cur = to;
                }
                self.sync_focus();
                self.relayout();
            }
            "width-next" => {
                if let Some(c) = self.cols.get_mut(self.cur) {
                    c.width = (c.width + 1) % WIDTHS.len();
                }
                self.relayout();
            }
            "width-plus" | "width-minus" => {
                if let Some(c) = self.cols.get_mut(self.cur) {
                    c.width = if name.ends_with("plus") {
                        (c.width + 1).min(WIDTHS.len() - 1)
                    } else {
                        c.width.saturating_sub(1)
                    };
                }
                self.relayout();
            }
            "maximize-column" => {
                if let Some(c) = self.cols.get_mut(self.cur) {
                    // Развернуть — это переключатель: второе нажатие возвращает половину экрана.
                    c.width = if c.width == WIDTHS.len() - 1 { 1 } else { WIDTHS.len() - 1 };
                }
                self.relayout();
            }
            // Синонимы движения по ленте. По КРУГУ не ходим (Веха 121.1, просьба владельца):
            // дошёл до края — там и остался. Заворот полезен там, где окон не видно, а у нас
            // лента перед глазами, и прыжок с конца в начало читается как промах, а не как
            // помощь.
            "focus-next" => self.action("focus-column-right", store, me),
            "focus-prev" => self.action("focus-column-left", store, me),
            // ── обзор (Веха 123) ──
            "toggle-overview" => {
                if !self.overview {
                    self.overview = true;
                    self.build_overview(true);
                    self.ov_start(1024);
                } else if self.ov_to != 0 {
                    // Выходя, показываем стол ТОГО окна, что выбрано: обзор для того и нужен —
                    // ткнуть в окно и оказаться при нём, а не вернуться откуда пришёл.
                    self.leave_overview();
                }
            }
            // ── рабочие столы (Веха 122) ──
            //
            // Переключение — это ОБМЕН ЛЕНТАМИ: активная уходит в хранилище, оттуда приходит
            // другая. Вся раскладка продолжает работать с одной лентой и про столы не знает.
            _ if name.starts_with("workspace-") => {
                let Some(n) = digit(name) else { return };
                // Веха 137 — столов может быть меньше девяти, и цифра сверх их числа не ошибка,
                // а просьба «в самый дальний». Последний стол всегда пустой, так что `Super+9`
                // на системе с двумя столами означает «на чистый», а не «никуда».
                self.goto_space(n);
            }
            _ if name.starts_with("move-to-workspace-") => {
                let Some(n) = digit(name) else { return };
                let Some(id) = self.focused_id() else { return };
                let n = n.min(self.space_count().saturating_sub(1));
                if n == self.space {
                    return;
                }
                self.unlink(id);
                // На чужом столе окно всегда становится НОВОЙ колонкой: класть его в чью-то
                // чужую колонку значило бы менять раскладку стола, которого человек не видит.
                self.spaces[n].cols.push(Column { ids: vec![id], width: 1, focus: 0 });
                self.spaces[n].cur = self.spaces[n].cols.len() - 1;
                // Окно уехало на последний (пустой) стол — значит пустого в конце больше нет и
                // его надо завести; а стол, с которого окно ушло последним, исчезнет.
                self.tidy_spaces();
                self.sync_focus();
                self.relayout();
            }
            // Escape/Enter закрывают обзор — и НИЧЕГО не делают вне его: перехватывать эти
            // клавиши у программ было бы воровством (в редакторе Escape нужен ему, не нам).
            "close-overview" => {
                if self.overview && self.ov_to != 0 {
                    self.leave_overview();
                }
            }
            // Веха 143 — РАСКЛАДКА. Действие композитора, а не аккорд в драйвере: какой клавишей
            // её переключать — вкус владельца (у него это `Super+Z`), а вкусы живут в конфиге.
            // Таблицы при этом остаются в ядре: вторая копия раскладки в userspace разошлась бы
            // с той, по которой считается ввод в текстовом режиме.
            "switch-layout" => {
                if sys::keymap_next().is_none() {
                    sys::write_console("[wm] раскладку не переключить: экран не наш\n".as_bytes());
                }
            }
            "quit" => {
                sys::write_console("[wm] выход по запросу\n".as_bytes());
                sys::exit(0);
            }
            other => {
                sys::write_console(alloc::format!("[wm] нет такого действия: {}\n", other).as_bytes());
            }
        }
    }

    /// Убрать окна процессов, которых больше нет.
    fn reap(&mut self) {
        let mut foreign = false;
        for i in 0..self.wins.len() {
            // Закрывающееся окно уже осиротело — спрашивать про его хозяина незачем.
            if self.wins[i].closing {
                continue;
            }
            match sys::wait(self.wins[i].owner, true) {
                sys::Wait::Exited(_) => {
                    let id = self.wins[i].id;
                    self.begin_close(id);
                    self.sync_focus();
                    self.relayout();
                    return; // список изменился — доберём на следующем обороте
                }
                // «Не мой ребёнок» — про него `SYS_WAIT` не знает ничего, и молчание тут не
                // значит «жив». Такие окна проверяются обзором, ниже.
                sys::Wait::NoChild => foreign = true,
                sys::Wait::Running => {}
            }
        }
        if foreign {
            self.reap_foreign();
        }
    }

    /// Веха 168 — ИМЯ ПРОЦЕССА по его номеру, спрошенное у ядра.
    ///
    /// Тот же приём, которым проверяется проситель права ([`Wm::grant_for`]): имя процесса ядро
    /// берёт из имени программы в store, и подделать его нельзя, не подменив саму программу.
    /// Спросить самого отправителя было бы не проверкой, а анкетой.
    ///
    /// Права обзора нет — уведомление всё равно покажем, просто без имени: сказать человеку то,
    /// что ему говорят, важнее, чем знать, кто это сказал.
    fn proc_name(&self, pid: usize) -> String {
        if self.sysview == sys::NO_CAP {
            return String::new();
        }
        let rec = sys::PROC_REC;
        let mut buf = vec![0u8; rec * 64];
        let Some(total) = sys::proc_list(self.sysview, &mut buf) else { return String::new() };
        for k in 0..total.min(buf.len() / rec) {
            let r = &buf[k * rec..k * rec + rec];
            if u16::from_le_bytes([r[0], r[1]]) as usize == pid {
                let nlen = (r[7] as usize).min(24);
                return String::from_utf8_lossy(&r[40..40 + nlen]).into_owned();
            }
        }
        String::new()
    }

    /// Веха 168 — где сейчас ВСПЛЫВАШКА. Правый верх, под полосой панели: там же, где её ждут
    /// системы, к которым владелец привык, и там же, где стоит колокольчик в панели — глаз
    /// переходит от одного к другому, не ища.
    fn toast_at(&self) -> Option<At<Screen>> {
        let t = self.toast?;
        let n = self.notes.iter().find(|n| n.id == t.id)?;
        let gw = sys::glyph::W as i32;
        let gh = sys::glyph::H as i32;
        let chars = n.title.chars().count().max(n.text.chars().count()).max(8) as i32;
        let w = chars * gw + 2 * TOAST_PAD;
        let h = 2 * gh + 2 * TOAST_PAD;
        let sc = self.screen().rect();
        // Под РАБОЧЕЙ ЗОНОЙ, а не под краем экрана: панель уже сказала, сколько места заняла,
        // и всплывашка, залезающая под неё, была бы наполовину невидимой.
        Some(At::new((sc.w - w - TOAST_PAD).max(0), self.work.rect().y + TOAST_PAD, w, h))
    }

    /// Веха 168.3 — где на экране лежит то, что клиент ДЕЙСТВИТЕЛЬНО нарисовал в свой буфер
    /// (`Win::touched`), если поверхность стоит на месте `place`.
    ///
    /// Нужно, чтобы убирать поверхность по площади нарисованного. У слоя буфер и место совпадают
    /// (место он называет сам), поэтому перевод — просто сдвиг; на всякий случай режем по месту.
    /// Не рисовал ничего — и стирать нечего.
    fn touched_on(&self, i: usize, place: At<Screen>) -> At<Screen> {
        let t = self.wins[i].touched;
        if t.is_empty() {
            return At::new(0, 0, 0, 0);
        }
        let p = place.rect();
        At::of(Rect::new(p.x + t.x, p.y + t.y, t.w, t.h).intersect(p))
    }

    /// Веха 169.1 — положить уведомление В СПИСОК и показать всплывашку.
    ///
    /// Отдельным методом, потому что говорить человеку что-то приходится и САМОМУ композитору —
    /// не только чужим программам через [`win::OP_NOTIFY`]. Первый такой случай: окну не хватило
    /// места в адресном пространстве ([`Wm::map_client_buf`]). Раньше об этом знала только
    /// консоль ядра, то есть в графическом режиме — никто: окно просто оказывалось цвета рамки,
    /// и отличить это от сломанной программы было нечем.
    ///
    /// Имя отправителя приходит строкой: у своих сообщений его не у кого спросить, а «композитор»
    /// человеку понятнее номера процесса.
    fn post_note(&mut self, level: u8, from: &str, title: &str, text: &str) {
        let id = self.next_note;
        self.next_note = self.next_note.wrapping_add(1).max(1);
        // Свежие ПЕРВЫМИ и потолок на список: уведомления копятся сами собой, а «сто двадцать
        // штук» человек всё равно не читает — он читает последние.
        self.notes.insert(
            0,
            Note {
                id,
                level,
                from: String::from(from),
                title: String::from(title),
                text: String::from(text),
            },
        );
        self.notes.truncate(NOTES_MAX);
        // Всплывашка — на несколько секунд. Рисует её композитор сам: поверхности у уведомления
        // нет и не должно быть, иначе оно ловило бы клики по чужим окнам. «Не беспокоить» гасит
        // ВСПЛЫВАШКУ, а не уведомление: счёт идёт, колокольчик считает, человек прочтёт когда
        // захочет.
        if !self.dnd {
            let now = sys::monotonic_ns();
            self.toast = Some(Toast { id, at: now, until: now + TOAST_NS });
            self.damage_toast();
        }
    }

    fn damage_toast(&mut self) {
        if let Some(r) = self.toast_at() {
            self.damage(r);
        }
    }

    /// Веха 168.2 — насколько всплывашка ВЫТЯНУЛАСЬ (0..256).
    ///
    /// Одна формула на приход и уход: берётся меньшее из «сколько прошло от появления» и
    /// «сколько осталось до конца». Заведи мы два счёта — они разошлись бы сроками, и
    /// уведомление уходило бы не так, как пришло.
    ///
    /// Движение то же самое, что у полотен панели: карточка ВЫТЯГИВАЕТСЯ из своего верхнего
    /// края, а не проявляется. Проявление здесь было бы вдвойне неуместно — оно говорит «поверх
    /// экрана легло второе окно», а всплывашка окном как раз не является.
    fn toast_t(&self, now: u64) -> u32 {
        let Some(t) = self.toast else { return 0 };
        let d = self.anim * D_OPEN / 100 * 1_000_000;
        if d == 0 {
            return 256;
        }
        let came = (now.saturating_sub(t.at) * 1024 / d).min(1024) as i32;
        let left = (t.until.saturating_sub(now) * 1024 / d).min(1024) as i32;
        (ease_out(came.min(left)) / 4).clamp(0, 256) as u32
    }

    /// Сколько всплывашки видно СЕЙЧАС: полный прямоугольник, поджатый по высоте.
    fn toast_sheet(&self, now: u64) -> Option<At<Screen>> {
        let b = self.toast_at()?.rect();
        let h = b.h * self.toast_t(now) as i32 / 256;
        (h > 0).then(|| At::new(b.x, b.y, b.w, h))
    }

    /// Веха 168 — ВСПЛЫВАШКА строкой, как курсор и ярлык: пиксель экрана пишется ровно один раз
    /// за кадр.
    ///
    /// Веха 168.1 — по МАКЕТУ, а не «рамка и заливка»: скруглённая карточка цвета карточек
    /// системы, заголовок текстом, вторая строка приглушённой. Отличие важного — цвет
    /// ЗАГОЛОВКА, а не рамка вокруг: рамка кричит всей формой, а форма у всех уведомлений
    /// одна, и менять её значило бы делать важное другой сущностью.
    fn draw_toast_row(&self, out: &mut [u32], yy: i32, x0: i32, x1: i32) {
        let (Some(t), Some(b)) = (self.toast, self.toast_box) else {
            return;
        };
        let Some(n) = self.notes.iter().find(|n| n.id == t.id) else {
            return;
        };
        let r = b.rect();
        let ry = yy - r.y;
        if ry < 0 || ry >= r.h {
            return;
        }
        let bg = tri(self.th.bg);
        // Скругление не крупнее половины того, что видно: на первых кадрах карточка ниже своего
        // угла, и радиус «как задумано» вывернул бы форму наизнанку.
        let rad = TOAST_RAD.min(r.h / 2);
        let corner = ry < rad || r.h - 1 - ry < rad;
        for xx in r.x.max(x0)..r.right().min(x1) {
            // Скругление — тем же знаковым расстоянием, что у окон: две формулы «где угол»
            // разошлись бы, и у всплывашки углы оказались бы не системные.
            let cov = if corner {
                (128 - rrect_sd(xx, yy, r.x, r.y, r.w, r.h, rad)).clamp(0, 256) as u32
            } else {
                256
            };
            if cov == 0 {
                continue;
            }
            let i = (xx - x0) as usize;
            out[i] = self.blend(out[i], bg, cov);
        }
        let gh = sys::glyph::H as i32;
        let (line, gy) = ((ry - TOAST_PAD) / gh, (ry - TOAST_PAD) % gh);
        if ry < TOAST_PAD || line > 1 {
            return;
        }
        let text = if line == 0 { &n.title } else { &n.text };
        let col = self.pack(tri(match (line, n.level) {
            (0, win::NOTE_WARN) => self.th.danger,
            (0, _) => self.th.text,
            _ => self.th.muted,
        }));
        let mut cx = r.x + TOAST_PAD;
        for ch in text.chars() {
            let bits = sys::glyph::rows(ch)[gy as usize];
            for bit in 0..8 {
                let xx = cx + bit;
                if bits & (0x80 >> bit) != 0 && xx >= x0 && xx < x1 {
                    out[(xx - x0) as usize] = col;
                }
            }
            cx += sys::glyph::W as i32;
        }
    }

    /// Веха 166.1 — окна ЧУЖИХ процессов: тех, кого запустили не мы.
    ///
    /// `SYS_WAIT` отвечает только про СВОИХ детей, а приложение из строки запуска — ребёнок
    /// сторожа `run`, а не наш (Веха 147). Его смерть композитор не замечал вовсе: рамка
    /// оставалась на экране навсегда, с картинкой, за которой уже никого нет. Снаружи это
    /// выглядит не как «программа упала», а как «программа зависла», и разобраться в разнице
    /// человеку нечем — именно так и было увидено падение файлового менеджера.
    ///
    /// Спрашиваем ОБЗОРОМ (`sysview`) и не чаще раза в секунду: список процессов — это копия
    /// килобайтов на каждый оборот цикла, а падают программы не по расписанию. Права нет —
    /// проверки нет: композитор поднимается и без неё, просто ghost-окна живут до `Super+Q`.
    fn reap_foreign(&mut self) {
        if self.sysview == sys::NO_CAP {
            return;
        }
        let now = sys::monotonic_ns();
        if now.saturating_sub(self.liveness_at) < 1_000_000_000 {
            return;
        }
        self.liveness_at = now;
        let rec = sys::PROC_REC;
        let mut buf = vec![0u8; rec * 64];
        let Some(total) = sys::proc_list(self.sysview, &mut buf) else { return };
        let shown = total.min(buf.len() / rec);
        let alive = |pid: usize| {
            (0..shown).any(|k| {
                let r = &buf[k * rec..k * rec + rec];
                u16::from_le_bytes([r[0], r[1]]) as usize == pid
            })
        };
        // Список неполон (процессов больше, чем влезло) — не закрываем НИЧЕГО: отсутствие в
        // обрезанном списке не значит смерть, а закрытое по ошибке окно не вернуть.
        if total > shown {
            return;
        }
        for i in 0..self.wins.len() {
            if self.wins[i].closing || alive(self.wins[i].owner) {
                continue;
            }
            let id = self.wins[i].id;
            sys::write_console(
                alloc::format!("[wm] окно {}: хозяин P{} умер — убираю\n", id, self.wins[i].owner)
                    .as_bytes(),
            );
            self.begin_close(id);
            self.sync_focus();
            self.relayout();
            return;
        }
    }

    /// Веха 140 — разослать `EV_STATUS` подписавшимся, если состояние рабочего места изменилось.
    ///
    /// Зовётся раз за оборот, а не из каждого места, где состояние меняется: меняют его смена
    /// стола, фокус, закрытие окна, раскладка и обзор — рассылку из каждого пришлось бы
    /// вспоминать, а забытая означает бар, молча показывающий прошлое.
    fn notify_status(&mut self) {
        // Веха 143 — раскладка входит в снимок: её меняет не только наше действие (в ядре
        // остался зашитый Alt+Shift для текстового режима), поэтому спрашиваем, а не помним.
        // Веха 168 — счётчик уведомлений входит в снимок: панель рисует его у колокольчика, и
        // не разбудить её на новое уведомление значило бы показать вчерашнее число.
        let now = (
            self.space,
            self.space_count(),
            self.focus,
            sys::keymap(),
            self.overview,
            self.notes.len(),
            self.dnd,
        );
        if now == self.status {
            return;
        }
        self.status = now;
        for i in 0..self.wins.len() {
            if self.wins[i].watching {
                self.send(i, win::Event::Status);
            }
        }
    }

    /// Веха 145 — ближайший срок, которого ждёт кто-то из клиентов. `None` — все ждут бессрочно.
    ///
    /// По нему укорачивается СОБСТВЕННЫЙ сон композитора: срок, который проверяют раз в 200 мс,
    /// на анимацию не годится, а часам бара он и так был не нужен. Простой при этом не страдает —
    /// когда никто ничего не просил, шаг остаётся прежним.
    fn next_deadline(&self, now: u64) -> Option<u64> {
        self.wins
            .iter()
            .filter(|w| w.waiting.is_some())
            .filter_map(|w| w.wait_until)
            // Веха 168 — срок ВСПЛЫВАШКИ здесь же: она гаснет сама, и «раз в 200 мс» ей не
            // годится — человек увидел бы, как она держится лишнюю пятую секунды.
            .chain(self.toast.map(|t| t.until))
            .map(|d| d.max(now))
            .min()
    }

    /// Веха 140 — вышел срок ожидания события: ответить ПУСТО, а не держать клиента дальше.
    /// Пустой ответ клиент читает как «событий не было», и это тот же ответ, что у `OP_POLL`.
    fn expire_waits(&mut self, now: u64) {
        for i in 0..self.wins.len() {
            if !self.wins[i].wait_until.is_some_and(|d| now >= d) {
                continue;
            }
            self.wins[i].wait_until = None;
            if let Some(cap) = self.wins[i].waiting.take() {
                sys::reply(cap, &[]);
            }
        }
    }

    /// Отдать событие клиенту: сразу, если он ждёт, иначе в очередь.
    ///
    /// Веха 148.4 — событие здесь СОБЫТИЕ, а не восемь байт с длиной в восьмом. Байтами оно
    /// становится в одном месте — [`win::Event::encode`], рядом с разбором на той стороне.
    fn send(&mut self, i: usize, ev: win::Event) {
        match self.wins[i].waiting.take() {
            Some(cap) => {
                self.wins[i].wait_until = None; // ждать больше нечего — срок снимаем вместе с ним
                reply_event(cap, ev);
            }
            None => {
                // Веха 148.2 — ДВИЖЕНИЯ СЛИПАЮТСЯ. Если последним в очереди уже лежит движение,
                // новое его заменяет: клиенту нужна текущая точка курсора, а не путь, которым тот
                // до неё дошёл. Разбудить программу шестнадцать раз подряд ради шестнадцати точек,
                // из которых значима последняя, — это ровно тот способ отстать от руки, на который
                // жаловался владелец (подсветка во вьювере тянулась за курсором).
                //
                // Заменяем ТОЛЬКО последнее: так порядок с нажатиями и клавишами не рушится —
                // движение, стоящее перед кнопкой, остаётся перед ней.
                if matches!(ev, win::Event::Motion { .. }) {
                    if let Some(last) = self.wins[i].inbox.last_mut() {
                        if matches!(last, win::Event::Motion { .. }) {
                            *last = ev;
                            return;
                        }
                    }
                }
                // Потолок разный по СМЫСЛУ события: движения мыши устаревают мгновенно (копить
                // их сотнями значит показывать клиенту прошлое), а клавиши терять нельзя —
                // человек их уже нажал. Строка, вставленная в консоль целиком, приезжает
                // десятками байт разом, и потолок в 16 съедал её середину.
                let cap = if matches!(ev, win::Event::Key { .. }) { 256 } else { 16 };
                if self.wins[i].inbox.len() < cap {
                    self.wins[i].inbox.push(ev);
                }
            }
        }
    }

    // ── буферы кадров клиентов (Веха 129) ──────────────────────────────────────────────

    /// Веха 169.1 — занять `n` подряд идущих зёрен окна ВА. `None` — столько подряд не нашлось.
    ///
    /// Первым подходящим (first-fit), а не лучшим: областей десятки, а не тысячи, и лучшая
    /// подгонка тут стоила бы дороже дырок, которые она экономит.
    fn take_grains(&mut self, n: usize) -> Option<usize> {
        let busy = |g: &[u64; SHM_WORDS], i: usize| g[i / 64] & (1 << (i % 64)) != 0;
        let mut at = 0;
        while at + n <= SHM_GRAINS {
            // Ищем занятое В КОНЦЕ куска: наткнулись — начинать надо сразу за ним, а не с
            // следующего зерна, иначе обход становится квадратичным на плотной карте.
            match (at..at + n).rev().find(|&i| busy(&self.grains, i)) {
                Some(bad) => at = bad + 1,
                None => {
                    for i in at..at + n {
                        self.grains[i / 64] |= 1 << (i % 64);
                    }
                    return Some(at);
                }
            }
        }
        None
    }

    /// Вернуть зёрна.
    fn free_grains(&mut self, at: usize, n: usize) {
        for i in at..(at + n).min(SHM_GRAINS) {
            self.grains[i / 64] &= !(1 << (i % 64));
        }
    }

    /// Отобразить у себя область, право на которую прислал клиент. `None` — права нет, область
    /// не та или места в окне ВА не осталось.
    ///
    /// Ошибка здесь — НЕ повод падать: право приходит от клиента, а клиент может прислать что
    /// угодно. Окно просто останется без картинки (рамка и место в раскладке у него будут) — но
    /// молчать об этом нельзя: окно цвета рамки неотличимо от сломанной программы, и владелец
    /// нашёл это ровно так. Поэтому о нехватке места композитор говорит УВЕДОМЛЕНИЕМ.
    fn map_client_buf(&mut self, cap: usize, w: i32, h: i32) -> Option<(usize, usize, usize, usize)> {
        if cap == sys::NO_CAP {
            sys::write_console("[wm] окно без буфера: клиент не прислал права на область\n".as_bytes());
            return None;
        }
        let need = (w.max(0) as usize * h.max(0) as usize * 4).div_ceil(SHM_GRAIN).max(1);
        let Some(slot) = self.take_grains(need) else {
            sys::write_console("[wm] окно без буфера: кончилось окно ВА под чужие кадры\n".as_bytes());
            self.post_note(
                2,
                ui::t("композитор"),
                ui::t("окну не хватило места"),
                ui::t("кончилось адресное пространство под кадры окон — закройте часть окон"),
            );
            return None;
        };
        let va = SHM_BASE + slot * SHM_GRAIN;
        let Some(len) = sys::shm_map(cap, va) else {
            sys::write_console("[wm] окно без буфера: область не отобразилась\n".as_bytes());
            self.free_grains(slot, need);
            return None;
        };
        // Область обязана вмещать кадр объявленного размера: рисуем мы по ЕЁ содержимому, и
        // короткая область значила бы чтение за краем на каждой строке. И не быть длиннее взятых
        // зёрен — иначе она накрыла бы соседа (см. [`SHM_BASE`]).
        if len < (w * h * 4) as usize || len > need * SHM_GRAIN {
            sys::write_console("[wm] окно без буфера: область не того размера\n".as_bytes());
            sys::shm_unmap(cap, va);
            self.free_grains(slot, need);
            return None;
        }
        Some((va, len, slot, need))
    }

    /// Веха 147.1 — ПОКАЗАТЬ принятый буфер: отпустить старый, переставить поля, а у СЛОЯ заодно
    /// применить новое место.
    ///
    /// Всё вместе и ровно здесь — в этом весь смысл. Картинка, размер буфера и прямоугольник
    /// поверхности меняются одним движением, поэтому кадра «новое место со старой картинкой»
    /// (растянутой) не существует так же, как и кадра с пустой областью.
    fn swap_buf(&mut self, i: usize) {
        let Some(p) = self.wins[i].next.take() else { return };
        self.drop_buf(i);
        let win = &mut self.wins[i];
        win.buf = p.va;
        win.buf_len = p.len;
        win.cap = p.cap;
        win.slot = p.slot;
        win.span = p.span;
        win.bw = p.w;
        win.bh = p.h;
        // Веха 145 — у СЛОЯ размер буфера и есть размер поверхности: место он называет сам (то же
        // правило, что при рождении в `OP_LAYER`). У окна ленты наоборот — там место назначает
        // раскладка, и трогать его отсюда значило бы дать клиенту переставлять себя мимо неё.
        //
        // Занятую зону НЕ пересчитываем от нового размера: она названа один раз и живёт в
        // `LayerCfg`. Иначе панель, выросшая на экран ради меню, увела бы под себя все окна.
        let Some(l) = self.wins[i].layer else { return };
        let old = self.wins[i].place(self.scroll_x);
        let place = self.layer_rect(&l, p.w, p.h);
        // У СЛОЯ лента не едет: его собственная лента и есть экран (см. [`Win::place`]).
        let r = place.to_strip(0).rect();
        let win = &mut self.wins[i];
        (win.x, win.y, win.w, win.h) = (r.x, r.y, r.w, r.h);
        let to = Shown { x: r.x, y: r.y, w: r.w, h: r.h, a: win.shown.a };
        win.shown = to;
        win.from = to;
        win.to = to;
        win.dur = 0;
        // Веха 168.3 — помечаем ТОЛЬКО СТАРОЕ место, а не новое.
        //
        // Слой панели вырастает на весь экран, когда открывается меню, и здесь стоял
        // `damage(place)` — то есть пересборка миллиона точек ради полотна в три сотни на две.
        // Счётчик кадров (`fps`) назвал этот кадр поимённо: 11.7 мс сборки, 100 % экрана, и
        // ровно на нём движение и спотыкалось — весь бюджет кадра уходил в один кадр.
        //
        // Новое место помечать не нужно: свежие страницы общего буфера ПРОЗРАЧНЫ (ядро отдаёт их
        // обнулёнными), а прозрачный слой поверх стола даёт тот же пиксель, что был без него.
        // Что клиент в этот буфер нарисует, он скажет сам — прямоугольником своего кадра, и
        // приедет он этим же сообщением, строкой ниже.
        //
        // Старое место — наоборот, обязательно: слой мог СЖАТЬСЯ, и то, что он занимал, надо
        // из-под него открыть. Но и там — только НАРИСОВАННОЕ (`touched`): остальное в старом
        // буфере было прозрачным, и стол под ним уже такой, какой нужен.
        let was = self.touched_on(i, old);
        self.wins[i].touched = Rect::ZERO;
        self.damage(was);
        if (r.w, r.h) != (p.w, p.h) {
            let ev = win::Event::Resize { w: r.w as u16, h: r.h as u16 };
            self.send(i, ev);
        }
    }

    /// Отпустить ПРИНЯТЫЙ, но не показанный буфер (клиент прислал новый, не нарисовав в старый).
    fn drop_next(&mut self, i: usize) {
        let Some(p) = self.wins[i].next.take() else { return };
        sys::shm_unmap(p.cap, p.va);
        self.free_grains(p.slot, p.span);
    }

    /// Отпустить буфер окна: снять отображение и вернуть зёрна. Ушли оба держателя — страницы
    /// вернулись системе.
    fn drop_buf(&mut self, i: usize) {
        let w = &mut self.wins[i];
        if w.buf == 0 {
            return;
        }
        sys::shm_unmap(w.cap, w.buf);
        let (slot, span) = (w.slot, w.span);
        w.buf = 0;
        w.buf_len = 0;
        w.bw = 0;
        w.bh = 0;
        self.free_grains(slot, span);
    }

    // ── плитка запуска (Веха 147) ──────────────────────────────────────────────────────

    /// Плитка, которая ждёт окна от процесса `pid` **или от его потомка**.
    ///
    /// Потомок — не тонкость, а обычный случай: программа вполне может открыть окно не сама, а
    /// запустив кого-то (так делает всякий, кто «оболочка вокруг»). ADR 0016 требует этого
    /// дословно, а средство есть с Вехи 114 — `SYS_PARENT`.
    ///
    /// Глубина ограничена: цепочка предков конечна, но за ней стоит ЯДРО, а не наши данные, и
    /// зацикливаться на чужих числах композитор не должен.
    fn tile_for(&self, pid: usize) -> Option<usize> {
        let mut p = pid;
        for _ in 0..8 {
            if let Some(k) = self
                .wins
                .iter()
                .position(|w| w.launch.as_ref().is_some_and(|l| l.pid == p && l.done.is_none()))
            {
                return Some(k);
            }
            match sys::parent_of(p) {
                Some(up) if up != p => p = up,
                _ => break,
            }
        }
        None
    }

    /// Перерисовать плитку, если её кадр устарел. `true` — кадр обновился и его надо показать.
    ///
    /// Рисуем НЕ каждый кадр, а по трём числам: размер плитки и фаза бегунка. Иначе композитор
    /// собирал бы одну и ту же картинку шестьдесят раз в секунду ради полосы, которая двигается
    /// двадцать пять.
    fn render_launch(&mut self, i: usize, now: u64) -> bool {
        // Копия темы: ниже окно берётся `&mut self.wins[i]`, и одолжить `self.th` рядом уже
        // нельзя. Плитка перерисовывается раз в 40 мс — цена копии здесь не видна ничем.
        let th = self.th.clone();
        let Win { launch: Some(l), own, bw, bh, w, h, .. } = &mut self.wins[i] else {
            return false;
        };
        // Веха 151 — внутри СНИМОК прошлого сеанса: рисовать поверх нечего. Бегунок здесь был бы
        // ложью — мы не запускаем с нуля, мы возвращаем то, что было. А вот карточку с кодом
        // выхода снимок не отменяет: если программа умерла, не показав окна, картинка живого окна
        // — враньё уже в другую сторону.
        if l.shot && l.done.is_none() {
            return false;
        }
        let (cw, ch) = ((*w).max(1), (*h).max(1));
        // Фаза бегунка: 40 мс на шаг, пока ждём и не вышел срок. `MAX` — «стоим»: и после
        // итога, и после срока ожидания. Бесконечно бегущая полоса — то же враньё, что и
        // спиннер после смерти: она обещает, что вот-вот.
        let phase = if l.done.is_none() && now.saturating_sub(l.since) < LAUNCH_ANIM_NS {
            (now.saturating_sub(l.since) / 40_000_000) as u32
        } else {
            u32::MAX
        };
        if l.drawn == Some((cw, ch, phase)) {
            return false;
        }
        l.drawn = Some((cw, ch, phase));
        let need = (cw * ch * 4) as usize;
        let px = own.get_or_insert_with(Vec::new);
        if px.len() != need {
            px.clear();
            px.resize(need, 0);
        }
        draw_tile(px, cw, ch, l, phase, now, &th);
        *bw = cw;
        *bh = ch;
        true
    }

    // ── запросы клиентов ───────────────────────────────────────────────────────────────

    /// Веха 155 — отдавать ли просителю право обзора процессов ([`win::OP_GRANT`]).
    /// [`sys::NO_CAP`] — нет, и это ответ по умолчанию на всё непонятное.
    ///
    /// Кто просит — говорит ЯДРО: номер отправителя приходит с сообщением (`m.sender`), а имя
    /// процесса берётся из его же списка процессов. Спросить самого просителя было бы не
    /// проверкой, а анкетой: назвать чужое имя в запросе может кто угодно.
    fn grant_for(&self, pid: usize, kind: u8) -> usize {
        // Раздаём только то, что объявлено раздаваемым. Экран (`mmio:fb`) в этом списке не
        // появится: рисовать поверх чужих окон и читать их пиксели не нужно никому из клиентов,
        // и просьбу о нём правильнее отклонить молча, чем обсуждать.
        let cap = match kind {
            13 => self.sysview,
            10 => self.power,
            // Веха 166 — вид 4 (эндпоинт) у композитора значит РОВНО ОДНО: канал к серверу
            // сети. Других он не раздаёт, и просить «эндпоинт вообще» здесь бессмысленно —
            // у каждого свой адресат, а вид один на всех.
            4 => self.netcap,
            _ => sys::NO_CAP,
        };
        if cap == sys::NO_CAP || !self.grants.iter().any(|(k, _)| *k == kind) {
            return sys::NO_CAP;
        }
        // Имя просителя спрашиваем У ЯДРА, а не у него самого. Для этого нужен обзор процессов;
        // без него композитор не может проверить НИЧЕГО и потому не раздаёт ничего.
        if self.sysview == sys::NO_CAP {
            return sys::NO_CAP;
        }
        let rec = sys::PROC_REC;
        let mut buf = vec![0u8; rec * 64];
        let Some(total) = sys::proc_list(self.sysview, &mut buf) else { return sys::NO_CAP };
        for k in 0..total.min(buf.len() / rec) {
            let r = &buf[k * rec..k * rec + rec];
            if u16::from_le_bytes([r[0], r[1]]) as usize != pid {
                continue;
            }
            let nlen = (r[7] as usize).min(24);
            let name = core::str::from_utf8(&r[40..40 + nlen]).unwrap_or("");
            let ok = self.grants.iter().any(|(k, who)| *k == kind && who == name);
            sys::write_console(
                alloc::format!(
                    "[wm] право {}: P{} «{}» — {}\n",
                    match kind {
                        13 => "обзора процессов",
                        10 => "выключения",
                        4 => "канала к сети",
                        _ => "неизвестного вида",
                    },
                    pid,
                    name,
                    if ok { "выдано" } else { "ОТКАЗ (конфиг называет другого)" },
                )
                .as_bytes(),
            );
            return if ok { cap } else { sys::NO_CAP };
        }
        sys::NO_CAP
    }

    fn request(&mut self, m: &sys::Message, buf: &[u8]) {
        let op = m.op & 0xff;
        let len = m.len.min(buf.len());
        // Тело запроса — РОВНО присланные байты, и разбирается оно описанием протокола
        // (`win::wire`), а не индексами здесь. Веха 148.4; до неё поля брались по смещению без
        // оглядки на длину, а приёмный буфер один на все запросы — короткий запрос читался
        // вперемешку с хвостом предыдущего, и `OP_DESTROY` без номера закрывал случайное чужое
        // окно. `OP_CREATE` короче четырёх байт вовсе ронял композитор, то есть весь экран.
        let req = &buf[..len];
        match op {
            win::OP_CREATE => {
                let c = body!(m, win::wire::Create::decode(req));
                let w = c.w.clamp(32, 1600) as i32;
                let h = c.h.clamp(32, 1200) as i32;
                let title = core::str::from_utf8(c.title).unwrap_or("окно");
                let id = self.next_id;
                self.next_id += 1;
                // Веха 147 — не ждёт ли это окно ПЛИТКА? Тогда оно займёт её место в ленте, а не
                // заведёт новую колонку: плитка для того и стоит, чтобы раскладка не прыгнула,
                // когда окно наконец появится.
                let tile = self.tile_for(m.sender);
                // Каскадом: каждое следующее окно правее и ниже — иначе они лягут друг на друга
                // и человек решит, что открылось одно.
                let n = self.wins.len() as i32;
                // Буфер кадра приезжает ПРАВОМ вместе с запросом: окно рождается уже с
                // картинкой. Не дали — окно всё равно будет, просто пустое.
                let (buf, buf_len, slot, span) =
                    self.map_client_buf(m.cap, w, h).unwrap_or((0, 0, 0, 0));
                let win = Win {
                    id,
                    owner: m.sender,
                    x: 60 + n * 40,
                    y: 60 + n * 40,
                    w,
                    h,
                    title: String::from(title),
                    buf,
                    buf_len,
                    cap: m.cap,
                    slot,
                    span,
                    bw: if buf != 0 { w } else { 0 },
                    bh: if buf != 0 { h } else { 0 },
                    touched: Rect::ZERO,
                    waiting: None,
                    wait_until: None,
                    watching: false,
                    inbox: Vec::new(),
                    shown: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                    from: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                    to: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                    at: 0,
                    dur: 0,
                    fresh: true,
                    closing: false,
                    visible: true,
                    layer: None,
                    next: None,
                    launch: None,
                    run: None,
                    snap: None,
                    asked: false,
                    own: None,
                };
                self.wins.push(win);
                if let Some(k) = tile {
                    // Плитка ДОЖДАЛАСЬ своего окна. Окно встаёт ровно на её место — и в ленте, и
                    // на экране: `shown` наследуется, поэтому подмена не мигает и не едет.
                    // Разворачивать окно из точки, как обычное новое, здесь было бы враньём в
                    // другую сторону — оно не появилось, оно ПРИШЛО НА ГОТОВОЕ место.
                    //
                    // Веха 151 — но только если плитка стоит на АКТИВНОМ столе. Плитка чужого
                    // стола не раскладывалась ни разу (раскладка обходит одну ленту — активную),
                    // и её `shown` — нули: унаследовав их, окно выехало бы из угла экрана в тот
                    // миг, когда на его стол впервые перейдут. Пусть лучше появится как новое —
                    // для человека оно там и правда появляется впервые.
                    let old = self.wins[k].id;
                    let on_active = self.locate(old).is_some();
                    let shown = self.wins[k].shown;
                    // Веха 151.1 — окно НАСЛЕДУЕТ запись сеанса у своей плитки: команду и снимок.
                    // Плитка знала, чем её позвали, — а пришедшее окно об этом не знает ничего,
                    // и спросить его мы успеем позже.
                    let (run, snap) = {
                        let t = &mut self.wins[k];
                        (t.run.take(), t.snap.take())
                    };
                    let n = self.wins.len() - 1;
                    self.wins[n].shown = shown;
                    self.wins[n].to = shown;
                    self.wins[n].from = shown;
                    self.wins[n].fresh = !on_active;
                    self.wins[n].run = run;
                    self.wins[n].snap = snap;
                    self.relink(old, id);
                    self.wins.remove(k);
                    sys::reply(m.reply_cap, &id.to_le_bytes());
                    self.sync_focus();
                    self.relayout();
                    return;
                }
                // Новое окно — НОВАЯ КОЛОНКА справа от текущей: так работает niri, и так же
                // ведёт себя лента при `Super+Return`. Класть его в текущую колонку значило бы
                // делить экран по вертикали без просьбы.
                let at = if self.cols.is_empty() { 0 } else { self.cur + 1 };
                self.cols.insert(at, Column { ids: vec![id], width: 1, focus: 0 });
                self.cur = at;
                // Веха 137 — окно село на последний (пустой) стол: пустого в конце больше нет,
                // и его надо завести, иначе «дальше» переходить будет некуда.
                self.tidy_spaces();
                sys::reply(m.reply_cap, &id.to_le_bytes());
                self.sync_focus();
                self.relayout();
            }
            // Веха 139 — ПОВЕРХНОСТЬ СЛОЯ: обои, бар, панель. Отличий от окна ровно два — место
            // назначает не раскладка, а якорь, и в ленту она не встаёт.
            win::OP_LAYER => {
                let l = body!(m, win::wire::LayerReq::decode(req));
                let spec = LayerCfg {
                    layer: l.spec.layer,
                    anchor: l.spec.anchor,
                    // Занятая зона не может превышать экран: клиент присылает что угодно.
                    exclusive: (l.spec.exclusive as i32)
                        .min(self.info.height as i32)
                        .min(self.info.width as i32),
                    alpha: l.spec.alpha,
                    kbd: l.spec.kbd,
                };
                let w = l.w.max(1) as i32;
                let h = l.h.max(1) as i32;
                let title = core::str::from_utf8(l.title).unwrap_or("слой");
                let id = self.next_id;
                self.next_id += 1;
                let (buf, buf_len, slot, span) =
                    self.map_client_buf(m.cap, w, h).unwrap_or((0, 0, 0, 0));
                // У СЛОЯ лента не едет: его собственная лента и есть экран ([`Win::place`]).
                let place = self.layer_rect(&spec, w, h);
                let r = place.to_strip(0).rect();
                // Проявляются только ОБОИ (нижний слой): см. ниже, у поля `shown`.
                let fade = spec.layer == win::LAYER_BG;
                let win = Win {
                    id,
                    owner: m.sender,
                    x: r.x,
                    y: r.y,
                    w: r.w,
                    h: r.h,
                    title: String::from(title),
                    buf,
                    buf_len,
                    cap: m.cap,
                    slot,
                    span,
                    bw: if buf != 0 { w } else { 0 },
                    bh: if buf != 0 { h } else { 0 },
                    touched: Rect::ZERO,
                    waiting: None,
                    wait_until: None,
                    watching: false,
                    inbox: Vec::new(),
                    // Слой не ЕЗДИТ: он появляется там, где ему назначено. Выезжающие обои или
                    // подпрыгивающий бар — не «оживление», а рябь на каждом запуске.
                    //
                    // Веха 142 — но обои ПРОЯВЛЯЮТСЯ. Место при этом не меняется, меняется только
                    // непрозрачность: снимок с телефона распаковывается заметное время, и до
                    // этого момента стол уже нарисован — без проявления картинка возникает
                    // рывком, будто что-то моргнуло. Бар этого не требует: он появляется сразу.
                    shown: Shown { x: r.x, y: r.y, w: r.w, h: r.h, a: if fade { 0 } else { 256 } },
                    from: Shown { x: r.x, y: r.y, w: r.w, h: r.h, a: if fade { 0 } else { 256 } },
                    to: Shown { x: r.x, y: r.y, w: r.w, h: r.h, a: 256 },
                    at: 0,
                    dur: 0,
                    // «Свежая» поверхность — та, что ещё ни разу не нарисовала себя. Для обоев
                    // это и есть повод проявиться, когда картинка появится (см. `OP_COMMIT`).
                    fresh: fade,
                    closing: false,
                    visible: true,
                    layer: Some(spec),
                    next: None,
                    launch: None,
                    run: None,
                    snap: None,
                    asked: false,
                    own: None,
                };
                self.wins.push(win);
                sys::reply(m.reply_cap, &id.to_le_bytes());
                // Клиент просил один размер, якорь назначил другой (растянуться на весь край) —
                // сказать ему об этом тем же событием, что и окнам: пусть заведёт буфер под то,
                // что ему на самом деле дали. До ответа рисуем растянутым — как и окно, которое
                // ещё не успело перерисоваться (Веха 126.1).
                if (r.w, r.h) != (w, h) {
                    let k = self.wins.len() - 1;
                    self.send(k, win::Event::Resize { w: r.w as u16, h: r.h as u16 });
                }
                // Веха 169 — **место слоя НЕ помечается**, и это не экономия, а исправление.
                //
                // Поверхность только что создана: её страницы обнулены ядром, то есть прозрачны,
                // и прозрачное поверх стола даёт ровно тот же пиксель, что и его отсутствие.
                // Помечать тут нечего — рисовать начнёт первый `OP_COMMIT`, и пометит он ровно
                // то, что нарисовал.
                //
                // Стоило это ровно того, на что жаловался владелец. Строка запуска растянута НА
                // ВЕСЬ ЭКРАН (иначе ей не поймать щелчок мимо себя), поэтому каждое её открытие
                // начиналось с пересборки миллиона точек — 11 мс в QEMU+KVM по замеру `fps`
                // («самый тяжёлый кадр: 100% экрана»), а на железе, где кадр едет по шине,
                // заметно больше. Ровно в тот миг, когда карточка начинает разворачиваться, —
                // отсюда и «рванее всего именно лаунчер».
                // Зона могла отнять место у ленты — пересчёт раскладки внутри.
                self.recompute_work();
            }
            // Веха 150 — БУФЕР ОБМЕНА. Композитор держит ИМЯ содержимого, а не содержимое:
            // байты положил в store сам копирующий, и через IPC они не едут ни разу (ADR 0016).
            //
            // Почему это дело композитора, а не отдельной службы: буфер обмена — вопрос «кто
            // сейчас на экране и кто у кого забирает», а на него отвечает тот, кто держит фокус.
            // Отдельная служба знала бы про фокус только с чужих слов.
            win::OP_CLIP_SET => {
                let c = body!(m, win::wire::Clip::decode(req));
                // Корень ДВИГАЕМ ПЕРВЫМ делом: без него объект недостижим, и ближайшая сборка
                // мусора store унесла бы скопированное. Не вышло — не принимаем вовсе: сказать
                // «принято» и потерять текст хуже, чем отказать сразу.
                if sys::obj_set_root(self.store, b"clip/current", &c.id) != 0 {
                    sys::reply(m.reply_cap, &[]);
                    return;
                }
                self.clip = Some((c.kind, c.id));
                sys::reply(m.reply_cap, &[1]);
            }
            win::OP_CLIP_GET => match self.clip {
                Some((kind, id)) => {
                    let mut rep = [0u8; 33];
                    let n = win::wire::Clip { kind, id }.encode(&mut rep);
                    sys::reply(m.reply_cap, &rep[..n]);
                }
                None => {
                    sys::reply(m.reply_cap, &[]);
                }
            },
            // Веха 151 — ответ на «сохранись»: чем звать это окно обратно.
            //
            // Принимаем ТОЛЬКО во время сбора: командная строка нужна ровно в момент записи
            // сеанса, и держать её между разами значило бы хранить прошлогоднее обещание. Окно
            // называет себя само, но проверяем мы его — хозяина окна говорит ядро.
            win::OP_PERSIST => {
                let p = body!(m, win::wire::Persist::decode(req));
                let run = core::str::from_utf8(p.run).unwrap_or("").trim();
                let mine = self
                    .win_at(p.id)
                    .filter(|&k| self.wins[k].owner == m.sender && self.wins[k].tiled());
                match mine {
                    Some(k) if !run.is_empty() => {
                        // Ответ помнит ОКНО, а не сбор: сеанс переписывается и по ходу дела,
                        // когда никто ничего не спрашивал (Веха 151.1), и брать команду тогда
                        // было бы неоткуда.
                        self.wins[k].run = Some(String::from(run));
                        if let Some(s) = self.saving.as_mut() {
                            s.got += 1;
                        }
                        sys::reply(m.reply_cap, &[1]);
                    }
                    _ => {
                        sys::reply(m.reply_cap, &[]);
                    }
                }
            }
            // ── Веха 150.1: ПЕРЕТАСКИВАНИЕ ────────────────────────────────────────────────
            //
            // Груз тот же, что у буфера обмена, — объект store плюс имя. Композитор берётся за
            // него по той же причине, по какой держит буфер: он один знает, где рука.
            //
            // Соглашаемся только на то, что можем ПРОВЕРИТЬ, и проверяем ровно два факта.
            win::OP_DRAG => {
                let d = body!(m, win::wire::Drag::decode(req));
                // Первый: кнопка сейчас ДЕРЖИТСЯ. Без неё программа завела бы перетаскивание,
                // которого рука не начинала, — ярлык поехал бы за курсором сам по себе, и убрать
                // его человеку было бы нечем.
                //
                // Второй: курсор над поверхностью САМОГО просящего. Хозяина окна называет ядро
                // (`m.sender`), а не запрос, — тот же довод, что у плитки запуска: назвать чужой
                // номер может кто угодно. Иначе любой желающий подменял бы груз в чужом
                // перетаскивании, дождавшись, пока сосед нажмёт кнопку.
                let src = self
                    .hover
                    .and_then(|h| self.win_at(h))
                    .filter(|&i| self.wins[i].owner == m.sender && self.buttons != 0);
                let Some(i) = src else {
                    sys::reply(m.reply_cap, &[]);
                    return;
                };
                // Корень — ПЕРВЫМ делом, как и у буфера: без него груз недостижим, и сборка
                // мусора store забрала бы его прямо из-под руки.
                if sys::obj_set_root(self.store, b"drag/current", &d.id) != 0 {
                    sys::reply(m.reply_cap, &[]);
                    return;
                }
                // Подпись режем ЗДЕСЬ, а не при рисовании: ширина ярлыка считается по ней в двух
                // местах (пометка и сборка строки), и считать её длину заново значило бы завести
                // вторую истину о том, что поместилось, — те же грабли, что у плитки запуска.
                // Не UTF-8 — ярлык без подписи, а не отказ: груз от этого не портится, а
                // «починить» чужую строку композитор всё равно не может.
                let full = core::str::from_utf8(d.label).unwrap_or("");
                let mut label: String = full.chars().take(BADGE_CHARS).collect();
                if full.chars().count() > BADGE_CHARS {
                    label.push('…');
                }
                self.carry = Some(Payload { kind: d.kind, id: d.id, label, from: self.wins[i].id });
                // Под курсором появился ярлык — там, где его нет, надо перерисовать.
                self.damage_pointer(self.cursor);
                sys::reply(m.reply_cap, &[1]);
            }
            // Забрать уронённое — и ровно один раз: отдали имя и забыли. Отдаём ТОМУ, в кого
            // роняли: чужой спросивший получает пустой ответ, а не чужой груз.
            win::OP_DROP => {
                let mine = self.dropped.filter(|&(id, _, _)| {
                    self.win_at(id).is_some_and(|k| self.wins[k].owner == m.sender)
                });
                match mine {
                    Some((_, kind, id)) => {
                        self.dropped = None;
                        let mut rep = [0u8; 33];
                        let n = win::wire::Clip { kind, id }.encode(&mut rep);
                        sys::reply(m.reply_cap, &rep[..n]);
                    }
                    None => {
                        sys::reply(m.reply_cap, &[]);
                    }
                }
            }
            // Веха 139 — размер экрана. Обоям и бару он нужен ДО того, как они заведут буфер, а
            // права на сам фреймбуфер у них нет и быть не должно.
            win::OP_SCREEN => {
                let mut rep = [0u8; 4];
                let s = win::wire::Screen {
                    w: self.info.width as u16,
                    h: self.info.height as u16,
                };
                let n = s.encode(&mut rep);
                sys::reply(m.reply_cap, &rep[..n]);
            }
            // Веха 129 — НОВЫЙ буфер под изменившийся размер.
            //
            // Веха 147.1 — буфер принимается В ЗАПАС и показывается только с первым кадром в нём
            // (`OP_COMMIT`, см. [`Wm::swap_buf`]). Раньше подмена была немедленной, и всё время
            // между «принял» и «клиент нарисовал» — 6–25 мс по замеру, то есть кадр-другой —
            // композитор показывал ПУСТУЮ область. На панели это видно прямо: открываешь меню,
            // и она на миг пропадает.
            win::OP_REBUF => {
                let r = body!(m, win::wire::Rebuf::decode(req));
                let (id, w, h) = (r.id, r.w as i32, r.h as i32);
                if let Some(i) = self.wins.iter().position(|x| x.id == id) {
                    // Второй `OP_REBUF` без кадра между ними: предыдущий запас не показали и уже
                    // не покажем — отпускаем, иначе слот окна ВА утёк бы.
                    self.drop_next(i);
                    if let Some((va, len, slot, span)) = self.map_client_buf(m.cap, w, h) {
                        self.wins[i].next =
                            Some(Pending { va, len, cap: m.cap, slot, span, w, h });
                    }
                }
                // Ответ ПОСЛЕ отображения: клиент по возврату из вызова отпускает свою старую
                // область, и делать это, пока мы ещё в неё смотрим, нельзя.
                sys::reply(m.reply_cap, &[]);
            }
            win::OP_COMMIT => {
                let c = body!(m, win::wire::Commit::decode(req));
                // Ответ — не здесь, а после сборки кадра (см. [`Wm::commit_reply`]).
                self.commit_reply.push(m.reply_cap);
                // Веха 168.3 — клиентский кадр приехал. Считаем ЗДЕСЬ, а не в `flush`: между
                // «клиент нарисовал» и «оказалось на экране» лежит всё, что нас интересует, и
                // сложить эти два события в одно значило бы стереть саму разницу.
                self.frames.commits += 1;
                self.frames.since += 1;
                if let Some(i) = self.wins.iter().position(|w| w.id == c.id) {
                    // Веха 147.1 — вот он, первый кадр в новом буфере: показываем его целиком
                    // (буфер + место поверхности) ДО разбора повреждения, иначе прямоугольник
                    // считался бы в координатах уже неактуального кадра.
                    self.swap_buf(i);
                    // Веха 168.3 — и запоминаем, ЧТО он нарисовал: по этому следу поверхность
                    // потом и уберут — площадью нарисованного, а не площадью поверхности. После
                    // смены буфера, а не до: след принадлежит буферу, а не окну.
                    let drew = Rect::new(c.x as i32, c.y as i32, c.w as i32, c.h as i32);
                    self.wins[i].touched = self.wins[i].touched.union(drew);
                    // Веха 142 — ПЕРВЫЙ кадр обоев: отсюда и начинается их проявление.
                    //
                    // Не с создания поверхности: обои распаковывают картинку и просят место
                    // ДО того, как им есть что показать. Проявись они от
                    // создания — проявился бы пустой буфер, а картинка потом возникла бы рывком,
                    // то есть ровно тем, от чего проявление и заводили.
                    if self.wins[i].fresh && !self.wins[i].tiled() {
                        self.wins[i].fresh = false;
                        let r = self.wins[i].shown.rect().rect();
                        let d = self.anim * D_OPEN / 100;
                        let to = Shown { x: r.x, y: r.y, w: r.w, h: r.h, a: 256 };
                        self.wins[i].start(to, d, sys::monotonic_ns());
                    }
                    let (dx, dy) = (c.x as i32, c.y as i32);
                    let (dw, dh) = (c.w as i32, c.h as i32);
                    // Прямоугольник клиента — в КООРДИНАТАХ ЭКРАНА, а это не то же самое, что его
                    // место в раскладке. Считать надо от ПОКАЗАННОГО положения (`shown`) за
                    // вычетом сдвига ленты: лента длиннее экрана и по нему ездит.
                    //
                    // Здесь было `content_at()` — место окна в ЛЕНТЕ. Пока окон было два, лента
                    // никуда не уезжала (сдвиг 0) и разницы не было видно; третье окно её
                    // сдвигало, и повреждения всех последующих кадров уходили за край экрана.
                    // Выглядело это так, будто новое окно рождается ЧЁРНЫМ: рамку рисовала
                    // раскладка, а содержимое не перерисовывалось уже никогда.
                    // Место окна на экране спрашиваем у него самого: оно одно знает и про
                    // прокрутку, и про то, что у слоя лента не едет.
                    let place = self.wins[i].place(self.scroll_x);
                    let f = place.rect();
                    let tiled = self.wins[i].tiled();
                    let (b, _) = self.wins[i].deco();
                    let (want_w, want_h) = (self.wins[i].w + 2 * b, self.wins[i].h + 2 * b);
                    if self.overview && tiled {
                        // Веха 149.2 — В ОБЗОРЕ окно нарисовано не по `shown`, а по списку
                        // обзора (уменьшенным, со своей камерой), и помечать надо ЕГО
                        // прямоугольник. Прежний код помечал место окна в ленте, то есть чужое
                        // место на экране: клиент, перерисовавшийся при открытом обзоре, свой
                        // эскиз не обновлял. Нашлось типизацией координат — до неё оба
                        // прямоугольника были одинаковыми четвёрками чисел.
                        let id = self.wins[i].id;
                        if let Some(r) = self.ov.iter().find(|it| it.id == id).map(|it| it.r) {
                            self.damage(r);
                        }
                    } else if f.w != want_w || f.h != want_h {
                        // Окно в движении (растёт, едет) — его пиксели легли на экран
                        // масштабированными, и попасть в них прямоугольником клиента нельзя.
                        // Помечаем окно целиком: кадр анимации всё равно перерисовывает его.
                        self.damage(place);
                    } else {
                        // Прямоугольник приезжает в координатах БУФЕРА КЛИЕНТА, а на экран его
                        // пиксели легли растянутыми до размера содержимого окна
                        // (`bw × bh` → `cw × ch`, см. `draw_win_row`). Пока буфер не совпал с
                        // содержимым — а между `EV_RESIZE` и `OP_REBUF` так бывает у ЛЮБОГО
                        // клиента, — это две разные системы координат, и класть одну в другую
                        // как есть значит помечать не ту область.
                        //
                        // Так и выглядел артефакт `winbox` (он вовсе не перевыделял буфер):
                        // клиент перекрашивал кадр целиком, а на экране менялся левый верхний
                        // угол размером с его буфер. Остальное «чинилось» лишь тем, что рисуется
                        // само: пятно под курсором и полная перерисовка при обзоре или переезде.
                        let (cw, ch) = (self.wins[i].w, self.wins[i].h);
                        let (bw, bh) = (self.wins[i].bw.max(1), self.wins[i].bh.max(1));
                        let (rx, ry, rw, rh) = if bw == cw && bh == ch {
                            (dx, dy, dw.max(1), dh.max(1)) // масштаба нет — считать нечего
                        } else {
                            // Отображение целочисленное, поэтому края берём с запасом в пиксель:
                            // краевой столбец экрана может читать соседнюю колонку источника.
                            let x0 = (dx * cw / bw - 1).clamp(0, cw);
                            let y0 = (dy * ch / bh - 1).clamp(0, ch);
                            let x1 = (((dx + dw) * cw + bw - 1) / bw + 1).clamp(x0, cw);
                            let y1 = (((dy + dh) * ch + bh - 1) / bh + 1).clamp(y0, ch);
                            (x0, y0, (x1 - x0).max(1), (y1 - y0).max(1))
                        };
                        self.damage(At::new(f.x + b + rx, f.y + b + ry, rw, rh));
                    }
                }
            }
            // Неблокирующий опрос: у клиента свой реактор, спать в нашем вызове он не может.
            win::OP_POLL => {
                let id = body!(m, win::wire::id(req));
                let ev = self.wins.iter_mut().find(|w| w.id == id).and_then(|w| {
                    (!w.inbox.is_empty()).then(|| w.inbox.remove(0))
                });
                match ev {
                    Some(e) => reply_event(m.reply_cap, e),
                    None => {
                        sys::reply(m.reply_cap, &[]);
                    }
                }
            }
            win::OP_EVENT => {
                let r = body!(m, win::wire::EventReq::decode(req));
                let Some(i) = self.wins.iter().position(|w| w.id == r.id) else {
                    sys::reply(m.reply_cap, &[]);
                    return;
                };
                // ОЧЕРЕДЬ, а не стек: `pop` брал с конца, и набранное приезжало задом наперёд
                // (а при переполнении — вперемешку). Стоимость `remove(0)` при потолке в
                // сотни записей несущественна, а порядок ввода — свойство, которое нельзя терять.
                let first = if self.wins[i].inbox.is_empty() {
                    None
                } else {
                    Some(self.wins[i].inbox.remove(0))
                };
                match first {
                    // Есть накопленное — отвечаем сразу.
                    Some(e) => reply_event(m.reply_cap, e),
                    // Пусто — ответ ОТКЛАДЫВАЕТСЯ: клиент спит в `SYS_CALL`, как в чтении stdin.
                    None => {
                        self.wins[i].waiting = Some(m.reply_cap);
                        // Веха 140 — необязательный СРОК хвостом запроса: часам в баре надо
                        // проснуться через минуту, а минута — не событие. Нет хвоста — ждём
                        // бессрочно, как ждали все клиенты до бара.
                        self.wins[i].wait_until =
                            r.ms.map(|ms| sys::monotonic_ns() + ms as u64 * 1_000_000);
                    }
                }
            }
            // Веха 140 — СОСТОЯНИЕ рабочего места для бара: стол, сколько столов, заголовок окна
            // в фокусе. Заголовок здесь, а не в событии, потому что событие — семь байт.
            win::OP_STATUS => {
                let title = self
                    .focus
                    .and_then(|id| self.wins.iter().find(|w| w.id == id))
                    .map_or(&[][..], |w| w.title.as_bytes());
                let s = win::wire::Status {
                    space: self.space as u8,
                    spaces: self.space_count().min(255) as u8,
                    // Веха 143 — раскладка. Спрашивать её у ядра самой панели не годится:
                    // `SYS_KEYMAP` отвечает всем, но панель узнаёт об ИЗМЕНЕНИИ только от
                    // композитора, и два источника одного числа однажды разойдутся.
                    layout: sys::keymap().min(255) as u8,
                    // Веха 145 — идёт ли обзор. Панели это нужно не для вида: в обзоре мышь
                    // слоям не отдают вовсе, и открытое меню осталось бы на экране навсегда —
                    // закрывать его кликом было бы нечем.
                    overview: self.overview,
                    // Веха 168 — сколько уведомлений накопилось: по этому числу панель рисует
                    // счётчик у колокольчика.
                    dnd: self.dnd,
                    notes: self.notes.len().min(255) as u8,
                    title,
                };
                let mut rep = [0u8; 8 + win::TITLE_MAX];
                let n = s.encode(&mut rep);
                sys::reply(m.reply_cap, &rep[..n]);
            }
            // Веха 140 — подписка на `EV_STATUS`.
            win::OP_WATCH => {
                let id = body!(m, win::wire::id(req));
                if let Some(i) = self.wins.iter().position(|w| w.id == id) {
                    self.wins[i].watching = true;
                }
                sys::reply(m.reply_cap, &[]);
                // Первое состояние — сразу: иначе бар до первой смены стола показывал бы пустоту.
                if let Some(i) = self.wins.iter().position(|w| w.id == id) {
                    self.send(i, win::Event::Status);
                }
            }
            // Веха 144 — переключить раскладку (клик по буквам в баре). Тем же вызовом, что и
            // аккорд `Super+Z`: панели своего пути к раскладке не дано — экран не её.
            win::OP_LAYOUT => {
                sys::reply(m.reply_cap, &[]);
                if sys::keymap_next().is_none() {
                    sys::write_console("[wm] раскладку не переключить: экран не наш\n".as_bytes());
                }
            }
            // Веха 140 — переключить стол (клик по столу в баре). Тем же путём, что аккорд
            // `Super+N`: второй способ сделать то же самое разошёлся бы с первым.
            win::OP_SPACE => {
                let n = body!(m, win::wire::Rd::new(req).u8()) as usize;
                sys::reply(m.reply_cap, &[]);
                self.goto_space(n);
            }
            // Веха 147 — НАМЕРЕНИЕ ЗАПУСТИТЬ: место в ленте занимается сразу, до окна.
            win::OP_LAUNCHING => {
                // Чей это запуск, говорит ЯДРО (`m.sender`), а не запрос: назвать чужой номер
                // отсюда нельзя, а свой — не нужно. Плитка при этом заводится ДО `SYS_SPAWN`,
                // поэтому номера запускаемого ещё и не существует.
                let pid = m.sender;
                let name = core::str::from_utf8(req).unwrap_or("?");
                let id = self.next_id;
                self.next_id += 1;
                let now = sys::monotonic_ns();
                let win = Win {
                    id,
                    // Хозяин плитки — ТОТ, КТО ЗАПУСКАЕТ (сторож `run`), а не запускаемый: это
                    // он с нами говорит и он же умрёт, если запуск сорвётся вместе с ним.
                    owner: m.sender,
                    x: 0,
                    y: 0,
                    w: 480,
                    h: 320,
                    title: String::from(name),
                    buf: 0,
                    buf_len: 0,
                    cap: sys::NO_CAP,
                    slot: 0,
                    span: 0,
                    bw: 0,
                    bh: 0,
                    touched: Rect::ZERO,
                    waiting: None,
                    wait_until: None,
                    watching: false,
                    inbox: Vec::new(),
                    shown: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                    from: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                    to: Shown { x: 0, y: 0, w: 0, h: 0, a: 0 },
                    at: 0,
                    dur: 0,
                    fresh: true,
                    closing: false,
                    visible: true,
                    layer: None,
                    next: None,
                    launch: Some(Launch {
                        pid,
                        name: String::from(name),
                        since: now,
                        done: None,
                        drawn: None,
                        shot: false,
                    }),
                    run: None,
                    snap: None,
                    asked: false,
                    own: None,
                };
                self.wins.push(win);
                let at = if self.cols.is_empty() { 0 } else { self.cur + 1 };
                self.cols.insert(at, Column { ids: vec![id], width: 1, focus: 0 });
                self.cur = at;
                self.tidy_spaces();
                sys::reply(m.reply_cap, &id.to_le_bytes());
                self.sync_focus();
                self.relayout();
            }
            // Веха 147 — ЧЕМ КОНЧИЛОСЬ. Плитки нет — значит окно успело появиться, и говорить
            // тут не о чем: программа запустилась, а что она когда-нибудь завершится, экрану
            // сообщать незачем.
            win::OP_LAUNCH_DONE => {
                let pid = m.sender;
                let d = body!(m, win::wire::LaunchDone::decode(req));
                let (code, tail) = (d.code, core::str::from_utf8(d.tail).unwrap_or(""));
                sys::reply(m.reply_cap, &[]);
                if let Some(k) = self.wins.iter().position(|w| {
                    w.launch.as_ref().is_some_and(|l| l.pid == pid && l.done.is_none())
                }) {
                    if let Some(l) = &mut self.wins[k].launch {
                        l.done = Some((code, String::from(tail)));
                        l.drawn = None; // кадр устарел целиком
                    }
                }
            }
            // Веха 155 — «дай право, которое конфиг назначил мне». Копия уезжает УРЕЗАННОЙ маской
            // «чтение+запись»: смотреть и действовать — да, `GRANT` — нет. Иначе получивший мог
            // бы раздать право дальше, и объявление владельца перестало бы что-то значить со
            // второй передачи. Для обзора процессов остаётся `rw`, для выключения — `w`
            // (у самого права `power` чтения нет вовсе).
            // Веха 168 — СКАЗАТЬ ЧЕЛОВЕКУ. Имя отправителя берём У ЯДРА по номеру процесса, а
            // не из сообщения: написать себе чужое имя не должно быть возможно (тот же довод,
            // что у раздачи прав).
            win::OP_NOTIFY => {
                let body = &req[..m.len.min(req.len())];
                if body.len() < 2 {
                    sys::reply(m.reply_cap, &[]);
                    return;
                }
                let (level, tl) = (body[0], (body[1] as usize).min(body.len() - 2));
                let title = String::from_utf8_lossy(&body[2..2 + tl]).into_owned();
                let text = String::from_utf8_lossy(&body[2 + tl..]).into_owned();
                let from = self.proc_name(m.sender);
                self.post_note(level, &from, &title, &text);
                sys::reply(m.reply_cap, &[1]);
            }
            // Что накопилось — списком. Читает панель, когда открывает своё меню.
            win::OP_NOTES => {
                let mut rep: Vec<u8> = Vec::new();
                for n in &self.notes {
                    let (f, t, x) = (n.from.as_bytes(), n.title.as_bytes(), n.text.as_bytes());
                    if rep.len() + 8 + f.len() + t.len() + x.len() > NOTES_REPLY_MAX {
                        break;
                    }
                    rep.extend_from_slice(&n.id.to_le_bytes());
                    rep.push(n.level);
                    rep.push(f.len() as u8);
                    rep.push(t.len() as u8);
                    rep.push(x.len() as u8);
                    rep.extend_from_slice(f);
                    rep.extend_from_slice(t);
                    rep.extend_from_slice(x);
                }
                sys::reply(m.reply_cap, &rep);
            }
            // Убрать одно или всё.
            win::OP_NOTE_DROP => {
                let body = &req[..m.len.min(req.len())];
                let id = match body.get(..4) {
                    Some(b) => u32::from_le_bytes([b[0], b[1], b[2], b[3]]),
                    None => 0,
                };
                let was = self.notes.len();
                if id == 0 {
                    self.notes.clear();
                } else {
                    self.notes.retain(|n| n.id != id);
                }
                // Ушедшее уведомление не должно остаться всплывашкой на экране.
                if self.toast.is_some_and(|t| id == 0 || t.id == id) {
                    self.damage_toast();
                    self.toast = None;
                }
                sys::reply(m.reply_cap, &[(was - self.notes.len()).min(255) as u8]);
            }
            // Веха 168.3 — счёт кадров ЭКРАНА. Отдаём как есть, без сглаживания: сгладить
            // рывок значит его спрятать, а ищут именно его.
            win::OP_FRAMES => {
                // Непустое тело — СБРОС: замер начинается с чистого кольца, иначе в него попадёт
                // всё, что человек делал до того, как решил померить.
                if m.len > 0 && !req.is_empty() {
                    self.frames = Frames::new();
                    sys::reply(m.reply_cap, &[]);
                    return;
                }
                let rep = self.frames.encode(self.info.width as u32, self.info.height as u32);
                sys::reply(m.reply_cap, &rep);
            }
            // Веха 168.1 — «не беспокоить». Пустое тело — только спросить.
            win::OP_NOTE_DND => {
                let body = &req[..m.len.min(req.len())];
                if let Some(&v) = body.first() {
                    self.dnd = v != 0;
                    // Включили — гасим то, что висит сейчас: просьба не отвлекать начинает
                    // действовать сразу, а не со следующего уведомления.
                    if self.dnd && self.toast.is_some() {
                        self.damage_toast();
                        self.toast = None;
                    }
                }
                sys::reply(m.reply_cap, &[self.dnd as u8]);
            }
            win::OP_GRANT => {
                let kind = body!(m, win::wire::Rd::new(req).u8());
                let cap = self.grant_for(m.sender, kind);
                // Маска — ПО ВИДУ права, а не одна на всех. Общая `rw` годилась, пока раздавались
                // обзор (`rw`) и выключение (`w`); эндпоинт же действует правом `SEND`, и та же
                // маска срезала бы ему всё — уезжал бы дескриптор без единого бита, а отказ
                // всплывал бы уже у получателя, на первом вызове. `GRANT` не входит ни в одну:
                // раздать дальше нельзя, иначе объявление владельца перестаёт что-то значить.
                let mask: u32 = match kind {
                    4 => 0x08,        // эндпоинт: только отправка
                    10 => 0x02,       // выключение: только действие (чтения у него нет вовсе)
                    _ => 0x01 | 0x02, // обзор: смотреть и управлять
                };
                sys::reply_granting(m.reply_cap, &[], cap, mask);
            }
            win::OP_DESTROY => {
                let id = body!(m, win::wire::id(req));
                sys::reply(m.reply_cap, &[]);
                if let Some(k) = self.win_at(id) {
                    // Веха 169 — уход СЛОЯ раскладку не трогает, и спрашивать её незачем.
                    //
                    // Слоя нет в ленте: он не занимает колонки, не двигает соседей и фокуса не
                    // держит. А `relayout` кончается пометкой ВСЕГО ЭКРАНА — то есть каждое
                    // закрытие строки запуска стоило пересборки миллиона точек ровно в тот миг,
                    // когда карточка досворачивалась. Зону (если она была) пересчитает
                    // [`Wm::begin_close`] — там `recompute_work`, и он позовёт раскладку сам,
                    // но только если место у ленты действительно изменилось.
                    let layer = self.wins[k].layer.is_some();
                    self.begin_close(id);
                    if !layer {
                        self.sync_focus();
                        self.relayout();
                    }
                }
            }
            // Чужой запрос — ответить пусто, а не молчать: молчание повесило бы вызвавшего.
            _ => {
                let _ = m.sender;
                sys::reply(m.reply_cap, &[]);
            }
        }
    }
}

// ── рисование плитки запуска (Веха 147) ────────────────────────────────────────────────
//
// Текста композитор до этой вехи не рисовал вовсе: заголовок окна он хранит, но показывает его
// панель. Плитка — первое, что он обязан сказать словами, и берёт она растровый шрифт 8×16 из
// таблицы ядра ([`sys::glyph`], тот же, что у панели).
//
// Веха 148.3 — пиксели пишет `ui::Canvas`, цвета приходят из `ui::Theme`. Здесь стояла оговорка
// «тулкит сюда не тянем: void-ui живёт в клиентах, а композитор не клиент самому себе», и верна
// она ровно наполовину: `Ui` с виджетами и `app` с циклом ему правда не нужны, а холст и палитра
// нужны — своя копия обоих обошлась в четвёртый способ писать пиксель и вторую палитру,
// разошедшуюся с первой. ШРИФТ остаётся кернельный: `ui::Font` — это загрузка TTF из store, то
// есть умение, которого у держателя всех оконных буферов быть не должно.

/// Сколько плитка «бежит». Дальше полоса замирает и надпись говорит правду: «дольше обычного».
/// Врать процентами нечем — мы не знаем ни сколько осталось, ни сколько всего.
const LAUNCH_ANIM_NS: u64 = 10_000_000_000;

/// Залить прямоугольник плитки. Холст сам режет по краю и сам пишет альфу.
fn tile_fill(c: &mut ui::Canvas, r: Rect, col: Rgba) {
    c.fill(r, col.with_a(0xff));
}

/// Написать строку шрифтом 8×16 с увеличением `scale`. Возвращает ширину написанного.
///
/// Обрезка — по КРАЮ ПЛИТКИ, а не по числу знаков: строка вывода умершей программы может быть
/// какой угодно длины, и считать её длину заранее значило бы завести вторую истину о том, что
/// поместилось.
fn tile_text(c: &mut ui::Canvas, x: i32, y: i32, s: &str, col: Rgba, scale: i32) -> i32 {
    let bw = c.w;
    let mut cx = x;
    for ch in s.chars() {
        let rows = sys::glyph::rows(ch);
        for (ry, bits) in rows.iter().enumerate() {
            for bit in 0..8 {
                if bits & (0x80 >> bit) == 0 {
                    continue;
                }
                tile_fill(c, Rect::new(cx + bit * scale, y + ry as i32 * scale, scale, scale), col);
            }
        }
        cx += 8 * scale;
        if cx >= bw {
            break;
        }
    }
    cx - x
}

/// Написать строку ПО ЦЕНТРУ плитки.
fn tile_center(c: &mut ui::Canvas, y: i32, s: &str, col: Rgba, scale: i32) {
    let w = s.chars().count() as i32 * 8 * scale;
    tile_text(c, (c.w - w) / 2, y, s, col, scale);
}

/// Весь кадр плитки: «запускается» с бегунком либо итог с кодом выхода и хвостом вывода.
fn draw_tile(px: &mut [u8], bw: i32, bh: i32, l: &Launch, phase: u32, now: u64, th: &Theme) {
    let c = &mut ui::Canvas::new(px, bw, bh);
    tile_fill(c, Rect::new(0, 0, bw, bh), th.bg);
    match &l.done {
        // ── ждём окна ──────────────────────────────────────────────────────────────────
        None => {
            let long = now.saturating_sub(l.since) >= LAUNCH_ANIM_NS;
            let y = bh / 2 - 34;
            tile_center(c, y, ui::t("ЗАПУСКАЕТСЯ"), th.muted, 1);
            tile_center(c, y + 24, &l.name, th.text, 2);
            // Дорожка и бегунок. Проценты не рисуем и не выдумываем: мы не знаем ни сколько
            // осталось, ни сколько всего, — знаем только, что ещё ждём.
            let track = (bw / 6).max(40).min(bw / 2);
            let (tx, ty) = ((bw - track) / 2, y + 64);
            tile_fill(c, Rect::new(tx, ty, track, 4), th.border);
            if long {
                // Срок вышел: полоса замирает целиком, а словами говорим правду.
                tile_fill(c, Rect::new(tx, ty, track, 4), th.muted);
                tile_center(c, ty + 14, ui::t("дольше обычного — окна всё нет"), th.muted, 1);
            } else {
                let run = (track / 4).max(8);
                // Челнок туда-обратно: бесконечная лента вправо выглядит как «загрузка идёт»,
                // а мы не знаем, идёт ли она.
                let span = (track - run).max(1);
                let p = (phase as i32) % (2 * span);
                let off = if p < span { p } else { 2 * span - p };
                tile_fill(c, Rect::new(tx + off, ty, run, 4), th.accent);
            }
        }
        // ── всё кончилось, а окна не было ──────────────────────────────────────────────
        Some((code, tail)) => {
            let bad = *code != 0;
            let head = if bad { ui::t("НЕ ЗАПУСТИЛОСЬ") } else { ui::t("ЗАВЕРШИЛОСЬ БЕЗ ОКНА") };
            let pad = 14;
            tile_text(c, pad, pad, head, if bad { th.danger } else { th.muted }, 1);
            tile_text(c, pad, pad + 22, &l.name, th.text, 2);
            let code_line = ui::f1(ui::t("код выхода {}"), &alloc::format!("{code}"));
            tile_text(c, pad, pad + 56, &code_line, th.muted, 1);
            tile_fill(c, Rect::new(pad, pad + 78, bw - 2 * pad, 1), th.border);
            // Вывод — ПОСЛЕДНИЕ строки: смерть объясняют они, а не первые. Пустой вывод не
            // прячем за молчанием, а называем: «программа не сказала ничего» — это тоже ответ.
            let mut y = pad + 88;
            // Длинные строки ПЕРЕНОСИМ, а не обрезаем: обрезка съедает как раз конец сообщения
            // об ошибке, то есть то место, ради которого карточку и читают.
            let cols = (((bw - 2 * pad) / 8).max(8)) as usize;
            let mut lines: Vec<&str> = Vec::new();
            for line in tail.lines().filter(|s| !s.trim().is_empty()) {
                let mut rest = line;
                while rest.chars().count() > cols {
                    // Режем по границе СИМВОЛА: строка приезжает от чужой программы, и байтовая
                    // граница развалила бы кириллицу пополам.
                    let cut = rest.char_indices().nth(cols).map_or(rest.len(), |(i, _)| i);
                    let (head, tail_) = rest.split_at(cut);
                    lines.push(head);
                    rest = tail_;
                }
                lines.push(rest);
            }
            let fit = ((bh - y - pad) / 18).max(0) as usize;
            if lines.is_empty() {
                tile_text(c, pad, y, ui::t("вывода не было"), th.muted, 1);
            }
            for line in lines.iter().skip(lines.len().saturating_sub(fit)) {
                tile_text(c, pad, y, line, th.text, 1);
                y += 18;
            }
            tile_text(c, pad, bh - pad - 16, ui::t("Super+Q — убрать"), th.muted, 1);
        }
    }
}

/// Курсор — тот же, что в `term` (Веха 115): контур плюс тело.
const CUR_W: i32 = 12;
const CUR_H: i32 = 19;

/// Поля ярлыка перетаскивания вокруг подписи (Веха 150.1).
const BADGE_PAD_X: i32 = 6;
const BADGE_PAD_Y: i32 = 4;
/// Сколько знаков подписи помещаем на ярлык. Дальше — многоточие: ярлык едет за курсором по
/// всему экрану, и подпись во всю ширину закрывала бы как раз то окно, в которое целятся.
const BADGE_CHARS: usize = 32;
const CURSOR: [&str; 19] = [
    "#           ",
    "##          ",
    "#.#         ",
    "#..#        ",
    "#...#       ",
    "#....#      ",
    "#.....#     ",
    "#......#    ",
    "#.......#   ",
    "#........#  ",
    "#.....##### ",
    "#..#..#     ",
    "#.# #..#    ",
    "##  #..#    ",
    "#    #..#   ",
    "     #..#   ",
    "      #.#   ",
    "      ###   ",
    "            ",
];

/// Барьер записи: пачки write-combining не должны залёживаться (Веха 116.1).
#[cfg(target_arch = "x86_64")]
fn fence() {
    unsafe { core::arch::asm!("sfence", options(nostack, preserves_flags)) };
}
#[cfg(not(target_arch = "x86_64"))]
fn fence() {}


#[no_mangle]
pub extern "C" fn _start(_a0: usize, _a1: usize) -> ! {
    main_loop()
}

/// Право на экран: по имени, иначе перебором стартовых (как в `term`).
fn find_fb_cap() -> Option<usize> {
    sys::cap_named("FB")
        .filter(|&c| sys::video_info(c).is_some())
        .or_else(|| {
            (0..8)
                .map(sys::start_cap)
                .find(|&c| c != sys::NO_CAP && sys::video_info(c).is_some())
        })
}

/// Право на store (нужно и для чтения буферов, и для запуска клиентов).
fn store_cap() -> usize {
    sys::cap_named("STORE").unwrap_or_else(|| sys::start_cap(1))
}
